span{font-size:14px;color:rgba(255,255,255,.85);line-height:1.4}\\n.pxt-enj{display:grid;grid-template-columns:repeat(3,1fr);gap:0;border-top:1px solid var(--b);margin-top:36px}\\n.pxt-enj>div{padding:34px 30px 30px;border-right:1px solid var(--b);position:relative;transition:background .3s}\\n.pxt-enj>div:last-child{border-right:0}\\n.pxt-enj>div::before{content:\\"\\";position:absolute;left:0;top:-1px;height:3px;width:0;background:var(--c);transition:width .5s}\\n.pxt-enj>div:hover{background:#F6FAFC}.pxt-enj>div:hover::before{width:100%}\\n.pxt-enj i{display:block;font-style:normal;font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:76px;line-height:1;color:transparent;-webkit-text-stroke:1.5px var(--p);margin-bottom:18px}\\n.pxt-enj h3{font-size:20px;margin-bottom:10px}\\n.pxt-enj p{font-size:15px!important;color:var(--m)}\\n.pxt-enj .pxt-link{margin-top:6px;font-size:14.5px}\\n.pxt-dark{background:radial-gradient(circle at 0% 0%,rgba(1,205,243,.14),transparent 40%),var(--n);color:rgba(255,255,255,.8)}\\n.pxt-dark h2,.pxt-dark h3{color:#fff}.pxt-dark .pxt-k{color:var(--c)}.pxt-dark .pxt-lead{color:rgba(255,255,255,.72)}\\n.pxt-tabs{display:grid;grid-template-columns:330px 1fr;gap:28px;margin-top:36px;align-items:stretch}\\n.pxt-tabs>input{position:absolute;opacity:0;pointer-events:none}\\n.pxt-tabs__nav{display:grid;gap:8px;align-content:start}\\n.pxt-tabs__nav label{display:flex;align-items:center;gap:14px;cursor:pointer;padding:16px 18px;border-radius:12px;border:1px solid rgba(255,255,255,.14);color:rgba(255,255,255,.85);font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:16px;transition:all .25s}\\n.pxt-tabs__nav label i{font-style:normal;font-size:12px;font-weight:800;color:var(--c);width:26px}\\n.pxt-tabs__nav label:hover{background:rgba(255,255,255,.06)}\\n.pxt-tabs__panels{position:relative;min-height:400px}\\n.pxt-panel{display:none;grid-template-columns:1fr 1fr;border-radius:20px;overflow:hidden;background:#fff;height:100%;animation:pxtFade .4s ease}\\n.pxt-panel figure{margin:0;position:relative;min-height:400px}.pxt-panel figure img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\\n.pxt-panel>div{padding:34px 34px 30px;display:flex;flex-direction:column;justify-content:center}\\n.pxt-panel h3{color:var(--n)!important;font-size:24px;margin-bottom:12px}\\n.pxt-panel p{color:#3E5163;font-size:15.5px!important}\\n.pxt-panel .pxt-note{font-size:13px!important;color:var(--m);background:#F2F6F9;border-radius:8px;padding:10px 12px}\\n@keyframes pxtFade{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}\\n.pxt-tabs>input:nth-of-type(1):checked~.pxt-tabs__panels .pxt-panel:nth-child(1),.pxt-tabs>input:nth-of-type(2):checked~.pxt-tabs__panels .pxt-panel:nth-child(2),.pxt-tabs>input:nth-of-type(3):checked~.pxt-tabs__panels .pxt-panel:nth-child(3),.pxt-tabs>input:nth-of-type(4):checked~.pxt-tabs__panels .pxt-panel:nth-child(4),.pxt-tabs>input:nth-of-type(5):checked~.pxt-tabs__panels .pxt-panel:nth-child(5){display:grid}\\n.pxt-tabs>input:nth-of-type(1):checked~.pxt-tabs__nav label:nth-of-type(1),.pxt-tabs>input:nth-of-type(2):checked~.pxt-tabs__nav label:nth-of-type(2),.pxt-tabs>input:nth-of-type(3):checked~.pxt-tabs__nav label:nth-of-type(3),.pxt-tabs>input:nth-of-type(4):checked~.pxt-tabs__nav label:nth-of-type(4),.pxt-tabs>input:nth-of-type(5):checked~.pxt-tabs__nav label:nth-of-type(5){background:var(--c);border-color:var(--c);color:var(--n)}\\n.pxt-tabs>input:nth-of-type(1):checked~.pxt-tabs__nav label:nth-of-type(1) i,.pxt-tabs>input:nth-of-type(2):checked~.pxt-tabs__nav label:nth-of-type(2) i,.pxt-tabs>input:nth-of-type(3):checked~.pxt-tabs__nav label:nth-of-type(3) i,.pxt-tabs>input:nth-of-type(4):checked~.pxt-tabs__nav label:nth-of-type(4) i,.pxt-tabs>input:nth-of-type(5):checked~.pxt-tabs__nav label:nth-of-type(5) i{color:var(--n)}\\n.pxt-split{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}\\n.pxt-bars{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;align-items:end;height:300px;padding:0 6px;border-bottom:2px solid var(--b)}\\n.pxt-bar{position:relative;border-radius:12px 12px 0 0;background:linear-gradient(180deg,#9DB4C3,#C7D4DD);display:flex;flex-direction:column;justify-content:flex-start;align-items:center;padding-top:14px;color:#fff;font-family:Sora,system-ui,sans-serif;font-weight:700}\\n.pxt-bar b{font-size:22px}\\n.pxt-bar--on{background:linear-gradient(180deg,var(--c),var(--p))}.pxt-bar--on b{color:var(--n)}\\n.pxt-bar--nv{background:linear-gradient(180deg,#0E4A73,var(--n))}\\n.pxt-bars__x{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;padding:10px 6px 0;text-align:center;font-family:Sora,system-ui,sans-serif;font-weight:600;color:var(--n);font-size:15px}\\n.pxt-bars__x small{display:block;font-family:Figtree,system-ui,sans-serif;font-weight:500;color:var(--m);font-size:12.5px}\\n.pxt-big{font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:clamp(70px,9vw,130px);line-height:.95;color:transparent;-webkit-text-stroke:2px var(--p);letter-spacing:-.03em}\\n.pxt-big+span{display:block;font-family:Sora,system-ui,sans-serif;font-weight:600;color:var(--n);font-size:20px;margin-top:8px}\\n.pxt-duo{display:grid;grid-template-columns:1fr 64px 1fr;align-items:stretch;margin-top:32px}\\n.pxt-duo>div{border-radius:18px;padding:30px}\\n.pxt-duo__a{background:#fff;border:1px solid var(--b)}\\n.pxt-duo__b{background:var(--n);color:rgba(255,255,255,.82)}.pxt-duo__b h3{color:#fff!important}\\n.pxt-duo__x{display:grid;place-items:center}.pxt-duo__x span{width:52px;height:52px;border-radius:50%;background:var(--c);color:var(--n);display:grid;place-items:center;font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:20px;box-shadow:0 0 0 8px #fff}\\n.pxt-duo .pxt-ico{width:46px;height:46px;border-radius:12px;display:grid;place-items:center;font-size:18px;background:#E3F7FC;color:var(--pd);margin-bottom:14px}\\n.pxt-duo__b .pxt-ico{background:rgba(1,205,243,.14);color:var(--c)}\\n.pxt-duo h3{font-size:20px;margin-bottom:8px}\\n.pxt-vs{position:relative;display:grid;gap:14px;counter-reset:s}\\n.pxt-vs::before{content:\\"\\";position:absolute;left:27px;top:20px;bottom:20px;width:2px;background:linear-gradient(180deg,var(--c),rgba(1,205,243,.15))}\\n.pxt-vs>div{position:relative;display:grid;grid-template-columns:56px 1fr;gap:18px;align-items:center}\\n.pxt-vs>div::before{counter-increment:s;content:counter(s,decimal-leading-zero);width:56px;height:56px;border-radius:50%;background:#fff;border:2px solid var(--c);display:grid;place-items:center;font-family:Sora,system-ui,sans-serif;font-weight:700;color:var(--n);z-index:1}\\n.pxt-vs>div>div{background:#fff;border:1px solid var(--b);border-radius:14px;padding:16px 20px;font-size:15.5px;color:var(--n);box-shadow:0 8px 20px rgba(8,45,74,.05)}\\n.pxt-dark .pxt-vs>div::before{background:var(--n);color:#fff}\\n.pxt-dark .pxt-vs>div>div{background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.14);color:#fff}\\n.pxt-groups{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:32px}\\n.pxt-group{background:#fff;border:1px solid var(--b);border-radius:16px;padding:20px 20px 16px;transition:transform .2s,border-color .2s}\\n.pxt-group:hover{transform:translateY(-3px);border-color:var(--c)}\\n.pxt-group h3{font-size:16px;display:flex;align-items:center;gap:10px;margin-bottom:12px}\\n.pxt-group h3 span{width:34px;height:34px;border-radius:10px;background:#E3F7FC;color:var(--pd);display:grid;place-items:center;font-size:14px}\\n.pxt-group ul{list-style:none;padding:0;margin:0;display:grid;gap:10px}\\n.pxt-group li{display:grid;gap:4px;font-size:14.5px;color:var(--n);padding-top:10px;border-top:1px dashed var(--b)}\\n.pxt-group li:first-child{border-top:0;padding-top:0}\\n.pxt-group--wide{grid-column:span 2}\\n.pxt-mos{display:grid;grid-template-columns:1.4fr 1fr;grid-auto-rows:220px;gap:16px;margin-top:32px}\\n.pxt-mos a{position:relative;border-radius:18px;overflow:hidden;display:block;text-decoration:none!important}\\n.pxt-mos a:first-child{grid-row:span 2}\\n.pxt-mos img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .6s}\\n.pxt-mos a:hover img{transform:scale(1.05)}\\n.pxt-mos a::after{content:\\"\\";position:absolute;inset:0;background:linear-gradient(180deg,rgba(8,45,74,0) 35%,rgba(8,45,74,.92))}\\n.pxt-mos a>div{position:absolute;z-index:1;left:22px;right:22px;bottom:20px;color:#fff}\\n.pxt-mos small{display:block;font-size:11.5px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--c);margin-bottom:6px}\\n.pxt-mos b{font-family:Sora,system-ui,sans-serif;font-size:20px;line-height:1.25;font-weight:600}\\n.pxt-mos a:first-child b{font-size:26px}\\n.pxt-mos--1{grid-template-columns:1fr;grid-auto-rows:340px}\\n.pxt-band{position:relative;overflow:hidden;border-radius:24px;min-height:300px;display:grid;place-items:center;text-align:center;color:#fff;padding:56px 24px}\\n.pxt-band img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\\n.pxt-band::before{content:\\"\\";position:absolute;inset:0;z-index:1;background:linear-gradient(120deg,rgba(8,45,74,.95),rgba(8,45,74,.7) 60%,rgba(0,118,154,.75))}\\n.pxt-band>div{position:relative;z-index:2;max-width:760px}\\n.pxt-band h2{color:#fff;margin:12px 0 10px}.pxt-band p{color:rgba(255,255,255,.82)}\\n.pxt-band .pxt-k{color:var(--c)}.pxt-band .pxt-hero__act{justify-content:center}\\n.pxt-checks{list-style:none;padding:0;margin:14px 0 0;display:grid;gap:10px}\\n.pxt-checks li{display:flex;gap:12px;font-size:15.5px;color:var(--n);line-height:1.5}\\n.pxt-checks li::before{content:\\"\\";flex:0 0 10px;height:10px;margin-top:7px;border-radius:2px;background:var(--c);transform:rotate(45deg)}\\n.pxt-dark .pxt-checks li{color:#fff}\\n.px-section:has(.pxt-hero),.px-block-typo:has(.pxt-hero){margin-top:0!important;padding-top:0!important}\\n@supports (animation-timeline:view()){.pxt-rv{animation:pxtIn linear both;animation-timeline:view();animation-range:entry 0% entry 35%}@keyframes pxtIn{from{opacity:0;transform:translateY(30px)}to{opacity:1;transform:none}}}\\n@media(prefers-reduced-motion:reduce){.pxt-rv{animation:none!important}}\\n@media(max-width:991px){.pxt-hero .pxt-c{grid-template-columns:1fr;padding-top:120px}.pxt-enj{grid-template-columns:1fr}.pxt-enj>div{border-right:0;border-bottom:1px solid var(--b)}.pxt-tabs{grid-template-columns:1fr}.pxt-tabs__nav{grid-auto-flow:column;grid-auto-columns:max-content;overflow-x:auto}.pxt-panel{grid-template-columns:1fr}.pxt-panel figure{min-height:220px}.pxt-split{grid-template-columns:1fr;gap:36px}.pxt-duo{grid-template-columns:1fr;gap:12px}.pxt-duo__x{display:none}.pxt-groups{grid-template-columns:1fr 1fr}.pxt-mos{grid-template-columns:1fr}.pxt-mos a:first-child{grid-row:auto}}\\n@media(max-width:575px){.pxt-groups{grid-template-columns:1fr}.pxt-group--wide{grid-column:auto}.pxt-sec{padding:52px 0}}\\n/* pleine largeur */.pxs-sec,.pxt-sec,.pxt-hero{width:100vw!important;margin-left:calc(50% - 50vw)!important;margin-right:0!important}body{overflow-x:clip}\\n/* Manifeste PEXEN */\\n.pxt-manif-sec{background:radial-gradient(circle at 90% 20%,rgba(1,205,243,.12),transparent 40%),#fff;border-top:1px solid var(--b)}\\n.pxt-manif{display:grid;grid-template-columns:7fr 5fr;gap:56px;align-items:center}\\n.pxt-manif__t{font-family:Sora,system-ui,sans-serif!important;font-weight:800;font-size:clamp(40px,5.2vw,80px)!important;line-height:.98!important;letter-spacing:-.035em;color:var(--n)!important;margin:0!important}\\n.pxt-manif__t span{display:block;color:transparent;-webkit-text-stroke:2px var(--p)}\\n.pxt-manif__m{border-left:3px solid var(--c);padding-left:28px}\\n.pxt-manif__m p{font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:clamp(18px,1.5vw,22px)!important;line-height:1.45!important;color:var(--n)!important;margin:12px 0 16px!important}\\n.pxt-dark .pxt-manif__t{color:#fff!important}\\n@media(max-width:991px){.pxt-manif{grid-template-columns:1fr;gap:28px}}\\n/* ===== /pxt ===== */</style>\\n<style>:is(#pexen-compact,main) section:has(.px-ultra-faq-item){padding-bottom:36px!important}</style>"}, "type": "html", "style": {"paddingTop": "none", "paddingBottom": "none"}}]	{"slug": "efficacite-energetique-industrielle", "noindex": false, "nofollow": false, "seoTitle": "Efficacité énergétique industrielle : froid, chaleur | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "efficacité énergétique industrielle", "metaDescription": "Efficacité énergétique industrielle : froid process, chaleur fatale, vapeur, calorifugeage. Études et travaux sans arrêt de production, fiches CEE IND-UT."}	16	2026-10-21 12:43:13.022+02	\N	2026-10-21 12:43:13.022+02	2026-11-11 19:18:01.639+01	\N
page-yexaejjt	/secteurs/renovation-energetique-copropriete/	Bâtiments collectifs	published	cms	default	[{"id": "b-pxt-0", "data": {"html": "<div class=\\"pxt\\"><section class=\\"pxt-hero\\" data-word=\\"COLLECTIFS\\"><figure class=\\"pxt-hero__bg\\"><img src=\\"/themes/ultra-s/images/pexen/chaufferie-de-batiments-collectifs-modernisee-par-pexen.webp\\" alt=\\"Chaufferie de bâtiments collectifs modernisée par PEXEN\\" loading=\\"eager\\"></figure><div class=\\"pxt-c\\"><div><div class=\\"pxt-crumbs\\"><a href=\\"/\\">Accueil</a> › <a href=\\"/secteurs/\\">Secteurs</a> › Bâtiments collectifs</div><span class=\\"pxt-k\\">Bâtiments collectifs</span><h1>Performance énergétique des bâtiments collectifs</h1><p class=\\"pxt-hero__sub\\">Des charges maîtrisées, un confort tenu, un dossier prêt pour la décision.</p><p class=\\"pxt-hero__desc\\">Syndics, gestionnaires de patrimoine : dans les bâtiments collectifs, la chaufferie concentre l'essentiel des consommations et des charges. PEXEN la modernise, remplace le fioul par des pompes à chaleur et équilibre les réseaux.</p><div class=\\"pxt-hero__act\\"><a class=\\"pxt-btn\\" href=\\"/contact/\\">Parler de votre projet <span class=\\"fa fa-arrow-right\\"></span></a><a class=\\"pxt-btn pxt-btn--ghost\\" href=\\"/simulateur-prime-cee/\\">Estimer le financement</a></div></div>\\n<div class=\\"pxt-figs\\"><div class=\\"pxt-fig\\"><b>2026</b><span>toutes les copropriétés concernées par le projet de plan pluriannuel de travaux</span></div><div class=\\"pxt-fig\\"><b>1er poste</b><span>de charges récupérables : chauffage et eau chaude collectifs</span></div><div class=\\"pxt-fig\\"><b>RGE</b><span>installateur QualiPAC</span></div></div></div></section>\\n<section class=\\"pxt-sec\\"><div class=\\"pxt-c\\"><div class=\\"pxt-rv\\"><span class=\\"pxt-k\\">Vos enjeux</span><h2>Vos enjeux de gestionnaire</h2></div>\\n<div class=\\"pxt-enj pxt-rv\\"><div><i>01</i><h3>Les charges des occupants</h3><p>Le chauffage et l'eau chaude collectifs sont le premier poste de charges récupérables.</p></div><div><i>02</i><h3>Des chaufferies vieillissantes</h3><p>Chaudières fioul ou gaz hors condensation, réseaux non isolés, régulation figée.</p></div><div><i>03</i><h3>Une décision collective</h3><p>Un projet se vote en assemblée générale ou passe en comité d'engagement : il exige un dossier clair.</p></div></div></div></section>\\n<section class=\\"pxt-sec\\" style=\\"background:#F4F7FA\\"><div class=\\"pxt-c\\"><div class=\\"pxt-split\\"><div class=\\"pxt-rv\\"><div class=\\"pxt-big\\">2026</div><span>Toutes les copropriétés sont désormais concernées</span></div>\\n<div class=\\"pxt-rv\\"><span class=\\"pxt-k\\">Obligations</span><h2>Les obligations des copropriétés</h2><p>Les copropriétés de plus de 15 ans doivent disposer d'un projet de plan pluriannuel de travaux et d'un diagnostic de performance énergétique collectif. Depuis le 1er janvier 2026, toutes les copropriétés sont concernées.</p><p>Ces documents chiffrent les travaux ; notre étude les traduit en scénarios finançables.</p></div></div></div></section>\\n<section class=\\"pxt-sec pxt-dark\\"><div class=\\"pxt-c\\"><div class=\\"pxt-rv\\"><span class=\\"pxt-k\\">Nos solutions</span><h2>Nos solutions pour les bâtiments collectifs</h2></div><div class=\\"pxt-tabs pxt-rv\\"><input type=\\"radio\\" name=\\"pxt-so\\" id=\\"so0\\" checked><input type=\\"radio\\" name=\\"pxt-so\\" id=\\"so1\\"><input type=\\"radio\\" name=\\"pxt-so\\" id=\\"so2\\"><div class=\\"pxt-tabs__nav\\"><label for=\\"so0\\"><i>01</i>Sortie du fioul et du gaz</label><label for=\\"so1\\"><i>02</i>Équilibrage et régulation des réseaux</label><label for=\\"so2\\"><i>03</i>Isolation thermique en chaufferie</label></div><div class=\\"pxt-tabs__panels\\"><div class=\\"pxt-panel\\"><figure><img src=\\"/images/pompes-a-chaleur-toiture.webp\\" alt=\\"Pompes à chaleur en toiture\\" loading=\\"lazy\\"></figure><div><span class=\\"pxt-k\\">Solution 01</span><h3 style=\\"margin-top:12px\\">Sortie du fioul et du gaz</h3><p>Pompes à chaleur collectives et géothermie, bonifiées par l'État en cas de dépose d'une chaudière fossile. PEXEN est installateur RGE QualiPAC.</p><p><a class=\\"pxt-link\\" href=\\"/solutions/pompe-a-chaleur-tertiaire/\\">Chauffage et traitement d’air <span class=\\"fa fa-arrow-right\\"></span></a></p></div></div><div class=\\"pxt-panel\\"><figure><img src=\\"/uploads/pexen-mesure-debit-reseau-8324db2a.webp\\" alt=\\"Mesure de débit sur un réseau de chauffage\\" loading=\\"lazy\\"></figure><div><span class=\\"pxt-k\\">Solution 02</span><h3 style=\\"margin-top:12px\\">Équilibrage et régulation des réseaux</h3><p>Les logements éloignés de la chaufferie atteignent la consigne sans surchauffer les autres.</p><p><span class=\\"pxt-tag\\">Opération standardisée BAR-SE-104</span></p></div></div><div class=\\"pxt-panel\\"><figure><img src=\\"/themes/ultra-s/images/pexen/isolation-technique-calorifugeage-pexen.webp\\" alt=\\"Calorifugeage de réseaux en chaufferie\\" loading=\\"lazy\\"></figure><div><span class=\\"pxt-k\\">Solution 03</span><h3 style=\\"margin-top:12px\\">Isolation thermique en chaufferie</h3><p>Calorifugeage des réseaux, matelas isolants sur vannes et échangeurs.</p><p><a class=\\"pxt-link\\" href=\\"/solutions/isolation-technique/\\">Isolation thermique <span class=\\"fa fa-arrow-right\\"></span></a></p></div></div></div></div></div></section>\\n<section class=\\"pxt-sec\\"><div class=\\"pxt-c\\"><div class=\\"pxt-split\\"><div class=\\"pxt-rv\\"><span class=\\"pxt-k\\">Étapes</span><h2>Sortir du fioul en chaufferie collective</h2><p class=\\"pxt-lead\\">Cinq étapes, du relevé à la première saison de chauffe, avec un dossier prêt pour le vote.</p><a class=\\"pxt-btn\\" href=\\"/contact/?demande=etude\\" style=\\"margin-top:12px\\">Demander une étude <span class=\\"fa fa-arrow-right\\"></span></a></div>\\n<div class=\\"pxt-vs pxt-rv\\"><div><div>Relevé des consommations, de la puissance installée et des températures de départ.</div></div><div><div>Scénarios : pompe à chaleur seule, hybride avec appoint, géothermie.</div></div><div><div>Dossier pour l'assemblée générale ou le comité d'engagement, plan de financement inclus.</div></div><div><div>Travaux hors saison de chauffe ou avec production provisoire.</div></div><div><div>Réglage, équilibrage et suivi de la première saison.</div></div></div></div></div></section>\\n<section class=\\"pxt-sec\\" style=\\"background:#F4F7FA\\"><div class=\\"pxt-c\\"><div class=\\"pxt-rv\\" style=\\"text-align:center;max-width:780px;margin:0 auto\\"><span class=\\"pxt-k\\">Interlocuteurs</span><h2>Un dossier adapté à chaque gestionnaire</h2></div>\\n<div class=\\"pxt-duo pxt-rv\\"><div class=\\"pxt-duo__a\\"><span class=\\"pxt-ico fa fa-users\\"></span><h3>Pour un syndic</h3><p>Nous préparons les éléments que le conseil syndical présentera en assemblée générale.</p></div><div class=\\"pxt-duo__x\\"><span>&amp;</span></div><div class=\\"pxt-duo__b\\"><span class=\\"pxt-ico fa fa-chart-line\\"></span><h3>Pour un gestionnaire</h3><p>Nous suivons les consommations après travaux et ajustons les réglages de la chaufferie.</p></div></div></div></section></div>"}, "type": "html", "style": {"background": "white", "paddingTop": "none", "paddingBottom": "none"}}, {"id": "b-3e85689a", "data": {"items": [{"id": "f-jnu6vnjp", "answer": "<p>Oui. Le remplacement d'une production de chaleur se planifie hors saison de chauffe ou avec une solution provisoire.</p>", "question": "Les travaux se font-ils en site occupé ?"}, {"id": "f-ewl61221", "answer": "<p>Le syndicat des copropriétaires, maître d'ouvrage des travaux. Il vient en déduction du coût voté.</p>", "question": "Qui perçoit le financement en copropriété ?"}, {"id": "f-xhr7p3ew", "answer": "<p>Le dimensionnement est établi à partir des données du site, des régimes de fonctionnement et des besoins réels. PEXEN formalise les hypothèses et les calculs dans une note de dimensionnement avant travaux.</p>", "question": "Comment savez-vous que l’installation n’est pas surdimensionnée ?"}, {"id": "f-gz2em2sr", "answer": "<p>À partir des données d’exploitation et des relevés réalisés sur site. PEXEN dimensionne la solution, formalise les hypothèses de calcul et estime les économies attendues avant engagement des travaux.</p>", "question": "Comment estimez-vous les économies avant que je valide les travaux ?"}], "title": "Questions fréquentes sur la chaufferie collective", "layout": "stacked", "eyebrow": "FAQ", "showContactCard": false}, "type": "faq", "style": {"anchor": "faq", "background": "white", "paddingTop": "md", "hideOnMobile": false, "hideOnDesktop": false, "paddingBottom": "md"}}, {"id": "b-pxt-1", "data": {"html": "<div class=\\"pxt\\"><section class=\\"pxt-sec\\" style=\\"padding-top:24px\\"><div class=\\"pxt-c\\"><div class=\\"pxt-band pxt-rv\\"><img src=\\"/uploads/pexen-reseau-depart-retour-chauffage-04dc1bbd.webp\\" alt=\\"Réseau de chauffage collectif\\" loading=\\"lazy\\"><div><span class=\\"pxt-k\\">Votre projet</span><h2>Un projet ? Parlons-en.</h2><p>Prise de contact sous 48 h ouvrées par un ingénieur PEXEN, pour qualifier votre besoin et définir les prochaines étapes.</p><div class=\\"pxt-hero__act\\"><a class=\\"pxt-btn\\" href=\\"/contact/\\">Parler de votre projet <span class=\\"fa fa-arrow-right\\"></span></a><a class=\\"pxt-btn pxt-btn--ghost\\" href=\\"/simulateur-prime-cee/\\">Estimer le financement</a></div></div></div></div></section></div>\\n<style>:is(#pexen-compact,main) section:has(.px-ultra-faq-item){padding-bottom:36px!important}</style>"}, "type": "html", "style": {"background": "white", "paddingTop": "none", "paddingBottom": "none"}}, {"id": "b-0m1c5g4e", "data": {"image": "/uploads/pexen-batiments-collectifs-ce8e89df.webp", "intro": "Bailleurs sociaux, syndics et gestionnaires de copropriété : la rénovation énergétique copropriété et logement social agit sur deux choses que les occupants ressentent chaque hiver, leurs charges et leur confort. PEXEN modernise les chaufferies collectives, remplace le fioul par des pompes à chaleur, équilibre les réseaux et monte les dossiers CEE, dont la rénovation globale BAR-TH-177.", "title": "Performance énergétique des bâtiments collectifs", "buttons": [{"id": "btn-m8y0g8de", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-qtpg59pr", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "eyebrow": "Secteurs", "metrics": [{"id": "m-ndly3ylj", "label": "âge à partir duquel un plan pluriannuel de travaux est requis", "value": "15 ans"}, {"id": "m-k3a25ldm", "label": "installateur de pompes à chaleur collectives", "value": "RGE QualiPAC"}, {"id": "m-8cvk7r1e", "label": "prêt pour l’assemblée générale", "value": "1 dossier"}], "imageAlt": "Immeuble collectif contemporain avec balcons", "highlight": "Des charges maîtrisées, un confort tenu, un dossier prêt pour la décision.", "breadcrumb": true, "parentLink": "/secteurs/", "heroVariant": "sector", "parentLabel": "Secteurs"}, "type": "pageHeader", "style": {"background": "navy", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "md"}}, {"id": "b-5m3qfuhw", "data": {"html": "<div class=\\"px-ultra-zig-list\\"><article class=\\"px-ultra-zig\\">\\n  <div class=\\"px-ultra-zig__copy\\">\\n    <span class=\\"px-ultra-zig__num\\">Référence collectifs</span>\\n    <h2 class=\\"px-ultra-zig__title\\">Déstratification en grande hauteur</h2>\\n    <p class=\\"px-ultra-zig__lead\\">Un magasin chauffé par aérothermes gaz : l’air chaud stagne sous la toiture. Trois déstratificateurs ramènent la chaleur au sol.</p>\\n    <ul class=\\"px-ultra-zig__list\\"><li>BAT-TH-142</li><li>2,1 GWh cumac estimés*</li><li>Pose sans arrêt d’activité</li></ul>\\n    <a class=\\"px-ultra-zig__more\\" href=\\"/realisations/cedim-destratification/\\">Voir la réalisation <span aria-hidden=\\"true\\">→</span></a>\\n  </div>\\n  <a class=\\"px-ultra-zig__card\\" href=\\"/realisations/cedim-destratification/\\">\\n    <div class=\\"px-ultra-zig__card-media\\"><img src=\\"/themes/ultra-s/images/pexen/destratificateur-d-air-installe-dans-un-magasin-de-grande-hauteur.webp\\" alt=\\"CEDIM déstratification\\" loading=\\"lazy\\" width=\\"640\\" height=\\"400\\" /></div>\\n    <div class=\\"px-ultra-zig__card-body\\">\\n      <p class=\\"px-ultra-zig__card-tag\\">Collectif / négoce</p>\\n      <h3 class=\\"px-ultra-zig__card-title\\">CEDIM : ramener la chaleur au sol</h3>\\n      <div class=\\"px-ultra-zig__card-metrics\\"><span>2,1 GWh cumac*</span><span>BAT-TH-142</span></div>\\n    </div>\\n  </a>\\n</article></div>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-zb33qlkk", "data": {"intro": "", "items": [{"id": "c-93cm6am6", "link": "", "tags": [], "text": "Le chauffage et l’eau chaude collectifs constituent le premier poste de charges récupérables.", "title": "Les charges des occupants", "imageAlt": "Les charges des occupants", "linkLabel": ""}, {"id": "c-iizg4n4c", "link": "", "tags": [], "text": "Chaudières fioul ou gaz hors condensation, réseaux non isolés, régulation figée : les rendements chutent.", "title": "Des chaufferies vieillissantes", "imageAlt": "Des chaufferies vieillissantes", "linkLabel": ""}, {"id": "c-qx19yoqx", "link": "", "tags": [], "text": "Un projet de copropriété se vote en assemblée générale : il exige un dossier technique et financier lisible.", "title": "Une décision collective", "imageAlt": "Une décision collective", "linkLabel": ""}], "style": "hoverDark", "title": "Vos enjeux de bailleur ou de syndic", "columns": 3, "eyebrow": "Solutions", "headerLinkLabel": ""}, "type": "cards", "style": {"background": "soft", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-kpy01czx", "data": {"intro": "", "items": [{"id": "c-kvdet62p", "link": "", "tags": ["BAT-TH-163", "BAT-TH-164", "BAT-TH-162"], "text": "Pompes à chaleur collectives et géothermie, bonifiées par le Coup de pouce Chauffage en cas de dépose d’une chaudière fossile. PEXEN est installateur RGE QualiPAC.", "image": "/themes/ultra-s/images/pexen/pompes-a-chaleur-air-eau-sortie-du-fioul-chez-intermarche.webp", "title": "Sortie du fioul et du gaz", "imageAlt": "Sortie du fioul et du gaz", "linkLabel": ""}, {"id": "c-supp0i5p", "link": "", "tags": ["BAR-SE-104"], "text": "Réglage des organes d’équilibrage d’une installation de chauffage à eau chaude : les logements éloignés de la chaufferie atteignent la consigne sans surchauffer les autres.", "image": "/themes/ultra-s/images/pexen/batiments-collectifs-chaufferie-pexen.webp", "title": "Équilibrage et régulation des réseaux", "imageAlt": "Équilibrage et régulation des réseaux", "linkLabel": ""}, {"id": "c-te5x97af", "link": "", "tags": ["IND-UT-131", "IND-UT-121"], "text": "Calorifugeage des réseaux et matelas isolants sur vannes et échangeurs.", "image": "/themes/ultra-s/images/pexen/drive-isolation-technique-sur-reseau-hvac-industriel.webp", "title": "Isolation technique en chaufferie", "imageAlt": "Isolation technique en chaufferie", "linkLabel": ""}, {"id": "c-3u99i0l2", "link": "", "tags": ["BAR-TH-177"], "text": "Audit, bouquet de travaux et financement par la fiche BAR-TH-177, avec une bonification Coup de pouce « Rénovation performante d’un bâtiment résidentiel collectif » prolongée jusqu’au 31 décembre 2030.", "image": "/themes/ultra-s/images/pexen/drive-secteur-renovation-globale-collectif.webp", "title": "Rénovation globale", "imageAlt": "Rénovation globale", "linkLabel": ""}], "style": "hoverDark", "title": "Nos solutions pour la rénovation énergétique copropriété", "columns": 2, "eyebrow": "Solutions", "headerLinkLabel": ""}, "type": "cards", "style": {"background": "soft", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-7ntp8g33", "data": {"html": "<h2>Un dossier prêt pour l'assemblée générale</h2><p>Nous remettons un dossier lisible par le conseil syndical ou la direction du patrimoine : état des lieux, scénarios chiffrés, montant des CEE, reste à charge par lot ou par logement, calendrier des travaux en site occupé.</p>", "size": "normal"}, "type": "richText", "style": {"background": "soft", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-4m3h5coe", "data": {"html": "<h2>Les obligations des copropriétés</h2><p>Depuis la loi Climat et résilience, les copropriétés de plus de 15 ans doivent disposer d'un projet de plan pluriannuel de travaux, et les immeubles en monopropriété ou en copropriété d'un diagnostic de performance énergétique collectif. Le calendrier s'est appliqué par taille de copropriété : de 2023 à 2025 pour le plan pluriannuel, de 2024 à 2026 pour le DPE collectif. Depuis le 1er janvier 2026, toutes les copropriétés sont concernées. Ces documents chiffrent les travaux ; notre étude les traduit en scénarios finançables.</p>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-rtluhit5", "data": {"intro": "", "items": [{"id": "s-xchfaiwd", "num": "01", "text": "Consommations, puissance installée et températures de départ.", "title": "Relevé"}, {"id": "s-hhb8yqn8", "num": "02", "text": "Pompe à chaleur seule, hybride avec appoint, géothermie.", "title": "Scénarios"}, {"id": "s-e4tbxvpg", "num": "03", "text": "Assemblée générale ou comité d’engagement, avec le montant des CEE.", "title": "Dossier"}, {"id": "s-7rc1cjiy", "num": "04", "text": "Hors saison de chauffe ou avec production provisoire.", "title": "Travaux"}, {"id": "s-zty83cje", "num": "05", "text": "Réglage, équilibrage et suivi de la première saison.", "title": "Suivi"}], "style": "timeline", "title": "Sortir du fioul en chaufferie collective", "buttons": [], "eyebrow": "Méthode", "deliverableLabel": "Livrable"}, "type": "steps", "style": {"background": "soft", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-7cen4adm", "data": {"html": "<h2>Bailleurs, syndics, gestionnaires : un dossier adapté à chacun</h2><p>Pour un bailleur social, nous raisonnons à l'échelle du patrimoine et du programme pluriannuel. Pour un syndic, nous préparons les éléments que le conseil syndical présentera aux copropriétaires. Pour un gestionnaire, nous suivons les consommations après travaux et ajustons les réglages de la chaufferie.</p>", "size": "normal"}, "type": "richText", "style": {"background": "soft", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-1wlwfgx3", "data": {"text": "Un ingénieur PEXEN qualifie votre site, dimensionne les solutions et vous répond sous 48 h ouvrées.", "badge": "Réponse sous 48 h", "title": "Votre projet mérite une étude chiffrée", "layout": "centered", "buttons": [{"id": "btn-k584w2dt", "icon": "arrow", "link": "/contact/?demande=etude", "label": "Demander une étude", "variant": "primary"}], "eyebrow": "Étude & dimensionnement", "variant": "light"}, "type": "cta", "style": {"background": "soft", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-picf3bmq", "data": {"text": "Un ingénieur PEXEN étudie votre site, évalue le gisement et vous répond sous 48 h ouvrées.", "title": "Un projet ? Parlons-en.", "layout": "centered", "buttons": [{"id": "btn-0ontdlum", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-615ur1f8", "icon": "phone", "link": "tel:+33141935280", "label": "01 41 93 52 80", "variant": "secondary"}], "variant": "dark"}, "type": "cta", "style": {"background": "navy", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-pxt-css", "data": {"html": "<style>/* ===== pxt (Secteurs) ===== */\\n.pxt{--n:#082D4A;--c:#01CDF3;--p:#009FCC;--pd:#00769A;--b:#D5E1E6;--m:#5A6B7B;font-family:Figtree,system-ui,sans-serif;color:#3E5163;text-align:left}\\n.pxt *{box-sizing:border-box}\\n.pxt h1,.pxt h2,.pxt h3{font-family:Sora,system-ui,sans-serif;color:var(--n);margin:0}\\n.pxt p{margin:0 0 12px;line-height:1.7;font-size:16px}\\n.pxt-c{max-width:1296px;margin:0 auto;padding:0 24px;position:relative}\\n.pxt-sec{padding:72px 0;position:relative;overflow:hidden}\\n.pxt-k{display:inline-flex;align-items:center;gap:10px;font-size:12px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--pd)}\\n.pxt-k::before{content:\\"\\";width:28px;height:2px;background:var(--c)}\\n.pxt h2{font-size:clamp(28px,2.8vw,42px);line-height:1.15;letter-spacing:-.015em;margin:14px 0 14px}\\n.pxt-lead{font-size:17.5px!important;color:var(--m);max-width:720px}\\n.pxt-btn{display:inline-flex;align-items:center;gap:10px;height:48px;padding:0 26px;border-radius:6px;background:var(--c);color:var(--n)!important;font-weight:600;font-size:16px;text-decoration:none!important;transition:transform .2s,box-shadow .2s}\\n.pxt-btn:hover{transform:translateY(-2px);box-shadow:0 12px 26px rgba(1,205,243,.35)}\\n.pxt-btn--ghost{background:transparent;border:1px solid rgba(255,255,255,.5);color:#fff!important}\\n.pxt-btn--line{background:transparent;border:1px solid rgba(8,45,74,.3);color:var(--n)!important}\\n.pxt-link{display:inline-flex;gap:8px;align-items:center;font-weight:700;color:var(--pd)!important;text-decoration:none!important}\\n.pxt-link:hover{gap:12px}\\n.pxt-tag{display:inline-block;font-size:12px;font-weight:700;color:var(--pd);background:#E3F7FC;border-radius:6px;padding:5px 9px}\\n.pxt-hero{position:relative;min-height:640px;display:flex;align-items:flex-end;color:#fff;overflow:hidden;background:var(--n)}\\n.pxt-hero__bg{position:absolute;inset:0;margin:0}\\n.pxt-hero__bg img{width:100%;height:100%;object-fit:cover;transform:scale(1.04)}\\n.pxt-hero::before{content:\\"\\";position:absolute;inset:0;z-index:1;background:linear-gradient(90deg,rgba(8,45,74,.96) 0%,rgba(8,45,74,.86) 38%,rgba(8,45,74,.35) 72%,rgba(8,45,74,.15) 100%)}\\n.pxt-hero::after{content:attr(data-word);position:absolute;z-index:1;right:-10px;bottom:-34px;font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:clamp(90px,13vw,200px);line-height:1;color:transparent;-webkit-text-stroke:1.5px rgba(1,205,243,.28);letter-spacing:-.03em;pointer-events:none;white-space:nowrap}\\n.pxt-hero .pxt-c{z-index:2;width:100%;padding-top:96px;padding-bottom:72px;display:grid;grid-template-columns:7fr 5fr;gap:48px;align-items:end}\\n.pxt-crumbs{font-size:13px;color:rgba(255,255,255,.65);margin-bottom:18px}\\n.pxt-crumbs a{color:rgba(255,255,255,.8)!important;text-decoration:none!important}\\n.pxt-hero .pxt-k{color:var(--c)}\\n.pxt-hero h1{color:#fff;font-size:clamp(34px,4vw,58px);line-height:1.06;letter-spacing:-.02em;margin:14px 0 14px}\\n.pxt-hero__sub{font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:clamp(19px,1.7vw,24px);line-height:1.35;color:var(--c);margin:0 0 16px!important;max-width:640px}\\n.pxt-hero__desc{color:rgba(255,255,255,.82);max-width:600px;font-size:16.5px!important}\\n.pxt-hero__act{display:flex;flex-wrap:wrap;gap:12px;margin-top:26px}\\n.pxt-figs{display:grid;gap:12px}\\n.pxt-fig{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);border-radius:16px;padding:18px 22px;display:grid;grid-template-columns:auto 1fr;gap:16px;align-items:center}\\n.pxt-fig b{font-family:Sora,system-ui,sans-serif;font-size:30px;line-height:1;color:var(--c);white-space:nowrap}\\n.pxt-fig span{font-size:14px;color:rgba(255,255,255,.85);line-height:1.4}\\n.pxt-enj{display:grid;grid-template-columns:repeat(3,1fr);gap:0;border-top:1px solid var(--b);margin-top:36px}\\n.pxt-enj>div{padding:34px 30px 30px;border-right:1px solid var(--b);position:relative;transition:background .3s}\\n.pxt-enj>div:last-child{border-right:0}\\n.pxt-enj>div::before{content:\\"\\";position:absolute;left:0;top:-1px;height:3px;width:0;background:var(--c);transition:width .5s}\\n.pxt-enj>div:hover{background:#F6FAFC}.pxt-enj>div:hover::before{width:100%}\\n.pxt-enj i{display:block;font-style:normal;font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:76px;line-height:1;color:transparent;-webkit-text-stroke:1.5px var(--p);margin-bottom:18px}\\n.pxt-enj h3{font-size:20px;margin-bottom:10px}\\n.pxt-enj p{font-size:15px!important;color:var(--m)}\\n.pxt-enj .pxt-link{margin-top:6px;font-size:14.5px}\\n.pxt-dark{background:radial-gradient(circle at 0% 0%,rgba(1,205,243,.14),transparent 40%),var(--n);color:rgba(255,255,255,.8)}\\n.pxt-dark h2,.pxt-dark h3{color:#fff}.pxt-dark .pxt-k{color:var(--c)}.pxt-dark .pxt-lead{color:rgba(255,255,255,.72)}\\n.pxt-tabs{display:grid;grid-template-columns:330px 1fr;gap:28px;margin-top:36px;align-items:stretch}\\n.pxt-tabs>input{position:absolute;opacity:0;pointer-events:none}\\n.pxt-tabs__nav{display:grid;gap:8px;align-content:start}\\n.pxt-tabs__nav label{display:flex;align-items:center;gap:14px;cursor:pointer;padding:16px 18px;border-radius:12px;border:1px solid rgba(255,255,255,.14);color:rgba(255,255,255,.85);font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:16px;transition:all .25s}\\n.pxt-tabs__nav label i{font-style:normal;font-size:12px;font-weight:800;color:var(--c);width:26px}\\n.pxt-tabs__nav label:hover{background:rgba(255,255,255,.06)}\\n.pxt-tabs__panels{position:relative;min-height:400px}\\n.pxt-panel{display:none;grid-template-columns:1fr 1fr;border-radius:20px;overflow:hidden;background:#fff;height:100%;animation:pxtFade .4s ease}\\n.pxt-panel figure{margin:0;position:relative;min-height:400px}.pxt-panel figure img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\\n.pxt-panel>div{padding:34px 34px 30px;display:flex;flex-direction:column;justify-content:center}\\n.pxt-panel h3{color:var(--n)!important;font-size:24px;margin-bottom:12px}\\n.pxt-panel p{color:#3E5163;font-size:15.5px!important}\\n.pxt-panel .pxt-note{font-size:13px!important;color:var(--m);background:#F2F6F9;border-radius:8px;padding:10px 12px}\\n@keyframes pxtFade{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}\\n.pxt-tabs>input:nth-of-type(1):checked~.pxt-tabs__panels .pxt-panel:nth-child(1),.pxt-tabs>input:nth-of-type(2):checked~.pxt-tabs__panels .pxt-panel:nth-child(2),.pxt-tabs>input:nth-of-type(3):checked~.pxt-tabs__panels .pxt-panel:nth-child(3),.pxt-tabs>input:nth-of-type(4):checked~.pxt-tabs__panels .pxt-panel:nth-child(4),.pxt-tabs>input:nth-of-type(5):checked~.pxt-tabs__panels .pxt-panel:nth-child(5){display:grid}\\n.pxt-tabs>input:nth-of-type(1):checked~.pxt-tabs__nav label:nth-of-type(1),.pxt-tabs>input:nth-of-type(2):checked~.pxt-tabs__nav label:nth-of-type(2),.pxt-tabs>input:nth-of-type(3):checked~.pxt-tabs__nav label:nth-of-type(3),.pxt-tabs>input:nth-of-type(4):checked~.pxt-tabs__nav label:nth-of-type(4),.pxt-tabs>input:nth-of-type(5):checked~.pxt-tabs__nav label:nth-of-type(5){background:var(--c);border-color:var(--c);color:var(--n)}\\n.pxt-tabs>input:nth-of-type(1):checked~.pxt-tabs__nav label:nth-of-type(1) i,.pxt-tabs>input:nth-of-type(2):checked~.pxt-tabs__nav label:nth-of-type(2) i,.pxt-tabs>input:nth-of-type(3):checked~.pxt-tabs__nav label:nth-of-type(3) i,.pxt-tabs>input:nth-of-type(4):checked~.pxt-tabs__nav label:nth-of-type(4) i,.pxt-tabs>input:nth-of-type(5):checked~.pxt-tabs__nav label:nth-of-type(5) i{color:var(--n)}\\n.pxt-split{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}\\n.pxt-bars{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;align-items:end;height:300px;padding:0 6px;border-bottom:2px solid var(--b)}\\n.pxt-bar{position:relative;border-radius:12px 12px 0 0;background:linear-gradient(180deg,#9DB4C3,#C7D4DD);display:flex;flex-direction:column;justify-content:flex-start;align-items:center;padding-top:14px;color:#fff;font-family:Sora,system-ui,sans-serif;font-weight:700}\\n.pxt-bar b{font-size:22px}\\n.pxt-bar--on{background:linear-gradient(180deg,var(--c),var(--p))}.pxt-bar--on b{color:var(--n)}\\n.pxt-bar--nv{background:linear-gradient(180deg,#0E4A73,var(--n))}\\n.pxt-bars__x{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;padding:10px 6px 0;text-align:center;font-family:Sora,system-ui,sans-serif;font-weight:600;color:var(--n);font-size:15px}\\n.pxt-bars__x small{display:block;font-family:Figtree,system-ui,sans-serif;font-weight:500;color:var(--m);font-size:12.5px}\\n.pxt-big{font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:clamp(70px,9vw,130px);line-height:.95;color:transparent;-webkit-text-stroke:2px var(--p);letter-spacing:-.03em}\\n.pxt-big+span{display:block;font-family:Sora,system-ui,sans-serif;font-weight:600;color:var(--n);font-size:20px;margin-top:8px}\\n.pxt-duo{display:grid;grid-template-columns:1fr 64px 1fr;align-items:stretch;margin-top:32px}\\n.pxt-duo>div{border-radius:18px;padding:30px}\\n.pxt-duo__a{background:#fff;border:1px solid var(--b)}\\n.pxt-duo__b{background:var(--n);color:rgba(255,255,255,.82)}.pxt-duo__b h3{color:#fff!important}\\n.pxt-duo__x{display:grid;place-items:center}.pxt-duo__x span{width:52px;height:52px;border-radius:50%;background:var(--c);color:var(--n);display:grid;place-items:center;font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:20px;box-shadow:0 0 0 8px #fff}\\n.pxt-duo .pxt-ico{width:46px;height:46px;border-radius:12px;display:grid;place-items:center;font-size:18px;background:#E3F7FC;color:var(--pd);margin-bottom:14px}\\n.pxt-duo__b .pxt-ico{background:rgba(1,205,243,.14);color:var(--c)}\\n.pxt-duo h3{font-size:20px;margin-bottom:8px}\\n.pxt-vs{position:relative;display:grid;gap:14px;counter-reset:s}\\n.pxt-vs::before{content:\\"\\";position:absolute;left:27px;top:20px;bottom:20px;width:2px;background:linear-gradient(180deg,var(--c),rgba(1,205,243,.15))}\\n.pxt-vs>div{position:relative;display:grid;grid-template-columns:56px 1fr;gap:18px;align-items:center}\\n.pxt-vs>div::before{counter-increment:s;content:counter(s,decimal-leading-zero);width:56px;height:56px;border-radius:50%;background:#fff;border:2px solid var(--c);display:grid;place-items:center;font-family:Sora,system-ui,sans-serif;font-weight:700;color:var(--n);z-index:1}\\n.pxt-vs>div>div{background:#fff;border:1px solid var(--b);border-radius:14px;padding:16px 20px;font-size:15.5px;color:var(--n);box-shadow:0 8px 20px rgba(8,45,74,.05)}\\n.pxt-dark .pxt-vs>div::before{background:var(--n);color:#fff}\\n.pxt-dark .pxt-vs>div>div{background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.14);color:#fff}\\n.pxt-groups{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:32px}\\n.pxt-group{background:#fff;border:1px solid var(--b);border-radius:16px;padding:20px 20px 16px;transition:transform .2s,border-color .2s}\\n.pxt-group:hover{transform:translateY(-3px);border-color:var(--c)}\\n.pxt-group h3{font-size:16px;display:flex;align-items:center;gap:10px;margin-bottom:12px}\\n.pxt-group h3 span{width:34px;height:34px;border-radius:10px;background:#E3F7FC;color:var(--pd);display:grid;place-items:center;font-size:14px}\\n.pxt-group ul{list-style:none;padding:0;margin:0;display:grid;gap:10px}\\n.pxt-group li{display:grid;gap:4px;font-size:14.5px;color:var(--n);padding-top:10px;border-top:1px dashed var(--b)}\\n.pxt-group li:first-child{border-top:0;padding-top:0}\\n.pxt-group--wide{grid-column:span 2}\\n.pxt-mos{display:grid;grid-template-columns:1.4fr 1fr;grid-auto-rows:220px;gap:16px;margin-top:32px}\\n.pxt-mos a{position:relative;border-radius:18px;overflow:hidden;display:block;text-decoration:none!important}\\n.pxt-mos a:first-child{grid-row:span 2}\\n.pxt-mos img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .6s}\\n.pxt-mos a:hover img{transform:scale(1.05)}\\n.pxt-mos a::after{content:\\"\\";position:absolute;inset:0;background:linear-gradient(180deg,rgba(8,45,74,0) 35%,rgba(8,45,74,.92))}\\n.pxt-mos a>div{position:absolute;z-index:1;left:22px;right:22px;bottom:20px;color:#fff}\\n.pxt-mos small{display:block;font-size:11.5px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--c);margin-bottom:6px}\\n.pxt-mos b{font-family:Sora,system-ui,sans-serif;font-size:20px;line-height:1.25;font-weight:600}\\n.pxt-mos a:first-child b{font-size:26px}\\n.pxt-mos--1{grid-template-columns:1fr;grid-auto-rows:340px}\\n.pxt-band{position:relative;overflow:hidden;border-radius:24px;min-height:300px;display:grid;place-items:center;text-align:center;color:#fff;padding:56px 24px}\\n.pxt-band img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\\n.pxt-band::before{content:\\"\\";position:absolute;inset:0;z-index:1;background:linear-gradient(120deg,rgba(8,45,74,.95),rgba(8,45,74,.7) 60%,rgba(0,118,154,.75))}\\n.pxt-band>div{position:relative;z-index:2;max-width:760px}\\n.pxt-band h2{color:#fff;margin:12px 0 10px}.pxt-band p{color:rgba(255,255,255,.82)}\\n.pxt-band .pxt-k{color:var(--c)}.pxt-band .pxt-hero__act{justify-content:center}\\n.pxt-checks{list-style:none;padding:0;margin:14px 0 0;display:grid;gap:10px}\\n.pxt-checks li{display:flex;gap:12px;font-size:15.5px;color:var(--n);line-height:1.5}\\n.pxt-checks li::before{content:\\"\\";flex:0 0 10px;height:10px;margin-top:7px;border-radius:2px;background:var(--c);transform:rotate(45deg)}\\n.pxt-dark .pxt-checks li{color:#fff}\\n.px-section:has(.pxt-hero),.px-block-typo:has(.pxt-hero){margin-top:0!important;padding-top:0!important}\\n@supports (animation-timeline:view()){.pxt-rv{animation:pxtIn linear both;animation-timeline:view();animation-range:entry 0% entry 35%}@keyframes pxtIn{from{opacity:0;transform:translateY(30px)}to{opacity:1;transform:none}}}\\n@media(prefers-reduced-motion:reduce){.pxt-rv{animation:none!important}}\\n@media(max-width:991px){.pxt-hero .pxt-c{grid-template-columns:1fr;padding-top:120px}.pxt-enj{grid-template-columns:1fr}.pxt-enj>div{border-right:0;border-bottom:1px solid var(--b)}.pxt-tabs{grid-template-columns:1fr}.pxt-tabs__nav{grid-auto-flow:column;grid-auto-columns:max-content;overflow-x:auto}.pxt-panel{grid-template-columns:1fr}.pxt-panel figure{min-height:220px}.pxt-split{grid-template-columns:1fr;gap:36px}.pxt-duo{grid-template-columns:1fr;gap:12px}.pxt-duo__x{display:none}.pxt-groups{grid-template-columns:1fr 1fr}.pxt-mos{grid-template-columns:1fr}.pxt-mos a:first-child{grid-row:auto}}\\n@media(max-width:575px){.pxt-groups{grid-template-columns:1fr}.pxt-group--wide{grid-column:auto}.pxt-sec{padding:52px 0}}\\n/* pleine largeur */.pxs-sec,.pxt-sec,.pxt-hero{width:100vw!important;margin-left:calc(50% - 50vw)!important;margin-right:0!important}body{overflow-x:clip}\\n/* ===== /pxt ===== */</style>\\n<style>:is(#pexen-compact,main) section:has(.px-ultra-faq-item){padding-bottom:36px!important}</style>"}, "type": "html", "style": {"paddingTop": "none", "paddingBottom": "none"}}]	{"slug": "renovation-energetique-copropriete", "noindex": false, "nofollow": false, "seoTitle": "Rénovation énergétique des bâtiments collectifs | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "rénovation énergétique", "metaDescription": "Rénovation énergétique copropriété et logement social : sortie du fioul, chaufferie collective, équilibrage, dossiers CEE et AG."}	18	2026-10-18 13:23:13.999+02	\N	2026-10-18 13:23:13.999+02	2026-11-11 19:18:44.795+01	\N
p-zhfrekzi	/mentions-legales/	Mentions légales	published	cms	legal	[{"id": "b-vx643myc", "data": {"image": "/uploads/pexen-batiment-tertiaire-8345e0ee.webp", "intro": "", "title": "Mentions légales", "buttons": [], "eyebrow": "PEXEN", "imageAlt": "Bâtiment tertiaire contemporain", "breadcrumb": true, "parentLink": "", "parentLabel": "", "backgroundImage": "/themes/ultra-s/images/pexen/centrale-froid.webp"}, "type": "pageHeader", "style": {}}, {"id": "b-oi2g9pcu", "data": {"html": "<p><em>Dernière mise à jour : 10 novembre 2026</em></p><h2>1. Éditeur du site</h2><p>Le site pexen.fr (ci-après « le Site ») est édité par la société PEXEN, société par actions simplifiée au capital de 30 000 euros, immatriculée au registre du commerce et des sociétés de Créteil sous le numéro 922 217 336, dont le siège social est situé 122 avenue des Dahlias, 94240 L’Haÿ-les-Roses (SIRET : 922 217 336 00028).</p><p>Numéro de TVA intracommunautaire : FR75922217336</p><p>Téléphone : 01 41 93 52 80</p><p>Adresse électronique : contact@pexen.fr</p><p>PEXEN® est une marque de la société PEXEN.</p><h2>2. Directeur de la publication</h2><p>Monsieur Jamel Yacouben, en sa qualité de Président de la société PEXEN.</p><h2>3. Hébergement</h2><p>Le Site est hébergé par IONOS.</p><h2>4. Qualifications et assurances</h2><p>PEXEN est titulaire des qualifications RGE QualiPAC (pompes à chaleur, chauffage et eau chaude sanitaire), certificat n° QPAC/70449, et RGE Qualisol CESI, certificat n° QS/70449, délivrées par Qualit'EnR. Leur validité peut être vérifiée sur l'annuaire officiel France Rénov'.</p><p>Les audits énergétiques mentionnés sur le Site sont réalisés par le bureau d'études partenaire Leo Energy, titulaire de qualifications OPQIBI. Ces qualifications appartiennent à Leo Energy et non à PEXEN.</p><p>PEXEN a souscrit une assurance de responsabilité civile professionnelle et une assurance de responsabilité civile décennale auprès de MIC Insurance Company (police n° PTF N-3898616), couvrant les travaux réalisés en France métropolitaine.</p><h2>5. Propriété intellectuelle</h2><p>L'ensemble des éléments composant le Site, notamment les textes, visuels, photographies, illustrations, schémas, vidéos, éléments graphiques, chartes graphiques, logiciels, bases de données, la marque déposée PEXEN®, ainsi que la structure, l'agencement et la présentation du Site, sont la propriété exclusive et intégrale de la société PEXEN ou font l'objet d'autorisations d'utilisation spécifiques accordées à celle-ci.</p><p>Toute reproduction, représentation, modification, adaptation, altération, traduction, extraction, réutilisation, diffusion ou exploitation, totale ou partielle, de ces éléments, de la marque PEXEN® ou de tout ou partie du contenu du Site, par quelque procédé que ce soit, sur quel que support que ce soit, sans l'autorisation écrite, préalable et expresse de la société PEXEN, est strictement interdite. Tout manquement constitue une contrefaçon sanctionnée par les articles L. 335-2 et suivants ainsi que L. 716-1 et suivants du Code de la propriété intellectuelle, susceptible d'engager la responsabilité civile et pénale de son auteur. PEXEN se réserve le droit d'engager toute poursuite judiciaire nécessaire à la préservation de ses droits.</p><p>Les noms et logos des clients figurant sur le Site sont reproduits avec leur accord. Les logos des organismes de qualification appartiennent à ces organismes.</p><h2>6. Informations techniques, chiffres et estimations</h2><p>Les informations, éléments graphiques, données techniques et outils de simulation publiés sur le Site sont fournis exclusivement à titre informatif et indicatif. Ils ne constituent en aucun cas une offre contractuelle, un conseil juridique, financier ou technique engagé, ni une garantie de résultat ou d'éligibilité. Seule une étude de faisabilité sur site réalisée par nos équipes et la signature d'un devis ou d'un contrat ferme engagent PEXEN.</p><p>Les estimations d'économies d'énergie (exprimées en kWh cumac, GWh cumac ou pourcentages) sont établies à titre théorique et indicatif selon les fiches d'opérations standardisées de certificats d'économies d'énergie (CEE) ou des modèles de simulation. Elles ne constituent en aucun cas un engagement ferme ou une mesure des consommations réelles. PEXEN exclut toute responsabilité en cas d'écart entre les estimations affichées et les économies réellement constatées ultérieurement.</p><p>Les pourcentages de réduction des consommations associés à un contrat de performance énergétique correspondent à des objectifs contractuels, définis sur un périmètre, une durée et des conditions d'exploitation déterminés dans le contrat concerné.</p><p>Les informations réglementaires (décret tertiaire, décret BACS, dispositif des certificats d'économies d'énergie) sont à jour à la date indiquée sur chaque page. Elles peuvent évoluer ; seuls les textes publiés au Journal officiel font foi.</p><h2>7. Responsabilité</h2><p>PEXEN s'efforce de maintenir le Site à jour et accessible, sans toutefois pouvoir garantir l'absence totale d'erreurs, de virus, d'interruptions techniques ou d'inexactitudes. Dans les limites autorisées par la loi, PEXEN décline toute responsabilité pour tout dommage direct ou indirect, matériel ou immatériel (incluant notamment les pertes de données, de chiffre d'affaires, de bénéfices ou d'opportunités) résultant de l'accès au Site, de son indisponibilité, ou de l'utilisation des informations et simulations qui y figurent.</p><h2>8. Liens hypertextes</h2><p>Le Site peut contenir des liens vers des sites tiers, notamment des sites institutionnels. PEXEN n'exerce aucun contrôle sur ces sites et décline toute responsabilité quant à leur contenu.</p><p>La création d'un lien vers le Site est libre, à condition qu'il ne porte pas atteinte à l'image de PEXEN et qu'il ouvre le Site dans une nouvelle fenêtre. PEXEN peut demander la suppression de tout lien à tout moment.</p><h2>9. Données personnelles et cookies</h2><p>Le traitement des données personnelles collectées sur le Site et l'utilisation des cookies sont décrits dans la <a href=\\"/politique-de-confidentialite/\\">politique de confidentialité</a>, accessible depuis chaque page du Site.</p><h2>10. Droit applicable et juridiction</h2><p>Les présentes mentions légales sont régies par le droit français. Tout litige relatif au Site relève, à défaut de résolution amiable et sous réserve des règles de compétence impératives, des juridictions compétentes du ressort du siège social de PEXEN.</p>", "size": "normal"}, "type": "richText", "style": {"width": "narrow", "background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}]	{"slug": "mentions-legales", "noindex": true, "nofollow": false, "seoTitle": "Mentions légales | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "", "metaDescription": "Mentions légales du site pexen.fr : éditeur, directeur de la publication, hébergeur."}	5	2026-10-21 12:43:13.023+02	\N	2026-10-21 12:43:13.023+02	2026-11-10 12:01:57.3+01	\N
p-eo5wde86	/politique-de-confidentialite/	Politique de confidentialité	published	cms	legal	[{"id": "b-h8tr1e8i", "data": {"image": "/uploads/pexen-batiment-tertiaire-8345e0ee.webp", "intro": "", "title": "Politique de confidentialité", "buttons": [], "eyebrow": "PEXEN", "imageAlt": "Bâtiment tertiaire contemporain", "breadcrumb": true, "parentLink": "", "parentLabel": "", "backgroundImage": "/themes/ultra-s/images/pexen/centrale-froid.webp"}, "type": "pageHeader", "style": {}}, {"id": "b-mrg7j489", "data": {"html": "<p><em>Dernière mise à jour : 10 novembre 2026</em></p><p>La présente politique informe les visiteurs du Site et les personnes qui contactent PEXEN de la manière dont leurs données personnelles sont traitées, conformément au règlement (UE) 2016/679 du 27 avril 2016 (« RGPD ») et à la loi n° 78-17 du 6 janvier 1978 relative à l'informatique, aux fichiers et aux libertés.</p><h2>1. Responsable du traitement</h2><p>Le responsable du traitement est la société PEXEN, société par actions simplifiée au capital de 30 000 euros, immatriculée au RCS de Créteil sous le numéro 922 217 336 (SIRET : 922 217 336 00028), dont le siège social est situé 122 avenue des Dahlias, 94240 L’Haÿ-les-Roses, représentée par son Président, Monsieur Jamel Yacouben.</p><p>Pour toute question relative à vos données : contact@pexen.fr. PEXEN n'a pas désigné de délégué à la protection des données, cette désignation n'étant pas obligatoire au regard de son activité.</p><h2>2. Données collectées</h2><p>Formulaire de contact : nom et prénom, société, fonction (facultatif), adresse électronique professionnelle, numéro de téléphone, profil (entreprise, bailleur ou syndic, partenaire professionnel), type de site et description du projet. Les champs obligatoires sont signalés par un astérisque ; sans eux, PEXEN ne peut pas traiter la demande.</p><p>Outil « Estimer le financement » : type de site, nature des travaux envisagés et caractéristiques techniques saisies. Ces données ne sont rattachées à une personne que si celle-ci transmet ensuite ses coordonnées.</p><p>Échanges via WhatsApp : numéro de téléphone, nom de profil et contenu des messages, lorsque vous choisissez ce canal.</p><p>Assistant « Conseil PXN » : questions saisies dans l'assistant. Il est demandé de n'y saisir aucune donnée personnelle.</p><p>Navigation : avec votre consentement uniquement, données de mesure d'audience (pages consultées, durée de visite, type d'appareil et de navigateur, localisation approximative déduite de l'adresse IP tronquée).</p><h2>3. Finalités et bases légales</h2><p>FinalitéBase légaleRépondre à votre demande, organiser la visite technique et établir une propositionMesures précontractuelles prises à votre demande (article 6.1.b du RGPD)Gérer la relation commerciale et l'exécution des contratsExécution du contrat (article 6.1.b)Adresser aux professionnels des informations sur les offres de PEXEN en rapport avec leur activitéIntérêt légitime de PEXEN (article 6.1.f), avec faculté d'opposition à tout momentConstituer les dossiers de financement et répondre aux contrôles lorsque l'opération relève du dispositif des certificats d'économies d'énergieObligation légale et exécution du contrat (articles 6.1.c et 6.1.b)Mesurer l'audience du Site et en améliorer le contenuConsentement (article 6.1.a), recueilli par le bandeau cookiesAssurer la sécurité du Site et prévenir les envois abusifs du formulaireIntérêt légitime de PEXEN (article 6.1.f)Respecter les obligations comptables et fiscalesObligation légale (article 6.1.c)</p><h2>4. Destinataires</h2><p>Les données sont destinées aux seules personnes habilitées de PEXEN, dans la limite de leurs attributions. Elles peuvent être communiquées à des prestataires agissant pour le compte de PEXEN en qualité de sous-traitants : l'hébergeur du Site IONOS, Google Ireland Limited (messagerie professionnelle et, avec votre accord, Google Analytics) et Meta Platforms Ireland Limited (WhatsApp), pour les échanges que vous initiez sur ce canal.</p><p>Lorsqu'un projet relève du dispositif des certificats d'économies d'énergie, les données nécessaires au dossier sont transmises au partenaire financeur de l'opération et à l'organisme de contrôle accrédité, dans le cadre prévu par la réglementation. Vous en êtes informé au moment de la constitution du dossier.</p><p>Les données ne sont ni vendues, ni louées, ni cédées à des tiers à des fins commerciales.</p><h2>5. Transferts hors de l'Union européenne</h2><p>L'utilisation de Google Analytics et de WhatsApp peut entraîner un transfert de données vers les États-Unis. Ces transferts sont encadrés par la décision d'adéquation de la Commission européenne relative au cadre de protection des données UE, États-Unis (Data Privacy Framework), à laquelle ces sociétés ont adhéré, et, à défaut, par les clauses contractuelles types de la Commission européenne.</p><h2>6. Durées de conservation</h2><p>DonnéesDuréeDemande de contact sans suite3 ans à compter du dernier contact émanant de la personneDonnées des clientsDurée de la relation contractuelle, puis 3 ans à des fins de prospection ; durée de la prescription applicable pour la gestion d'un éventuel contentieuxPièces des dossiers de travaux et de financementDurée imposée par la réglementation applicable à l'opérationPièces comptables10 ans (article L. 123-22 du Code de commerce)Cookies de mesure d'audience13 mois au maximum à compter de leur dépôtDonnées de mesure d'audience14 moisChoix exprimé dans le bandeau cookies6 mois, au terme desquels votre choix est de nouveau demandé</p><h2>7. Vos droits</h2><p>Vous disposez d'un droit d'accès, de rectification, d'effacement, de limitation du traitement, d'opposition, notamment à la prospection, et à la portabilité de vos données, ainsi que du droit de définir des directives relatives au sort de vos données après votre décès. Lorsque le traitement repose sur votre consentement, vous pouvez le retirer à tout moment, sans que cela remette en cause la licéité du traitement effectué avant ce retrait.</p><p>Pour exercer ces droits, écrivez à contact@pexen.fr. Une réponse vous est apportée dans un délai d'un mois, prolongeable de deux mois compte tenu de la complexité ou du nombre de demandes. Un justificatif d'identité peut vous être demandé en cas de doute raisonnable sur votre identité.</p><p>Si vous estimez, après avoir contacté PEXEN, que vos droits ne sont pas respectés, vous pouvez introduire une réclamation auprès de la Commission nationale de l'informatique et des libertés (CNIL), 3 place de Fontenoy, TSA 80715, 75334 Paris Cedex 07, <a target=\\"_blank\\" rel=\\"noopener\\" href=\\"https://www.cnil.fr/\\">www.cnil.fr</a>.</p><h2>8. Sécurité</h2><p>PEXEN met en œuvre des mesures techniques et organisationnelles renforcées et adaptées au risque pour préserver la sécurité, l'intégrité et la confidentialité des données personnelles et empêcher toute altération, perte ou accès non autorisé : protocole HTTPS chiffré, contrôle strict des accès réservés au seul personnel habilité, politiques de mots de passe renforcées et sélection de sous-traitants présentant des garanties suffisantes de conformité au RGPD.</p><h2>9. Cookies</h2><p>Un cookie est un fichier déposé sur votre terminal lors de la consultation du Site. Le Site utilise :</p><p>CatégorieFinalitéConsentementDuréeCookies nécessairesFonctionnement et sécurité du Site, mémorisation de votre choix en matière de cookiesNon requis6 mois au maximumMesure d'audience (Google Analytics 4 : _ga, _ga_GRR10GDECY)Statistiques de fréquentation et amélioration des contenusRequis13 mois au maximum</p><p>Lors de votre première visite, un bandeau vous permet d'accepter, de refuser ou de paramétrer les cookies soumis à consentement. Refuser est aussi simple qu'accepter. Aucun cookie de mesure d'audience n'est déposé avant votre choix. Vous pouvez modifier ce choix à tout moment grâce au lien « Gérer mes cookies » présent en bas de chaque page.</p><p>Vous pouvez également configurer votre navigateur pour bloquer les cookies. Les cookies nécessaires restant indispensables au fonctionnement du Site, leur blocage peut en limiter certaines fonctionnalités.</p><h2>10. Modification de la politique</h2><p>PEXEN peut modifier la présente politique pour tenir compte des évolutions légales, réglementaires ou techniques. La date de dernière mise à jour figure en tête de page.</p>", "size": "normal"}, "type": "richText", "style": {"width": "narrow", "background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}]	{"slug": "politique-de-confidentialite", "noindex": true, "nofollow": false, "seoTitle": "Politique de confidentialité | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "", "metaDescription": "Comment PEXEN collecte, utilise et protège vos données personnelles."}	6	2026-10-21 12:43:13.023+02	\N	2026-10-21 12:43:13.023+02	2026-11-10 12:02:09.365+01	\N
p-9oz5v30o	/realisations/intermarche-sortie-du-fioul/	Intermarché : sortir du fioul et optimiser le froid	published	cms	project	[{"id": "b-pxt-0", "data": {"html": "<div class=\\"pxt\\"><section class=\\"pxr-hero pxr-hero--split\\"><div><div class=\\"pxt-crumbs\\"><a href=\\"/\\">Accueil</a> › <a href=\\"/realisations/\\">Réalisations</a> › Intermarché</div><span class=\\"pxt-k\\">Réalisation · Grande distribution</span><h1>Intermarché : sortie du fioul et chaleur récupérée sur le froid</h1><div class=\\"pxr-chips\\"><span>Bourgogne-Franche-Comté</span><span>Grande distribution</span><span>Supermarché</span></div><div class=\\"pxt-hero__act\\"><a class=\\"pxt-btn\\" href=\\"/contact/\\">Un projet similaire ? <span class=\\"fa fa-arrow-right\\"></span></a></div></div><figure><img src=\\"/uploads/pexen-intermarche-pac-apres-957aec84.webp\\" alt=\\"Pompes à chaleur air-eau chez Intermarché après travaux\\" loading=\\"eager\\"></figure></section>\\n<section class=\\"pxt-sec\\" style=\\"padding-top:0;overflow:visible\\"><div class=\\"pxt-c\\"><div class=\\"pxr-figs pxt-rv\\"><div><b>1 650 m²</b><span>chauffés et sortis du fioul</span></div><div><b>240 kW</b><span>de chaleur récupérée sur la production de froid</span></div><div><b>14,8 GWh</b><span>cumac* d'économies d'énergie estimées sur 6 opérations</span></div><div><b>3 432 h</b><span>par an d'utilisation de la chaleur récupérée</span></div><div><b>40 %*</b><span>d'économie d'énergie visée sur 10 ans par contrat de performance</span></div></div>\\n<div style=\\"margin-top:40px\\"><div class=\\"pxr-story pxt-rv\\"><div class=\\"pxr-story__k\\"><i>01</i><span>Contexte</span></div><div><h2>Le site avant la sortie du fioul</h2><p>Le magasin était chauffé par deux chaudières fioul vétustes, alors que sa centrale de froid rejetait sa chaleur à l'extérieur.</p><p>Objectif : sortir du fioul, valoriser cette chaleur et maîtriser les consommations électriques, en hausse de 22 % entre 2024 et 2025.</p></div></div>\\n<div class=\\"pxr-story pxt-rv\\"><div class=\\"pxr-story__k\\"><i>02</i><span>Solution</span></div><div><h2>Ce que PEXEN a installé</h2><ul class=\\"pxt-checks\\"><li>Deux pompes à chaleur air/eau en cascade, en remplacement de la chaudière fioul.</li><li>Récupération de chaleur sur le groupe de production de froid commercial.</li><li>Contrat de performance énergétique sur 10 ans.</li><li>Régulation du froid et fermeture des meubles frigorifiques.</li></ul><p style=\\"margin-top:16px;display:flex;flex-wrap:wrap;gap:20px\\"><a class=\\"pxt-link\\" href=\\"/solutions/pompe-a-chaleur-tertiaire/\\">Pompe à chaleur tertiaire <span class=\\"fa fa-arrow-right\\"></span></a><a class=\\"pxt-link\\" href=\\"/solutions/recuperation-de-chaleur/\\">Récupération de chaleur <span class=\\"fa fa-arrow-right\\"></span></a></p></div></div></div></div></section>\\n<section class=\\"pxt-sec pxt-dark\\"><div class=\\"pxt-c\\"><span class=\\"pxt-k\\">Chantier</span><h2>Le chantier étape par étape</h2><div class=\\"pxr-steps\\"><div><b>1</b><strong>Étude</strong><p>Relevé de la chaufferie fioul et de la centrale froid, besoins de chauffage du magasin.</p></div><div><b>2</b><strong>Dimensionnement</strong><p>Deux pompes à chaleur de 30 kW en cascade, échangeur sur la centrale froid.</p></div><div><b>3</b><strong>Travaux</strong><p>En magasin ouvert, mise en service avant la saison de chauffe.</p></div><div><b>4</b><strong>Contrôle et suivi</strong><p>Contrôle de conformité et suivi des consommations dans le cadre du contrat de performance.</p></div></div></div></section>\\n<section class=\\"pxt-sec\\"><div class=\\"pxt-c\\"><span class=\\"pxt-k\\">En images</span><h2>Avant et après travaux</h2><div class=\\"pxr-ba pxr-ba--1 pxt-rv\\"><figure><img src=\\"/uploads/pexen-intermarche-pose-pac-00a823f1.webp\\" alt=\\"Installation des pompes à chaleur air-eau chez Intermarché\\" loading=\\"lazy\\"><figcaption>Le projet</figcaption></figure></div>\\n<div style=\\"margin-top:44px\\"><span class=\\"pxt-k\\">Résultats</span><h2>Les chiffres du projet</h2><div class=\\"pxr-res pxt-rv\\"><div>Fioul supprimé pour le chauffage du magasin.</div><div>Chaleur des groupes froids réutilisée pour le chauffage.</div><div>Objectif de −40 % de consommation sur 10 ans, suivi par contrat de performance énergétique*.</div></div>\\n<p class=\\"pxr-note\\">* Volume d'économies d'énergie estimé selon les fiches d'opérations standardisées mobilisées : le kWh cumac cumule et actualise les économies sur la durée de vie conventionnelle des équipements. Il ne constitue pas une mesure des consommations réelles.<br>* Objectif contractuel de réduction des consommations, sur le périmètre et la durée du contrat de performance énergétique (10 ans), à conditions d'exploitation comparables.</p></div></div></section>\\n<section class=\\"pxt-sec\\" style=\\"padding-top:0\\"><div class=\\"pxt-c\\"><span class=\\"pxt-k\\">Autres réalisations</span><div class=\\"pxr-next\\" style=\\"margin-top:18px\\"><a href=\\"/realisations/carrefour-market-recuperation-de-chaleur/\\"><img src=\\"/uploads/pexen-reference-carrefour-market-3649b191.webp\\" alt=\\"Carrefour Market\\" loading=\\"lazy\\"><div><small>Carrefour Market · Île-de-France</small><b>535 kW de chaleur récupérée sur le froid commercial</b></div></a><a href=\\"/realisations/cedim-destratification/\\"><img src=\\"/uploads/pexen-reference-cedim-964b62c5.webp\\" alt=\\"CEDIM\\" loading=\\"lazy\\"><div><small>CEDIM · Centre-Val de Loire</small><b>9 m de hauteur traitée par déstratification</b></div></a></div>\\n<div class=\\"pxt-band pxt-rv\\" style=\\"margin-top:40px\\"><img src=\\"/uploads/pexen-reference-intermarche-f0413e6e.webp\\" alt=\\"Intermarché\\" loading=\\"lazy\\"><div><span class=\\"pxt-k\\">Votre projet</span><h2>Un projet ? Parlons-en.</h2><p>Prise de contact sous 48 h ouvrées par un ingénieur PEXEN, pour qualifier votre besoin et définir les prochaines étapes.</p><div class=\\"pxt-hero__act\\"><a class=\\"pxt-btn\\" href=\\"/contact/\\">Parler de votre projet <span class=\\"fa fa-arrow-right\\"></span></a><a class=\\"pxt-btn pxt-btn--ghost\\" href=\\"/simulateur-prime-cee/\\">Estimer le financement</a></div></div></div></div></section></div>"}, "type": "html", "style": {"background": "white", "paddingTop": "none", "paddingBottom": "none"}}, {"id": "b-dzt2othi", "data": {"html": "<section aria-label=\\"Le chantier Intermarché en images\\" style=\\"max-width:1140px;margin:auto;padding:48px 24px;text-align:left\\"><h2>Le chantier Intermarché en images</h2><div style=\\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:24px\\"><figure style=\\"margin:0;background:#f2f6f8;border-radius:8px;overflow:hidden\\"><img src=\\"/uploads/pexen-intermarche-condenseur-avant-5db3cb2e.webp\\" alt=\\"Condenseur en toiture chez Intermarché avant travaux\\" loading=\\"lazy\\" style=\\"width:100%;height:360px;object-fit:contain;display:block\\"><figcaption style=\\"padding:16px\\">Condenseur en toiture chez Intermarché avant travaux</figcaption></figure><figure style=\\"margin:0;background:#f2f6f8;border-radius:8px;overflow:hidden\\"><img src=\\"/uploads/pexen-intermarche-coffret-pac-2c6faf26.webp\\" alt=\\"Coffret électrique des pompes à chaleur air-eau chez Intermarché\\" loading=\\"lazy\\" style=\\"width:100%;height:360px;object-fit:contain;display:block\\"><figcaption style=\\"padding:16px\\">Coffret électrique des pompes à chaleur air-eau chez Intermarché</figcaption></figure></div></section>"}, "type": "html", "style": {}}, {"id": "b-lnxsgztx", "data": {"image": "/uploads/pexen-reference-intermarche-f0413e6e.webp", "intro": "Bourgogne-Franche-Comté · Grande distribution", "title": "Intermarché : sortir du fioul et optimiser le froid", "buttons": [{"id": "btn-odz73h5x", "icon": "arrow", "link": "/contact/?demande=etude", "label": "Demander une étude", "variant": "primary"}, {"id": "btn-5csdt194", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}], "eyebrow": "Réalisations", "imageAlt": "Entrée du supermarché Intermarché", "highlight": "", "breadcrumb": true, "parentLink": "/realisations/", "heroVariant": "solution"}, "type": "pageHeader", "style": {"background": "navy", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "md"}}, {"id": "b-q0uasn52", "data": {"intro": "", "items": [{"id": "s-vae9k8pj", "num": "01", "text": "Inventaire des équipements, consommations et contraintes d’exploitation.", "title": "Relevé sur site"}, {"id": "s-wesqvad1", "num": "02", "text": "Bouquet d’actions et fiches CEE mobilisables, avant devis.", "title": "Dimensionnement"}, {"id": "s-yjcjzyha", "num": "03", "text": "Installation sans fermer le magasin ni arrêter la production.", "title": "Travaux"}, {"id": "s-qia6ft7p", "num": "04", "text": "Pièces constituées pour le contrôle et le versement de la prime.", "title": "Dossier CEE"}], "style": "timeline", "title": "De l’étude au dossier CEE", "buttons": [], "eyebrow": "Mission PEXEN", "deliverableLabel": "Livrable"}, "type": "steps", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "md"}}, {"id": "b-n3h8u8xy", "data": {"html": "<article class=\\"px-ultra-case\\">\\n  <div class=\\"px-ultra-case__kpi\\"><span class=\\"px-ultra-case__kpi-label\\">Résultat</span><p class=\\"px-ultra-case__kpi-value\\">14,8 GWh cumac d’économies d’énergie estimées* · sortie complète du fioul</p></div>\\n  <div class=\\"px-ultra-case__grid\\">\\n    <section class=\\"px-ultra-case__panel\\">\\n      <span class=\\"px-ultra-case__num\\" aria-hidden=\\"true\\">01</span>\\n      <h3 class=\\"px-ultra-case__h\\">L’enjeu</h3>\\n      <p class=\\"px-ultra-case__p\\">Un supermarché chauffé par deux chaudières fioul vétustes, une production de froid commercial énergivore et un objectif de décarbonation.</p>\\n    </section>\\n    <section class=\\"px-ultra-case__panel\\">\\n      <span class=\\"px-ultra-case__num\\" aria-hidden=\\"true\\">02</span>\\n      <h3 class=\\"px-ultra-case__h\\">Client &amp; site</h3>\\n      <p class=\\"px-ultra-case__p\\"><strong>Intermarché</strong><br/>Bourgogne-Franche-Comté<br/>Bourgogne-Franche-Comté · Grande distribution</p>\\n    </section>\\n    <section class=\\"px-ultra-case__panel\\">\\n      <span class=\\"px-ultra-case__num\\" aria-hidden=\\"true\\">03</span>\\n      <h3 class=\\"px-ultra-case__h\\">Fiches CEE mobilisées</h3>\\n      <div class=\\"px-ultra-case__tags\\"><span class=\\"px-ultra-case__tag\\">BAT-TH-163 (Coup de pouce)</span><span class=\\"px-ultra-case__tag\\">BAT-TH-139</span><span class=\\"px-ultra-case__tag\\">BAT-TH-134</span><span class=\\"px-ultra-case__tag\\">BAT-TH-116</span><span class=\\"px-ultra-case__tag\\">BAT-TH-142</span><span class=\\"px-ultra-case__tag\\">BAT-EQ-124</span></div>\\n    </section>\\n  </div>\\n  <section class=\\"px-ultra-ops\\">\\n    <header class=\\"px-ultra-ops__head\\">\\n      <span class=\\"px-ultra-ops__eyebrow\\">Travaux</span>\\n      <h2 class=\\"px-ultra-ops__title\\">Les solutions</h2>\\n      <p class=\\"px-ultra-ops__lead\\">Plusieurs opérations combinées sur un même site, dimensionnées pour rester éligibles CEE.</p>\\n    </header>\\n    <div class=\\"px-ultra-ops__grid\\"><article class=\\"px-ultra-op\\">\\n      <span class=\\"px-ultra-op__num\\">01</span>\\n      <h3 class=\\"px-ultra-op__title\\">Pompe à chaleur air/eau en remplacement du fioul</h3>\\n    </article><article class=\\"px-ultra-op\\">\\n      <span class=\\"px-ultra-op__num\\">02</span>\\n      <h3 class=\\"px-ultra-op__title\\">Récupération de chaleur sur le groupe froid</h3>\\n    </article><article class=\\"px-ultra-op\\">\\n      <span class=\\"px-ultra-op__num\\">03</span>\\n      <h3 class=\\"px-ultra-op__title\\">Déstratification d’air de la surface de vente</h3>\\n    </article><article class=\\"px-ultra-op\\">\\n      <span class=\\"px-ultra-op__num\\">04</span>\\n      <h3 class=\\"px-ultra-op__title\\">GTB de classe B</h3>\\n    </article><article class=\\"px-ultra-op\\">\\n      <span class=\\"px-ultra-op__num\\">05</span>\\n      <h3 class=\\"px-ultra-op__title\\">Fermeture des meubles frigorifiques et haute pression flottante</h3>\\n    </article></div>\\n  </section>\\n</article>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-cvnggskv", "data": {"html": "<p class=\\"text-xs text-slate-500 px-ultra-legal-note\\">* Estimation calculée selon les fiches d’opérations standardisées CEE mobilisées (arrêté du 22 décembre 2014 modifié). Le kWh cumac cumule et actualise les économies sur la durée de vie conventionnelle des équipements ; il ne mesure pas les consommations réelles.</p>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-19pwhnr7", "data": {"text": "Un ingénieur PEXEN étudie votre site et vous répond sous 48 h ouvrées.", "title": "Un projet similaire ?", "layout": "centered", "buttons": [{"id": "btn-2fb6t75v", "icon": "arrow", "link": "/contact/?demande=etude", "label": "Demander une étude", "variant": "primary"}, {"id": "btn-c3vhjwen", "icon": "phone", "link": "tel:+33141935280", "label": "01 41 93 52 80", "variant": "secondary"}], "variant": "dark"}, "type": "cta", "style": {"background": "navy", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-pxt-css", "data": {"html": "<style>/* ===== pxt (Secteurs) ===== */\\n.pxt{--n:#082D4A;--c:#01CDF3;--p:#009FCC;--pd:#00769A;--b:#D5E1E6;--m:#5A6B7B;font-family:Figtree,system-ui,sans-serif;color:#3E5163;text-align:left}\\n.pxt *{box-sizing:border-box}\\n.pxt h1,.pxt h2,.pxt h3{font-family:Sora,system-ui,sans-serif;color:var(--n);margin:0}\\n.pxt p{margin:0 0 12px;line-height:1.7;font-size:16px}\\n.pxt-c{max-width:1296px;margin:0 auto;padding:0 24px;position:relative}\\n.pxt-sec{padding:72px 0;position:relative;overflow:hidden}\\n.pxt-k{display:inline-flex;align-items:center;gap:10px;font-size:12px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--pd)}\\n.pxt-k::before{content:\\"\\";width:28px;height:2px;background:var(--c)}\\n.pxt h2{font-size:clamp(28px,2.8vw,42px);line-height:1.15;letter-spacing:-.015em;margin:14px 0 14px}\\n.pxt-lead{font-size:17.5px!important;color:var(--m);max-width:720px}\\n.pxt-btn{display:inline-flex;align-items:center;gap:10px;height:48px;padding:0 26px;border-radius:6px;background:var(--c);color:var(--n)!important;font-weight:600;font-size:16px;text-decoration:none!important;transition:transform .2s,box-shadow .2s}\\n.pxt-btn:hover{transform:translateY(-2px);box-shadow:0 12px 26px rgba(1,205,243,.35)}\\n.pxt-btn--ghost{background:transparent;border:1px solid rgba(255,255,255,.5);color:#fff!important}\\n.pxt-btn--line{background:transparent;border:1px solid rgba(8,45,74,.3);color:var(--n)!important}\\n.pxt-link{display:inline-flex;gap:8px;align-items:center;font-weight:700;color:var(--pd)!important;text-decoration:none!important}\\n.pxt-link:hover{gap:12px}\\n.pxt-tag{display:inline-block;font-size:12px;font-weight:700;color:var(--pd);background:#E3F7FC;border-radius:6px;padding:5px 9px}\\n.pxt-hero{position:relative;min-height:640px;display:flex;align-items:flex-end;color:#fff;overflow:hidden;background:var(--n)}\\n.pxt-hero__bg{position:absolute;inset:0;margin:0}\\n.pxt-hero__bg img{width:100%;height:100%;object-fit:cover;transform:scale(1.04)}\\n.pxt-hero::before{content:\\"\\";position:absolute;inset:0;z-index:1;background:linear-gradient(90deg,rgba(8,45,74,.96) 0%,rgba(8,45,74,.86) 38%,rgba(8,45,74,.35) 72%,rgba(8,45,74,.15) 100%)}\\n.pxt-hero::after{content:attr(data-word);position:absolute;z-index:1;right:-10px;bottom:-34px;font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:clamp(90px,13vw,200px);line-height:1;color:transparent;-webkit-text-stroke:1.5px rgba(1,205,243,.28);letter-spacing:-.03em;pointer-events:none;white-space:nowrap}\\n.pxt-hero .pxt-c{z-index:2;width:100%;padding-top:96px;padding-bottom:72px;display:grid;grid-template-columns:7fr 5fr;gap:48px;align-items:end}\\n.pxt-crumbs{font-size:13px;color:rgba(255,255,255,.65);margin-bottom:18px}\\n.pxt-crumbs a{color:rgba(255,255,255,.8)!important;text-decoration:none!important}\\n.pxt-hero .pxt-k{color:var(--c)}\\n.pxt-hero h1{color:#fff;font-size:clamp(34px,4vw,58px);line-height:1.06;letter-spacing:-.02em;margin:14px 0 14px}\\n.pxt-hero__sub{font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:clamp(19px,1.7vw,24px);line-height:1.35;color:var(--c);margin:0 0 16px!important;max-width:640px}\\n.pxt-hero__desc{color:rgba(255,255,255,.82);max-width:600px;font-size:16.5px!important}\\n.pxt-hero__act{display:flex;flex-wrap:wrap;gap:12px;margin-top:26px}\\n.pxt-figs{display:grid;gap:12px}\\n.pxt-fig{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);border-radius:16px;padding:18px 22px;display:grid;grid-template-columns:auto 1fr;gap:16px;align-items:center}\\n.pxt-fig b{font-family:Sora,system-ui,sans-serif;font-size:30px;line-height:1;color:var(--c);white-space:nowrap}\\n.pxt-fig span{font-size:14px;color:rgba(255,255,255,.85);line-height:1.4}\\n.pxt-enj{display:grid;grid-template-columns:repeat(3,1fr);gap:0;border-top:1px solid var(--b);margin-top:36px}\\n.pxt-enj>div{padding:34px 30px 30px;border-right:1px solid var(--b);position:relative;transition:background .3s}\\n.pxt-enj>div:last-child{border-right:0}\\n.pxt-enj>div::before{content:\\"\\";position:absolute;left:0;top:-1px;height:3px;width:0;background:var(--c);transition:width .5s}\\n.pxt-enj>div:hover{background:#F6FAFC}.pxt-enj>div:hover::before{width:100%}\\n.pxt-enj i{display:block;font-style:normal;font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:76px;line-height:1;color:transparent;-webkit-text-stroke:1.5px var(--p);margin-bottom:18px}\\n.pxt-enj h3{font-size:20px;margin-bottom:10px}\\n.pxt-enj p{font-size:15px!important;color:var(--m)}\\n.pxt-enj .pxt-link{margin-top:6px;font-size:14.5px}\\n.pxt-dark{background:radial-gradient(circle at 0% 0%,rgba(1,205,243,.14),transparent 40%),var(--n);color:rgba(255,255,255,.8)}\\n.pxt-dark h2,.pxt-dark h3{color:#fff}.pxt-dark .pxt-k{color:var(--c)}.pxt-dark .pxt-lead{color:rgba(255,255,255,.72)}\\n.pxt-tabs{display:grid;grid-template-columns:330px 1fr;gap:28px;margin-top:36px;align-items:stretch}\\n.pxt-tabs>input{position:absolute;opacity:0;pointer-events:none}\\n.pxt-tabs__nav{display:grid;gap:8px;align-content:start}\\n.pxt-tabs__nav label{display:flex;align-items:center;gap:14px;cursor:pointer;padding:16px 18px;border-radius:12px;border:1px solid rgba(255,255,255,.14);color:rgba(255,255,255,.85);font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:16px;transition:all .25s}\\n.pxt-tabs__nav label i{font-style:normal;font-size:12px;font-weight:800;color:var(--c);width:26px}\\n.pxt-tabs__nav label:hover{background:rgba(255,255,255,.06)}\\n.pxt-tabs__panels{position:relative;min-height:400px}\\n.pxt-panel{display:none;grid-template-columns:1fr 1fr;border-radius:20px;overflow:hidden;background:#fff;height:100%;animation:pxtFade .4s ease}\\n.pxt-panel figure{margin:0;position:relative;min-height:400px}.pxt-panel figure img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\\n.pxt-panel>div{padding:34px 34px 30px;display:flex;flex-direction:column;justify-content:center}\\n.pxt-panel h3{color:var(--n)!important;font-size:24px;margin-bottom:12px}\\n.pxt-panel p{color:#3E5163;font-size:15.5px!important}\\n.pxt-panel .pxt-note{font-size:13px!important;color:var(--m);background:#F2F6F9;border-radius:8px;padding:10px 12px}\\n@keyframes pxtFade{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}\\n.pxt-tabs>input:nth-of