ng:.08em;text-transform:uppercase;padding:16px 18px!important}\\n.px-ultra-table-wrap tbody td{padding:14px 18px!important;vertical-align:middle;border-color:var(--pxb)!important}\\n.px-ultra-table-wrap tbody tr:nth-child(even) td{background:var(--pxice)}\\n.px-ultra-table-wrap tbody td:nth-child(3),.px-ultra-table-wrap tbody td:nth-child(4){font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.82rem;font-weight:600;color:var(--pxn);white-space:nowrap}\\n.px-ultra-table-wrap tbody td:first-child{font-weight:600;color:var(--pxn)}\\n\\n/* Frise : trait continu du point 01 au point 05 */\\n@media(min-width:992px){.px-ultra-timeline__track{left:22px!important;right:calc((100% - 80px) / 5 - 22px)!important}}\\n\\n.px-ultra-ft__legal-notes{display:none!important}\\n\\n\\n/* Rythme resserré */\\n@media(max-width:767px){section.sec-padding,section.px-ultra-real-sec--standalone,section.px-ultra-ed:has(.px-ultra-ed__title){padding-top:64px!important;padding-bottom:64px!important}}\\n/* Logos RGE : Qualisol à la taille de QualiPAC */\\n.px-ultra-preuves__quali-item img[src*=\\"qualisol\\"]{height:52px!important;width:auto!important;max-height:none!important}\\n.px-ultra-garant-logo[src*=\\"qualisol\\"]{height:64px!important;width:auto!important;max-height:none!important}\\n/* Bandeau Estimer le financement */\\n#estimation{padding:88px 0!important;border:0!important;background:#fff!important}\\n#estimation .container>.row{position:relative;overflow:hidden;margin:0;padding:48px 56px;border:1px solid var(--pxb);border-radius:24px;background:linear-gradient(135deg,#EEF4FA 0%,#E2EDF5 100%);box-shadow:0 16px 40px rgba(8,45,74,.08)}\\n#estimation .container>.row::after{content:\\"\\";position:absolute;right:-80px;top:-80px;width:260px;height:260px;border-radius:50%;background:radial-gradient(circle,rgba(1,205,243,.28),transparent 70%);pointer-events:none}\\n#estimation h2{font-family:Sora,sans-serif;font-size:clamp(24px,2.4vw,32px)!important;font-weight:700;line-height:1.2;margin-bottom:12px!important}\\n#estimation h2::before{content:\\"Estimation\\";display:block;margin-bottom:10px;font-family:Figtree,sans-serif;font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--pxpd)}\\n#estimation p.small{font-size:16px!important;line-height:1.6;color:#3a4a5a!important;max-width:580px;margin-bottom:8px!important}\\n#estimation .btn.px-cta{position:relative;z-index:1;display:inline-flex;align-items:center;gap:10px;padding:18px 30px!important;border:0!important;border-radius:999px!important;background:var(--pxn)!important;color:#fff!important;font-size:15px;font-weight:700;box-shadow:0 10px 24px rgba(8,45,74,.22);transition:background .2s,transform .2s}\\n#estimation .btn.px-cta:hover{background:var(--pxpd)!important;transform:translateY(-2px)}\\n@media(max-width:767px){#estimation{padding:56px 0!important}#estimation .container>.row{padding:32px 24px}}\\n/* Footer : hiérarchie */\\nfooter.px-ultra-ft .container{max-width:1320px!important;padding-left:24px!important;padding-right:24px!important}\\n.px-ultra-ft__about{display:none!important}\\n.px-ultra-ft__nl{display:grid!important;grid-template-columns:minmax(0,1fr) minmax(0,460px);gap:48px;align-items:center;max-width:1080px;margin:0 auto 56px!important;padding:36px 44px!important;border:1px solid rgba(255,255,255,.12);border-radius:20px;background:rgba(255,255,255,.05);backdrop-filter:blur(6px)}\\n.px-ultra-ft__nl-form{max-width:none!important;width:100%!important}\\n.px-ultra-ft__nl-title{font-size:24px!important;margin-bottom:6px!important}\\n.px-ultra-ft__main{padding-top:56px!important;border-top:1px solid rgba(255,255,255,.1)!important}\\n.px-ultra-ft__grid{grid-template-columns:1.4fr repeat(4,minmax(0,1fr))!important;gap:40px!important}\\n.px-ultra-ft__brand{display:flex;flex-direction:column;gap:14px}\\n.px-ultra-ft__baseline{order:2;font-size:15px!important;font-weight:500!important;color:rgba(255,255,255,.72)!important;margin:0!important}\\n.px-u