xk-plan__r{background:linear-gradient(160deg,#EEF4FA,#E0ECF5);padding:40px 44px;display:flex;flex-direction:column;justify-content:center;gap:12px}\\n.pxk-step{display:flex;align-items:center;gap:14px;background:#fff;border:1px solid #D5E1E6;border-radius:12px;padding:14px 18px}\\n.pxk-step b{font-family:Sora,system-ui,sans-serif;font-size:15px;color:#082D4A;font-weight:600}\\n.pxk-step span{display:block;font-size:13px;color:#5A6B7B}\\n.pxk-tag{margin-left:auto;font-size:12px;font-weight:700;color:#00769A;background:#E3F7FC;border-radius:6px;padding:5px 10px;white-space:nowrap}\\n.pxk-check{width:26px;height:26px;border-radius:50%;background:#01CDF3;color:#082D4A;display:inline-flex;align-items:center;justify-content:center;font-size:12px;flex:0 0 26px}\\n/* Financement */\\n.pxk-split{display:grid;grid-template-columns:1.25fr 1fr;gap:48px;align-items:start}\\n.pxk-rows{display:grid;gap:14px;margin-top:8px}\\n.pxk-row{display:flex;gap:16px;align-items:flex-start;background:#fff;border:1px solid #D5E1E6;border-radius:14px;padding:18px 20px}\\n.pxk-row h3{font-size:16px;margin:2px 0 4px}\\n.pxk-row p{margin:0;font-size:14.5px}\\n.pxk-dark{background:#082D4A;border-radius:18px;padding:36px 34px;color:rgba(255,255,255,.8);box-shadow:0 20px 50px rgba(8,45,74,.18);position:sticky;top:110px}\\n.pxk-dark h3{color:#fff;font-size:21px;margin-bottom:20px}\\n.pxk-num{display:flex;gap:14px;align-items:flex-start;padding:14px 0;border-top:1px solid rgba(255,255,255,.12)}\\n.pxk-num i{font-style:normal;font-family:Sora,system-ui,sans-serif;font-weight:700;color:#01CDF3;font-size:22px;line-height:1;min-width:30px}\\n.pxk-num p{margin:0;font-size:15px;color:rgba(255,255,255,.85)}\\n.pxk-dark .pxk-btn{margin-top:22px}\\n/* Chaîne de cohérence (AMO) */\\n.pxk-chain{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;gap:16px;align-items:stretch}\\n.pxk-node{background:#fff;border:1px solid #D5E1E6;border-radius:16px;padding:26px 24px;text-align:left;box-shadow:0 12px 32px rgba(8