:translateY(-2px)}\\n.pxk-start b{font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:17px}\\n.pxk-start span{font-size:14px;color:#5A6B7B}\\n.pxk-pill{font-size:13px;font-weight:700;color:#082D4A;background:#E3F7FC;border-radius:6px;padding:8px 14px;white-space:nowrap}\\n.pxk-start .fa{color:#00769A}\\n/* Comparatif */\\n.pxk-vs{display:grid;grid-template-columns:1fr 1fr;gap:20px}\\n.pxk-vs>div{border-radius:16px;padding:28px}\\n.pxk-vs__a{background:#fff;border:1px solid #D5E1E6}\\n.pxk-vs__b{background:#082D4A;color:rgba(255,255,255,.85)}\\n.pxk-vs__b h3{color:#fff}\\n.pxk-vs ul{list-style:none;padding:0;margin:14px 0 0;display:grid;gap:12px}\\n.pxk-vs li{display:flex;gap:12px;align-items:flex-start;font-size:15px;line-height:1.5}\\n.pxk-vs li i{margin-top:3px}\\n.pxk-vs__a li i{color:#9AA9B5}\\n.pxk-vs__b li i{color:#01CDF3}\\n@media(max-width:991px){.pxk-grid3,.pxk-plan,.pxk-split,.pxk-vs{grid-template-columns:1fr}.pxk-grid4{grid-template-columns:1fr 1fr}.pxk-chain{grid-template-columns:1fr}.pxk-arrow{transform:rotate(90deg);justify-self:center}.pxk-dark{position:static}.pxk-plan__l,.pxk-plan__r{padding:32px 24px}.pxk-start a{grid-template-columns:1fr;gap:10px}}\\n@media(max-width:575px){.pxk-grid4{grid-template-columns:1fr}.pxk{padding:56px 0}}\\n/* Catalogue collé au tableau */\\n.px-block-typo:has(.px-ultra-table-sec) .px-ultra-table-sec{padding-bottom:20px!important}\\n.px-block-typo:has(.px-ultra-table-sec)+.px-block-typo .px-ultra-ed{background:#EEF3F7!important;padding:0 0 72px!important}\\n.px-block-typo:has(.px-ultra-table-sec)+.px-block-typo .px-ultra-ed__inner{display:block!important;text-align:center}\\n\\n.pxk-head--left{text-align:left!important}\\n.pxk-card,.pxk-row,.pxk-step,.pxk-dark,.pxk-node,.pxk-tile,.pxk-vs>div,.pxk-plan__l{text-align:left!important}\\n.pxk-callout{text-align:center!important}\\n.px-block-typo:has(.px-ultra-table-sec)+.px-block-typo .px-ultra-ed__prose{text-align:center!important;max-width:none!important;margin: