ps{justify-content:center}\\n.pxr-hero--giant{grid-template-columns:5fr 6fr}\\n.pxr-hero--giant>div{padding:110px 40px 64px max(24px,calc((100vw - 1296px)/2 + 24px));display:flex;flex-direction:column;justify-content:center}\\n.pxr-giant{font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:clamp(120px,15vw,230px);line-height:.85;color:transparent;-webkit-text-stroke:2px var(--c);letter-spacing:-.04em;margin-bottom:6px}\\n.pxr-giant+small{display:block;font-size:13px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--c);margin-bottom:10px}\\n.pxr-hero--giant figure{margin:0;position:relative;clip-path:polygon(14% 0,100% 0,100% 100%,0 100%)}.pxr-hero--giant figure img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\\n.pxr-figs{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:1px;background:rgba(255,255,255,.12);border-radius:18px;overflow:hidden;margin-top:-56px;position:relative;z-index:3;box-shadow:0 24px 50px rgba(8,45,74,.25)}\\n.pxr-figs>div{background:#0B3A5E;padding:24px 22px;color:rgba(255,255,255,.8)}\\n.pxr-figs b{display:block;font-family:Sora,system-ui,sans-serif;font-size:clamp(26px,2.4vw,34px);color:var(--c);line-height:1.05;margin-bottom:6px}\\n.pxr-figs span{font-size:13.5px;line-height:1.4;display:block}\\n.pxr-story{display:grid;grid-template-columns:300px 1fr;gap:56px;padding:44px 0;border-top:1px solid var(--b)}\\n.pxr-story:first-child{border-top:0}\\n.pxr-story__k{position:sticky;top:150px;align-self:start}\\n.pxr-story__k i{display:block;font-style:normal;font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:64px;line-height:1;color:transparent;-webkit-text-stroke:1.5px var(--p)}\\n.pxr-story__k span{display:block;font-family:Sora,system-ui,sans-serif;font-weight:700;color:var(--n);font-size:19px;margin-top:10px}\\n.pxr-story h2{font-size:clamp(24px,2.2vw,32px)!important;margin:0 0 14px!important}\\n.pxr-story p{font-size:17px!important;line-height:1.75;color:#3E5163}\\n.pxr-ba{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:28px}\\n.pxr-ba figure{margin:0;position:relative;border-radius:18px;overflow:hidden;min-height:340px}\\n.pxr-ba img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\\n.pxr-ba figcaption{position:absolute;left:16px;top:16px;background:var(--n);color:#fff;font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;border-radius:6px;padding:7px 12px}\\n.pxr-ba figure:last-child figcaption{background:var(--c);color:var(--n)}\\n.pxr-ba--1{grid-template-columns:1fr}.pxr-ba--1 figure{min-height:460px}\\n.pxr-steps{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;position:relative;margin-top:28px}\\n.pxr-steps::before{content:\\"\\";position:absolute;top:22px;left:12%;right:12%;height:2px;background:repeating-linear-gradient(90deg,var(--c) 0 10px,transparent 10px 18px)}\\n.pxr-steps>div{position:relative;text-align:left}\\n.pxr-steps b{display:grid;place-items:center;width:44px;height:44px;border-radius:50%;background:var(--c);color:var(--n);font-family:Sora,system-ui,sans-serif;font-size:16px;margin-bottom:14px;box-shadow:0 0 0 6px var(--n);position:relative}\\n.pxr-steps strong{display:block;font-family:Sora,system-ui,sans-serif;color:#fff;font-size:16.5px;margin-bottom:6px}\\n.pxr-steps p{color:rgba(255,255,255,.75);font-size:14.5px!important;margin:0}\\n.pxr-res{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:24px}\\n.pxr-res>div{background:#fff;border:1px solid var(--b);border-radius:16px;padding:22px;display:flex;gap:14px;align-items:flex-start;font-size:15.5px;color:var(--n);line-height:1.5}\\n.pxr-res>div::before{content:\\"\\\\f00c\\";font-family:\\"Font Awesome 5 Free\\",\\"FontAwesome\\";font-weight:900;flex:0 0 32px;height:32px;border-radius:50%;background:#E3F7FC;color:var(--pd);display:grid;place-items:center;font-size:13px}\\n.pxr-note{font-size:12.5px!important;color:var(--m);line-height:1.6;margin-top:18px!important}\\n.pxr-next{display:grid;grid-template-columns:1fr 1fr;gap:16px}\\n.pxr-next a{position:relative;display:block;border-radius:18px;overflow:hidden;min-height:220px;text-decoration:none!important}\\n.pxr-next img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .6s}.pxr-next a:hover img{transform:scale(1.05)}\\n.pxr-next a::after{content:\\"\\";position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,45,74,.92),rgba(8,45,74,.4))}\\n.pxr-next a>div{position:absolute;z-index:1;left:26px;right:26px;top:50%;transform:translateY(-50%);color:#fff}\\n.pxr-next small{display:block;font-size:11.5px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--c);margin-bottom:8px}\\n.pxr-next b{font-family:Sora,system-ui,sans-serif;font-size:21px;line-height:1.3;font-weight:600}\\n/* Liste */\\n.pxr-filter{display:flex;flex-wrap:wrap;gap:8px;margin:26px 0 22px}\\n.pxr-list>input{position:absolute;opacity:0;pointer-events:none}\\n.pxr-filter label{cursor:pointer;border:1px solid var(--b);border-radius:30px;padding:9px 18px;font-weight:700;font-size:14.5px;color:var(--n);background:#fff;transition:all .2s}\\n.pxr-list>input:nth-of-type(1):checked~.pxr-filter label:nth-of-type(1),.pxr-list>input:nth-of-type(2):checked~.pxr-filter label:nth-of-type(2),.pxr-list>input:nth-of-type(3):checked~.pxr-filter label:nth-of-type(3){background:var(--n);border-color:var(--n);color:#fff}\\n.pxr-list>input:nth-of-type(2):checked~.pxr-grid>[data-s]:not([data-s=\\"ter\\"]),.pxr-list>input:nth-of-type(3):checked~.pxr-grid>[data-s]:not([data-s=\\"ind\\"]){display:none}\\n.pxr-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px}\\n.pxr-card{position:relative;display:flex;flex-direction:column;border-radius:20px;overflow:hidden;background:#fff;border:1px solid var(--b);text-decoration:none!important;transition:transform .3s,box-shadow .3s}\\na.pxr-card:hover{transform:translateY(-4px);box-shadow:0 22px 44px rgba(8,45,74,.12)}\\n.pxr-card figure{margin:0;position:relative;height:280px;overflow:hidden}.pxr-card figure img{width:100%;height:100%;object-fit:cover;transition:transform .6s}\\na.pxr-card:hover figure img{transform:scale(1.05)}\\n.pxr-card figure span{position:absolute;left:16px;top:16px;background:rgba(8,45,74,.88);color:#fff;border-radius:6px;padding:6px 11px;font-size:12px;font-weight:700}\\n.pxr-card>div{padding:24px 26px 26px;display:flex;flex-direction:column;gap:6px;flex:1}\\n.pxr-card h3{font-size:22px!important}\\n.pxr-card small{font-size:13px;color:var(--m);font-weight:600}\\n.pxr-card .pxr-main{font-family:Sora,system-ui,sans-serif;font-weight:700;font-size:24px;color:var(--pd);line-height:1.25;margin-top:8px}\\n.pxr-card .pxr-sec2{display:flex;flex-wrap:wrap;gap:8px;margin-top:6px}\\n.pxr-card .pxr-sec2 em{font-style:normal;background:#F2F6F9;border-radius:6px;padding:6px 10px;font-size:13.5px;font-weight:700;color:var(--n)}\\n.pxr-card .pxt-link{margin-top:auto;padding-top:14px}\\n.pxr-card--wip{background:#F7FAFC}.pxr-card--wip .pxr-main{color:var(--n);font-size:18px}\\n.pxr-total{display:grid;grid-template-columns:auto 1fr;gap:40px;align-items:center;background:radial-gradient(circle at 100% 0,rgba(1,205,243,.2),transparent 50%),var(--n);border-radius:22px;padding:40px 44px;color:rgba(255,255,255,.8)}\\n.pxr-total b{font-family:Sora,system-ui,sans-serif;font-size:clamp(46px,5.4vw,76px);line-height:1;color:var(--c);white-space:nowrap}\\n.pxr-total strong{display:block;color:#fff;font-family:Sora,system-ui,sans-serif;font-size:20px;margin-bottom:8px}\\n.pxr-total p{font-size:13px!important;color:rgba(255,255,255,.65);margin:0}\\n@media(max-width:991px){.pxr-hero--split,.pxr-hero--giant{grid-template-columns:1fr}.pxr-hero--split figure,.pxr-hero--giant figure{min-height:280px;clip-path:none}.pxr-hero--split>div,.pxr-hero--giant>div{padding:100px 24px 72px}.pxr-story{grid-template-columns:1fr;gap:10px}.pxr-story__k{position:static}.pxr-ba,.pxr-res,.pxr-next,.pxr-grid{grid-template-columns:1fr}.pxr-steps{grid-template-columns:1fr 1fr}.pxr-steps::before{display:none}.pxr-total{grid-template-columns:1fr;gap:14px}}\\n/* ===== /pxr ===== */</style>"}, "type": "html", "style": {"paddingTop": "none", "paddingBottom": "none"}}], "status": "published", "template": "default", "createdAt": "2026-10-21T10:54:58.550Z", "updatedAt": "2026-11-11T14:47:23.083Z", "publishedAt": "2026-10-21T10:54:58.550Z", "contentSource": "cms"}	admin@pexen.fr	2026-11-11 17:56:38.379685+01
0e5d7ce0-8c03-4f50-98fb-40d096444033	page	p-4r7evz3v	Notre approche	{"id": "p-4r7evz3v", "seo": {"slug": "notre-approche", "noindex": false, "nofollow": false, "seoTitle": "Audit énergétique, travaux et suivi : notre méthode | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "audit énergétique", "metaDescription": "De l'audit énergétique au bilan d'économies : prévisite, ingénierie technico-financière, installation, contrôle COFRAC et suivi. Un livrable à chaque étape."}, "path": "/notre-approche/", "title": "Notre approche", "blocks": [{"id": "b-pxt-0", "data": {"html": "<div class=\\"pxt\\"><section class=\\"pxa-hero\\"><div class=\\"pxt-c\\"><div class=\\"pxt-rv\\"><div class=\\"pxt-crumbs\\" style=\\"color:#5A6B7B\\"><a href=\\"/\\" style=\\"color:#00769A!important\\">Accueil</a> › Notre approche</div><h1>Notre approche</h1><p class=\\"pxa-man\\">Optimiser aujourd'hui. <span>Performer demain.</span></p><p class=\\"pxa-hero__desc\\">PEXEN réunit ingénierie et performance énergétique dans une même équipe. Nos ingénieurs relèvent les installations sur site, dimensionnent les équipements, et nos équipes les installent puis suivent les consommations.</p><div class=\\"pxt-hero__act\\"><a class=\\"pxt-btn\\" href=\\"/contact/\\">Parler de votre projet <span class=\\"fa fa-arrow-right\\"></span></a><a class=\\"pxt-btn pxt-btn--line\\" href=\\"/realisations/\\">Voir nos réalisations</a></div></div>\\n<figure class=\\"pxt-rv\\"><img src=\\"/themes/ultra-s/images/pexen/ingenieur-pexen-sur-site-ingenierie-et-performance-energetique.webp\\" alt=\\"Ingénieur PEXEN sur site\\" loading=\\"eager\\"><figcaption>Une seule équipe, <b>de la note de calcul au suivi</b></figcaption></figure></div></section>\\n<section class=\\"pxt-sec\\" style=\\"background:#F4F7FA\\"><div class=\\"pxt-c\\"><div class=\\"pxt-rv\\"><span class=\\"pxt-k\\">Notre histoire</span><h2>Pourquoi PEXEN existe</h2></div>\\n<div class=\\"pxa-story pxt-rv\\"><div><i>01 · Le constat</i><h3>La performance se perd entre deux métiers</h3><p>Un bureau d'études s'arrête au rapport. Un installateur dimensionne au catalogue. Entre les deux, chaque passage de relais crée un écart : une puissance revue, un planning qui ignore l'exploitation, un dossier incomplet.</p></div>\\n<div><i>02 · Le déclic</i><h3>Une même équipe, du relevé au suivi</h3><p><span class=\\"pxa-todo\\">[À compléter : année de création, fondateurs, ce qui a déclenché le projet]</span></p><p>De ce constat est née une conviction : la note de calcul, le chantier et le suivi doivent être portés par la même équipe.</p></div>\\n<div><i>03 · La marque</i><h3>PEXEN, un nom qui dit ce que nous faisons</h3><p>Réunir ingénierie et performance énergétique dans une même équipe. <span class=\\"pxa-todo\\">[À compléter : l'évolution vers la marque PEXEN et ce que vous souhaitez raconter du nom]</span></p></div>\\n<div><i>04 · Aujourd'hui</i><h3>Des sites qui ne s'arrêtent pas</h3><p>Les sites que nous traitons sont des supermarchés, des entrepôts, des usines et des bâtiments collectifs, souvent en exploitation pendant les travaux. Le froid, la chaleur, le pilotage et l'isolation y sont traités dans un même projet.</p></div></div></div></section>\\n<section class=\\"pxt-sec pxt-dark\\"><div class=\\"pxt-c\\"><div class=\\"pxa-quote pxt-rv\\"><span class=\\"pxt-k\\" style=\\"justify-content:center\\">Notre mission</span><p style=\\"margin-top:18px!important\\">Rendre la performance énergétique des sites industriels et tertiaires mesurable et durable, de la note de calcul au suivi des consommations.</p></div></div></section>\\n<section class=\\"pxt-sec\\"><div class=\\"pxt-c\\"><div class=\\"pxt-rv\\"><span class=\\"pxt-k\\">Méthode</span><h2>5 étapes, de l'étude au suivi</h2><p class=\\"pxt-lead\\">PEXEN dimensionne, réalise et suit le projet après l'étude. À chaque étape, un livrable vous est remis.</p></div>\\n<div class=\\"pxa-steps pxt-rv\\"><div class=\\"pxa-step\\"><b>01</b><h3>Étude et éligibilité</h3><p>Audit énergétique, relevés sur site et calcul du gisement. Étude de faisabilité technique et vérification de l'éligibilité aux dispositifs de financement.</p><em>Audit, relevés, étude de faisabilité et d'éligibilité</em></div><div class=\\"pxa-step\\"><b>02</b><h3>Ingénierie et planification</h3><p>Notes de dimensionnement, choix des équipements, devis et plan de financement. Planning des travaux et organisation de l'assistance à maîtrise d'ouvrage.</p><em>Notes de dimensionnement, devis, plan de financement, planning des travaux</em></div><div class=\\"pxa-step\\"><b>03</b><h3>Travaux et suivi de chantier</h3><p>Installation par nos équipes, suivi de chantier et AMO pour alléger votre charge, mise en service et réglages, sans interrompre l'exploitation.</p><em>Comptes rendus de chantier, réglages, essais, mise en service</em></div><div class=\\"pxa-step\\"><b>04</b><h3>Fin de travaux et contrôle</h3><p>Documents de fin de travaux et procès-verbal de réception. Pour les opérations CEE : contrôle par un organisme accrédité COFRAC (dossier, visite sur site, enquête de satisfaction client).</p><em>Documents de fin de travaux, PV de réception, rapport de contrôle COFRAC pour les opérations CEE</em></div><div class=\\"pxa-step\\"><b>05</b><h3>Prise en charge et suivi</h3><p>Rapport final et suivi du dossier de financement jusqu'à sa prise en charge complète. Suivi des consommations après travaux.</p><em>Rapport final, bilan des consommations avant / après</em></div></div></div></section>\\n<section class=\\"pxt-sec\\" style=\\"background:#F4F7FA\\"><div class=\\"pxt-c\\"><div class=\\"pxt-rv\\"><span class=\\"pxt-k\\">Valeurs</span><h2>Nos valeurs</h2></div>\\n<div class=\\"pxa-vals pxt-rv\\"><div class=\\"pxa-val\\" data-l=\\"E\\"><h3>Exigence</h3><p>La précision de l'ingénieur à chaque étape : aucune préconisation sans relevé, une note de calcul signée pour chaque solution.</p></div><div class=\\"pxa-val pxa-val--on\\" data-l=\\"E\\"><h3>Engagement</h3><p>Jusqu'au résultat suivi : un livrable à chaque étape, le suivi des consommations après travaux.</p></div><div class=\\"pxa-val\\" data-l=\\"I\\"><h3>Intégrité</h3><p>Des chiffres justes : une estimation est présentée comme une estimation, et les limites d'une solution sont expliquées dès l'étude.</p></div></div></div></section>\\n<section class=\\"pxt-sec\\"><div class=\\"pxt-c\\"><div class=\\"pxt-rv\\" style=\\"text-align:center;max-width:820px;margin:0 auto\\"><span class=\\"pxt-k\\">Notre différence</span><h2>Ingénierie, travaux et suivi réunis</h2></div>\\n<div class=\\"pxa-cmp pxt-rv\\"><div><small>Bureau d'études</small><h3>S'arrête au rapport</h3><p>Des préconisations, sans le chantier ni le suivi.</p></div><div><small>Installateur</small><h3>Dimensionne au catalogue</h3><p>Des équipements posés, sans note de calcul.</p></div><div><small>PEXEN</small><h3>Porte la note de calcul, le chantier et le suivi</h3><p>Le froid, la chaleur, le pilotage et l'isolation traités dans un même projet, par la même équipe. Le financement CEE y est intégré lorsqu'il est applicable.</p></div></div></div></section>\\n<section class=\\"pxt-sec\\" style=\\"background:#F4F7FA\\"><div class=\\"pxt-c\\"><div class=\\"pxt-split\\"><div class=\\"pxt-rv\\"><span class=\\"pxt-k\\">Garanties</span><h2>Qualifiés, assurés, contrôlés</h2><div class=\\"pxa-logos\\"><img src=\\"/themes/ultra-s/images/pexen/quali/qualipac.png\\" alt=\\"RGE QualiPAC\\"><img src=\\"/themes/ultra-s/images/pexen/quali/qualisol.png\\" alt=\\"RGE Qualisol\\"><img src=\\"/themes/ultra-s/images/pexen/quali/opqibi.png\\" alt=\\"OPQIBI\\"><img src=\\"/themes/ultra-s/images/pexen/quali/assurance-decennale.png\\" alt=\\"Assurance décennale\\"></div></div>\\n<div class=\\"pxt-rv\\"><ul class=\\"pxt-checks\\"><li>RGE QualiPAC (chauffage et eau chaude sanitaire) et RGE Qualisol CESI.</li><li>Audits énergétiques via notre bureau d'études partenaire Leo Energy : OPQIBI 1905 et 1717.</li><li>RC Pro et décennale MIC Insurance.</li><li>Opérations contrôlées par des organismes accrédités <a href=\\"https://www.cofrac.fr/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">COFRAC</a>.</li></ul></div></div></div></section></div>"}, "type": "html", "style": {"background": "white", "paddingTop": "none", "paddingBottom": "none"}}, {"id": "b-manif", "data": {"html": "<div class=\\"pxt\\"><section class=\\"pxt-sec pxt-manif-sec\\"><div class=\\"pxt-c\\"><div class=\\"pxt-manif pxt-rv\\"><p class=\\"pxt-manif__t\\">Optimiser aujourd'hui. <span>Performer demain.</span></p><div class=\\"pxt-manif__m\\"><span class=\\"pxt-k\\">Notre mission</span><p>Rendre la performance énergétique des sites industriels et tertiaires mesurable et durable, de la note de calcul au suivi des consommations.</p><a class=\\"pxt-link\\" href=\\"/notre-approche/\\">Découvrir notre approche <span class=\\"fa fa-arrow-right\\"></span></a></div></div></div></section></div>"}, "type": "html", "style": {"paddingTop": "none", "paddingBottom": "none"}}, {"id": "b-s4qifcjq", "data": {"items": [{"id": "f-ijiojeiy", "answer": "<p>De quelques semaines pour une déstratification à plusieurs mois pour une chaufferie ou une centrale froid. Le planning figure dans le dossier de l'étape 2.</p>", "question": "Combien de temps dure un projet ?"}, {"id": "f-s7nik061", "answer": "<p>Par comparaison des consommations avant et après travaux, corrigées du climat et de l'activité, à partir de vos compteurs ou de comptages posés pour le projet.</p>", "question": "Comment suivez-vous les économies ?"}, {"id": "f-tjw5ucjy", "answer": "<p>Oui. Nous partageons nos relevés et nos notes de calcul et coordonnons les interventions.</p>", "question": "Travaillez-vous avec notre bureau d'études ou notre mainteneur ?"}], "title": "Questions fréquentes sur notre approche", "layout": "stacked", "eyebrow": "FAQ", "showContactCard": false}, "type": "faq", "style": {"anchor": "faq", "background": "white", "paddingTop": "md", "hideOnMobile": false, "hideOnDesktop": false, "paddingBottom": "md"}}, {"id": "b-pxt-1", "data": {"html": "<div class=\\"pxt\\"><section class=\\"pxt-sec\\" style=\\"padding-top:24px\\"><div class=\\"pxt-c\\"><div class=\\"pxt-band pxt-rv\\"><img src=\\"/themes/ultra-s/images/pexen/travaux-realises-dans-le-cadre-d-un-contrat-de-performance.webp\\" alt=\\"Travaux réalisés par PEXEN\\" loading=\\"lazy\\"><div><span class=\\"pxt-k\\">Votre projet</span><h2>Un projet ? Parlons-en.</h2><p>Prise de contact sous 48 h ouvrées par un ingénieur PEXEN, pour qualifier votre besoin et définir les prochaines étapes.</p><div class=\\"pxt-hero__act\\"><a class=\\"pxt-btn\\" href=\\"/contact/\\">Parler de votre projet <span class=\\"fa fa-arrow-right\\"></span></a><a class=\\"pxt-btn pxt-btn--ghost\\" href=\\"/simulateur-prime-cee/\\">Estimer le financement</a></div></div></div></div></section></div>"}, "type": "html", "style": {"background": "white", "paddingTop": "none", "paddingBottom": "none"}}, {"id": "b-jdrzfuk0", "data": {"image": "/uploads/pexen-equipe-ingenierie-d11aa9ca.webp", "intro": "Derrière chaque site, des installations qui ne s’arrêtent jamais, et des équipes qui en portent la responsabilité face à des coûts qui augmentent et à des obligations qui se durcissent. PEXEN est né d’une conviction : la performance énergétique ne se décrète pas, elle s’ingénie. Elle commence par un audit énergétique sur le terrain, se calcule, se construit sur le chantier, puis se prouve dans le temps.", "title": "Notre approche", "buttons": [{"id": "btn-4gr20at6", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-d6ll3j6z", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "eyebrow": "Notre approche", "metrics": [{"id": "m-822e3el5", "label": "de l’audit à la mesure", "value": "4 étapes"}, {"id": "m-vl4s2z80", "label": "daté à chaque étape", "value": "1 livrable"}, {"id": "m-1ppts4g3", "label": "contrôle par un organisme accrédité", "value": "COFRAC"}], "imageAlt": "Ingénieur devant une installation industrielle", "highlight": "Optimiser aujourd’hui. Performer demain.", "breadcrumb": true, "heroVariant": "solution"}, "type": "pageHeader", "style": {"background": "navy", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "md"}}, {"id": "b-ot68ti4s", "data": {"html": "<p>Faire de la performance énergétique un levier maîtrisé, mesurable et durable pour les sites industriels, tertiaires et résidentiels collectifs. Notre vision : un parc bâti et industriel où chaque kWh économisé est calculé, réalisé et démontré.</p><p><strong>La performance ne se promet plus, elle se prouve.</strong></p>", "image": "/uploads/pexen-audit-energetique-industrie-62f99a41.webp", "ratio": "landscape", "title": "Notre mission", "bullets": ["Maîtrisé, mesurable et durable", "Industrie, tertiaire et résidentiel collectif", "Chaque kWh calculé, réalisé et démontré"], "buttons": [{"id": "btn-x7bmk7ic", "icon": "arrow", "link": "/contact/?demande=etude", "label": "Demander une étude", "variant": "primary"}], "eyebrow": "Mission", "autoplay": false, "imageAlt": "Audit énergétique en environnement industriel", "highlight": "", "mediaType": "image", "mediaStyle": "rounded", "videoSource": "file", "mediaPosition": "right"}, "type": "textMedia", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-dzckskfn", "data": {"intro": "", "items": [{"id": "s-r8fa6iki", "num": "01", "text": "Relevé des équipements, lecture des factures et des courbes de charge, mesures ponctuelles. Les audits réglementaires sont conduits avec notre partenaire Leo Energy, qualifié OPQIBI 1905 et 1717. Remis : pré-étude d’ingénierie avec le gisement par poste.", "title": "Prévisite et audit"}, {"id": "s-fxtfwgfc", "num": "02", "text": "Notes de calcul, choix des équipements, chiffrage des travaux, calcul des kWh cumac et engagement du dossier CEE avant toute signature. Remis : dossier technique, devis, plan de financement.", "title": "Dimensionnement et ingénierie technico-financière"}, {"id": "s-0hwwq4o8", "num": "03", "text": "Travaux réalisés par nos équipes et nos partenaires qualifiés, phasés pour maintenir l’exploitation, réglages et essais. Remis : procès-verbal de réception.", "title": "Installation et mise en service"}, {"id": "s-afm5ai7z", "num": "04", "text": "Contrôle de l’opération par un organisme accrédité COFRAC, suivi des consommations, ajustement des réglages. Remis : bilan d’économies d’énergie.", "title": "Contrôle COFRAC, suivi et performance"}], "style": "timeline", "title": "Une méthode en 4 étapes, de l’audit énergétique à la mesure", "buttons": [], "eyebrow": "Méthode", "deliverableLabel": "Livrable"}, "type": "steps", "style": {"background": "soft", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-nz255lv4", "data": {"text": "", "title": "Demander une étude", "layout": "centered", "buttons": [{"id": "btn-pcekaxk6", "icon": "arrow", "link": "/contact/?demande=etude", "label": "Demander une étude", "variant": "primary"}], "variant": "light"}, "type": "cta", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-q0ca9gdd", "data": {"intro": "", "items": [{"id": "c-ga9lfvd2", "link": "", "tags": [], "text": "La précision de l’ingénieur, à chaque étape : aucune préconisation sans relevé, une note de calcul signée pour chaque solution.", "title": "Exigence", "linkLabel": ""}, {"id": "c-y0shrfz1", "link": "", "tags": [], "text": "Jusqu’au résultat, pas jusqu’à la facture : un livrable à chaque étape, le suivi des consommations après travaux, une réponse sous 48 h ouvrées.", "title": "Engagement", "linkLabel": ""}, {"id": "c-nim8r5ni", "link": "", "tags": [], "text": "Des chiffres justes, des engagements tenus : une estimation n’est jamais présentée comme une mesure, les règles CEE et les limites d’une solution sont dites d’emblée.", "title": "Intégrité", "linkLabel": ""}], "style": "hoverDark", "title": "Nos valeurs", "columns": 3, "eyebrow": "", "headerLinkLabel": ""}, "type": "cards", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-f6d307dw", "data": {"html": "<p>Un bureau d’études s’arrête au rapport. Un installateur dimensionne au catalogue. Un intermédiaire CEE ne voit que la prime. PEXEN porte la note de calcul, le chantier et le dossier : le froid, la chaleur, le pilotage et l’isolation traités dans un même projet, par la même équipe.</p>", "image": "/uploads/pexen-technicien-installation-industrielle-a911bca3.webp", "ratio": "landscape", "title": "Ingénierie, travaux et financement réunis", "bullets": ["Note de calcul portée en interne", "Chantier mené par la même équipe", "Dossier CEE monté jusqu’au contrôle", "Froid, chaleur, pilotage et isolation dans un même projet"], "buttons": [{"id": "btn-xt2o9rxj", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}], "eyebrow": "PEXEN", "autoplay": false, "imageAlt": "Technicien inspectant une installation industrielle", "highlight": "", "mediaType": "image", "mediaStyle": "rounded", "videoSource": "file", "mediaPosition": "left"}, "type": "textMedia", "style": {"background": "soft", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-f9pv5jnp", "data": {"text": "", "title": "Parlons de votre projet", "layout": "centered", "buttons": [{"id": "btn-tk1yvg4w", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}], "variant": "light"}, "type": "cta", "style": {"background": "soft", "paddingTop": "none", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-o6av3skn", "data": {"cards": [{"id": "ck-o4n9yb13", "icon": "fa-check", "title": "", "entries": [{"id": "e-uf2xfh5o", "title": "RGE QualiPAC (chauffage et eau chaude sanitaire) et RGE Qualisol CESI."}, {"id": "e-a0aihnnk", "title": "Audits énergétiques via notre partenaire Leo Energy : OPQIBI 1905 et 1717."}, {"id": "e-9if6hzyz", "title": "Responsabilité civile professionnelle et garantie décennale : MIC Insurance."}, {"id": "e-5bah8p3h", "title": "Opérations contrôlées par des organismes accrédités COFRAC."}]}], "intro": "", "title": "Qualifiés, assurés, contrôlés"}, "type": "checklist", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-8ihphcxh", "data": {"html": "<article id=\\"partenaires\\"><h2>Un réseau de partenaires</h2><p>Obligés, délégataires et mandataires CEE, fabricants d'équipements frigorifiques et de pompes à chaleur, bureaux d'études : PEXEN travaille avec des partenaires choisis pour la conformité de leurs dossiers et la disponibilité de leurs équipements.</p></article>", "size": "normal"}, "type": "richText", "style": {"background": "soft", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-2s1l8ja9", "data": {"text": "", "title": "Demander une étude", "layout": "centered", "buttons": [{"id": "btn-td8issye", "icon": "arrow", "link": "/contact/?demande=etude", "label": "Demander une étude", "variant": "primary"}], "variant": "light"}, "type": "cta", "style": {"background": "soft", "paddingTop": "none", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-8aqmfsda", "data": {"rows": [{"id": "r-kn6zye4p", "cells": ["01 Prévisite et audit", "Pré-étude d’ingénierie", "État initial, gisement par poste, premières recommandations"]}, {"id": "r-mnuyplr8", "cells": ["02 Ingénierie technico-financière", "Dossier technique, devis, plan de financement", "Notes de calcul, équipements, coût, CEE estimés, temps de retour"]}, {"id": "r-u1c4su97", "cells": ["03 Installation", "Procès-verbal de réception", "Travaux réalisés, réglages, essais, réserves levées"]}, {"id": "r-4p1kk9l0", "cells": ["04 Suivi et performance", "Bilan d’économies d’énergie", "Consommations avant et après, écarts, ajustements"]}], "intro": "", "title": "Les livrables, étape par étape", "columns": ["Étape", "Document remis", "Ce qu’il contient"], "searchable": false}, "type": "table", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-dcysu26h", "data": {"html": "<p>Un projet d’efficacité énergétique engage plusieurs décideurs : direction technique, direction financière, exploitant, parfois conseil syndical. Un document daté à chaque étape permet à chacun de valider en connaissance de cause, et sert de pièce justificative au dossier CEE et au contrôle COFRAC.</p>", "image": "/uploads/pexen-planification-projet-f309fac8.webp", "ratio": "landscape", "title": "Pourquoi un livrable à chaque étape", "bullets": ["Direction technique, financière, exploitant, conseil syndical", "Document daté pour valider chaque étape", "Pièce justificative du dossier CEE", "Contrôle par un organisme accrédité COFRAC"], "buttons": [{"id": "btn-jjtjg3ec", "icon": "arrow", "link": "/contact/?demande=etude", "label": "Demander une étude", "variant": "primary"}], "eyebrow": "Gouvernance", "autoplay": false, "imageAlt": "Planning de projet sur un ordinateur portable", "highlight": "", "mediaType": "image", "mediaStyle": "rounded", "videoSource": "file", "mediaPosition": "right"}, "type": "textMedia", "style": {"background": "soft", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-h97ylfpj", "data": {"text": "", "title": "Parlons de votre projet", "layout": "centered", "buttons": [{"id": "btn-qxrbu3n6", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}], "variant": "light"}, "type": "cta", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-gamk7jfb", "data": {"text": "Un ingénieur PEXEN étudie votre site, évalue le gisement et vous répond sous 48 h ouvrées.", "title": "Un projet ? Parlons-en.", "layout": "centered", "buttons": [{"id": "btn-wlvcw549", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-2084j5kp", "icon": "phone", "link": "tel:+33141935280", "label": "01 41 93 52 80", "variant": "secondary"}], "variant": "dark"}, "type": "cta", "style": {"background": "navy", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-pxt-css", "data": {"html": "<style>/* ===== pxt (Secteurs) ===== */\\n.pxt{--n:#082D4A;--c:#01CDF3;--p:#009FCC;--pd:#00769A;--b:#D5E1E6;--m:#5A6B7B;font-family:Figtree,system-ui,sans-serif;color:#3E5163;text-align:left}\\n.pxt *{box-sizing:border-box}\\n.pxt h1,.pxt h2,.pxt h3{font-family:Sora,system-ui,sans-serif;color:var(--n);margin:0}\\n.pxt p{margin:0 0 12px;line-height:1.7;font-size:16px}\\n.pxt-c{max-width:1296px;margin:0 auto;padding:0 24px;position:relative}\\n.pxt-sec{padding:72px 0;position:relative;overflow:hidden}\\n.pxt-k{display:inline-flex;align-items:center;gap:10px;font-size:12px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--pd)}\\n.pxt-k::before{content:\\"\\";width:28px;height:2px;background:var(--c)}\\n.pxt h2{font-size:clamp(28px,2.8vw,42px);line-height:1.15;letter-spacing:-.015em;margin:14px 0 14px}\\n.pxt-lead{font-size:17.5px!important;color:var(--m);max-width:720px}\\n.pxt-btn{display:inline-flex;align-items:center;gap:10px;height:48px;padding:0 26px;border-radius:6px;background:var(--c);color:var(--n)!important;font-weight:600;font-size:16px;text-decoration:none!important;transition:transform .2s,box-shadow .2s}\\n.pxt-btn:hover{transform:translateY(-2px);box-shadow:0 12px 26px rgba(1,205,243,.35)}\\n.pxt-btn--ghost{background:transparent;border:1px solid rgba(255,255,255,.5);color:#fff!important}\\n.pxt-btn--line{background:transparent;border:1px solid rgba(8,45,74,.3);color:var(--n)!important}\\n.pxt-link{display:inline-flex;gap:8px;align-items:center;font-weight:700;color:var(--pd)!important;text-decoration:none!important}\\n.pxt-link:hover{gap:12px}\\n.pxt-tag{display:inline-block;font-size:12px;font-weight:700;color:var(--pd);background:#E3F7FC;border-radius:6px;padding:5px 9px}\\n.pxt-hero{position:relative;min-height:640px;display:flex;align-items:flex-end;color:#fff;overflow:hidden;background:var(--n)}\\n.pxt-hero__bg{position:absolute;inset:0;margin:0}\\n.pxt-hero__bg img{width:100%;height:100%;object-fit:cover;transform:scale(1.04)}\\n.pxt-hero::before{content:\\"\\";position:absolute;inset:0;z-index:1;background:linear-gradient(90deg,rgba(8,45,74,.96) 0%,rgba(8,45,74,.86) 38%,rgba(8,45,74,.35) 72%,rgba(8,45,74,.15) 100%)}\\n.pxt-hero::after{content:attr(data-word);position:absolute;z-index:1;right:-10px;bottom:-34px;font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:clamp(90px,13vw,200px);line-height:1;color:transparent;-webkit-text-stroke:1.5px rgba(1,205,243,.28);letter-spacing:-.03em;pointer-events:none;white-space:nowrap}\\n.pxt-hero .pxt-c{z-index:2;width:100%;padding-top:96px;padding-bottom:72px;display:grid;grid-template-columns:7fr 5fr;gap:48px;align-items:end}\\n.pxt-crumbs{font-size:13px;color:rgba(255,255,255,.65);margin-bottom:18px}\\n.pxt-crumbs a{color:rgba(255,255,255,.8)!important;text-decoration:none!important}\\n.pxt-hero .pxt-k{color:var(--c)}\\n.pxt-hero h1{color:#fff;font-size:clamp(34px,4vw,58px);line-height:1.06;letter-spacing:-.02em;margin:14px 0 14px}\\n.pxt-hero__sub{font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:clamp(19px,1.7vw,24px);line-height:1.35;color:var(--c);margin:0 0 16px!important;max-width:640px}\\n.pxt-hero__desc{color:rgba(255,255,255,.82);max-width:600px;font-size:16.5px!important}\\n.pxt-hero__act{display:flex;flex-wrap:wrap;gap:12px;margin-top:26px}\\n.pxt-figs{display:grid;gap:12px}\\n.pxt-fig{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);border-radius:16px;padding:18px 22px;display:grid;grid-template-columns:auto 1fr;gap:16px;align-items:center}\\n.pxt-fig b{font-family:Sora,system-ui,sans-serif;font-size:30px;line-height:1;color:var(--c);white-space:nowrap}\\n.pxt-fig span{font-size:14px;color:rgba(255,255,255,.85);line-height:1.4}\\n.pxt-enj{display:grid;grid-template-columns:repeat(3,1fr);gap:0;border-top:1px solid var(--b);margin-top:36px}\\n.pxt-enj>div{padding:34px 30px 30px;border-right:1px solid var(--b);position:relative;transition:background .3s}\\n.pxt-enj>div:last-child{border-right:0}\\n.pxt-enj>div::before{content:\\"\\";position:absolute;left:0;top:-1px;height:3px;width:0;background:var(--c);transition:width .5s}\\n.pxt-enj>div:hover{background:#F6FAFC}.pxt-enj>div:hover::before{width:100%}\\n.pxt-enj i{display:block;font-style:normal;font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:76px;line-height:1;color:transparent;-webkit-text-stroke:1.5px var(--p);margin-bottom:18px}\\n.pxt-enj h3{font-size:20px;margin-bottom:10px}\\n.pxt-enj p{font-size:15px!important;color:var(--m)}\\n.pxt-enj .pxt-link{margin-top:6px;font-size:14.5px}\\n.pxt-dark{background:radial-gradient(circle at 0% 0%,rgba(1,205,243,.14),transparent 40%),var(--n);color:rgba(255,255,255,.8)}\\n.pxt-dark h2,.pxt-dark h3{color:#fff}.pxt-dark .pxt-k{color:var(--c)}.pxt-dark .pxt-lead{color:rgba(255,255,255,.72)}\\n.pxt-tabs{display:grid;grid-template-columns:330px 1fr;gap:28px;margin-top:36px;align-items:stretch}\\n.pxt-tabs>input{position:absolute;opacity:0;pointer-events:none}\\n.pxt-tabs__nav{display:grid;gap:8px;align-content:start}\\n.pxt-tabs__nav label{display:flex;align-items:center;gap:14px;cursor:pointer;padding:16px 18px;border-radius:12px;border:1px solid rgba(255