gba(255,255,255,.65);margin:0}\\n@media(max-width:991px){.pxr-hero--split,.pxr-hero--giant{grid-template-columns:1fr}.pxr-hero--split figure,.pxr-hero--giant figure{min-height:280px;clip-path:none}.pxr-hero--split>div,.pxr-hero--giant>div{padding:100px 24px 72px}.pxr-story{grid-template-columns:1fr;gap:10px}.pxr-story__k{position:static}.pxr-ba,.pxr-res,.pxr-next,.pxr-grid{grid-template-columns:1fr}.pxr-steps{grid-template-columns:1fr 1fr}.pxr-steps::before{display:none}.pxr-total{grid-template-columns:1fr;gap:14px}}\\n/* ===== /pxr ===== */</style>"}, "type": "html", "style": {"paddingTop": "none", "paddingBottom": "none"}}], "status": "published", "project": {"cumac": "2,1 GWh cumac", "image": "/uploads/pexen-reference-cedim-964b62c5.webp", "client": "CEDIM", "sector": "Négoce et entrepôt", "results": ["2,1 GWh cumac d’économies d’énergie estimées*"], "summary": "Centre-Val de Loire · Négoce et entrepôt", "featured": true, "location": "Centre-Val de Loire", "solution": "ramener la chaleur au sol", "sortOrder": 3}, "template": "project", "createdAt": "2026-10-21T10:43:13.023Z", "updatedAt": "2026-11-11T17:54:29.056Z", "publishedAt": "2026-10-21T10:43:13.023Z", "contentSource": "cms"}	admin@pexen.fr	2026-11-11 18:55:01.447246+01
