ut) */\\n.px-ultra-action-cta__btn,#estimation .btn.px-cta,.px-ultra-ed__prose p:last-child>a:only-child{border-radius:6px!important;padding:14px 28px!important;min-height:48px;font-size:16px!important;font-weight:600!important;text-transform:none!important;letter-spacing:normal!important;box-shadow:none!important;transform:none!important}\\n.px-ultra-action-cta__btn:not(.px-ultra-action-cta__btn--ghost),#estimation .btn.px-cta{background:#01CDF3!important;color:#082D4A!important;border:1px solid #01CDF3!important}\\n.px-ultra-action-cta__btn:not(.px-ultra-action-cta__btn--ghost):hover,#estimation .btn.px-cta:hover{background:#00B8DB!important;border-color:#00B8DB!important}\\n.px-ultra-action-cta__btn--ghost{background:transparent!important;border:1px solid currentColor!important}\\n.px-ultra-action-cta__btn-shine{display:none!important}\\n.px-ultra-ed__prose p:last-child>a:only-child{background:transparent!important;border:1px solid var(--pxn)!important;color:var(--pxn)!important}\\n.px-ultra-ed__prose p:last-child>a:only-child:hover{background:var(--pxn)!important;color:#fff!important}\\nsection[aria-labelledby$=\\"-cta\\"] a{border-radius:6px!important;padding:14px 28px!important;font-size:16px!important;font-weight:600!important}\\n\\n/* Rangées de 3 cartes : pleine largeur */\\n@media(min-width:1200px){.row.g-4>.col-xl-3:nth-child(3):last-child,.row.g-4>.col-xl-3:has(~.col-xl-3:nth-child(3):last-child){flex:0 0 33.3333%!important;max-width:33.3333%!important}}\\n/* En-tête du tableau centré (bloc pleine largeur) */\\n.px-ultra-table-sec__head{display:flex;flex-direction:column;align-items:center;text-align:center;max-width:820px;margin:0 auto 40px!important}\\n\\n/* ===== PEXEN · composants maison (pxk) ===== */\\nsection.sec-padding,section.px-ultra-real-sec--standalone,section.px-ultra-ed:has(.px-ultra-ed__title){padding-top:72px!important;padding-bottom:72px!important}\\n@media(max-width:767px){section.sec-padding,section.px-ultra-real-sec--standalone,section.px-ultra-ed:has(.px-ultra-ed__title){padding-top:56px!important;padding-bottom:56px!important}}\\n.sec-intro.mb-5,.px-ultra-ed__title{margin-bottom:36px!important}\\n.pxk{text-align:left;padding:72px 0;font-family:Figtree,system-ui,sans-serif;color:#3a4a5a}\\n.pxk--ice{background:linear-gradient(180deg,#F4F7FA 0%,#EEF3F7 100%)}\\n.pxk--navy{background:#082D4A;color:rgba(255,255,255,.78)}\\n.pxk__c{max-width:1296px;margin:0 auto;padding:0 24px}\\n.pxk-head{text-align:center!important;max-width:820px;margin:0 auto 44px}\\n.pxk-head--left{text-align:left;margin-left:0}\\n.pxk-eyebrow{display:inline-block;padding:5px 20px;border:1px solid #D5E1E6;border-radius:30px;font-size:13px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:#082D4A;margin-bottom:16px}\\n.pxk--navy .pxk-eyebrow{border-color:rgba(255,255,255,.25);color:#fff}\\n.pxk h2{font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:clamp(26px,2.6vw,38px);line-height:1.2;color:#082D4A;margin:0 0 14px;letter-spacing:-.01em}\\n.pxk--navy h2{color:#fff}\\n.pxk h3{font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:19px;line-height:1.3;color:#082D4A;margin:0 0 10px}\\n.pxk p{margin:0 0 12px;line-height:1.65;font-size:15.5px}\\n.pxk-lead{font-size:17px!important;color:#5A6B7B}\\n.pxk-btn{display:inline-flex;align-items:center;gap:10px;height:48px;padding:0 28px;border-radius:6px;border:1px solid #01CDF3;background:#01CDF3;color:#082D4A!important;font-weight:600;font-size:16px;text-decoration:none!important;transition:background .2s,border-color .2s}\\n.pxk-btn:hover{background:#00B8DB;border-color:#00B8DB}\\n.pxk-btn--ghost{background:transparent;border-color:currentColor;color:#082D4A!important}\\n.pxk--navy .pxk-btn--ghost,.pxk-dark .pxk-btn--ghost{color:#fff!important}\\n.pxk-btn--ghost:hover{background:#082D4A;color:#fff!important;border-color:#082D4A}\\n.pxk-link{display:inline-flex;align-items:center;gap:8px;font-weight:600;color:#00769A!important;text-decoration:none!important;border-bottom:1px solid rgba(0,118,154,.35);padding-bottom:2px}\\n.pxk-link:hover{border-color:#00769A}\\n.pxk-ico{display:inline-flex;align-items:center;justify-content:center;width:46px;height:46px;border-radius:12px;background:#E3F7FC;color:#00769A;font-size:19px;flex:0 0 46px}\\n/* Obligations */\\n.pxk-grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}\\n.pxk-card{position:relative;display:flex;flex-direction:column;background:#fff;border:1px solid #D5E1E6;border-radius:16px;padding:30px 28px;box-shadow:0 12px 32px rgba(8,45,74,.06);overflow:hidden}\\n.pxk-card::before{content:\\"\\";position:absolute;left:0;top:0;right:0;height:4px;background:linear-gradient(90deg,#01CDF3,#009FCC)}\\n.pxk-fig{font-family:Sora,system-ui,sans-serif;font-weight:700;font-size:38px;line-height:1;color:#082D4A;margin:6px 0 6px}\\n.pxk-fig small{font-size:15px;font-weight:600;color:#00769A;margin-left:6px}\\n.pxk-figcap{font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:#5A6B7B;margin-bottom:18px;padding-bottom:18px;border-bottom:1px solid #E6EEF2}\\n.pxk-card p{font-size:14.5px;color:#4a5a6a}\\n.pxk-card .pxk-link{margin-top:auto;align-self:flex-start;padding-top:8px}\\n/* Encart plan d'actions */\\n.pxk-plan{display:grid;grid-template-columns:1.05fr 1fr;border-radius:20px;overflow:hidden;box-shadow:0 20px 50px rgba(8,45,74,.14)}\\n.pxk-plan__l{background:#082D4A;padding:48px;color:rgba(255,255,255,.8);text-align:left}\\n.pxk-plan__l h2{color:#fff}\\n.pxk-plan__l .pxk-eyebrow{border-color:rgba(255,255,255,.25);color:#fff}\\n.pxk-plan__r{background:linear-gradient(160deg,#EEF4FA,#E0ECF5);padding:40px 44px;display:flex;flex-direction:column;justify-content:center;gap:12px}\\n.pxk-step{display:flex;align-items:center;gap:14px;background:#fff;border:1px solid #D5E1E6;border-radius:12px;padding:14px 18px}\\n.pxk-step b{font-family:Sora,system-ui,sans-serif;font-size:15px;color:#082D4A;font-weight:600}\\n.pxk-step span{display:block;font-size:13px;color:#5A6B7B}\\n.pxk-tag{margin-left:auto;font-size:12px;font-weight:700;color:#00769A;background:#E3F7FC;border-radius:6px;padding:5px 10px;white-space:nowrap}\\n.pxk-check{width:26px;height:26px;border-radius:50%;background:#01CDF3;color:#082D4A;display:inline-flex;align-items:center;justify-content:center;font-size:12px;flex:0 0 26px}\\n/* Financement */\\n.pxk-split{display:grid;grid-template-columns:1.25fr 1fr;gap:48px;align-items:start}\\n.pxk-rows{display:grid;gap:14px;margin-top:8px}\\n.pxk-row{display:flex;gap:16px;align-items:flex-start;background:#fff;border:1px solid #D5E1E6;border-radius:14px;padding:18px 20px}\\n.pxk-row h3{font-size:16px;margin:2px 0 4px}\\n.pxk-row p{margin:0;font-size:14.5px}\\n.pxk-dark{background:#082D4A;border-radius:18px;padding:36px 34px;color:rgba(255,255,255,.8);box-shadow:0 20px 50px rgba(8,45,74,.18);position:sticky;top:110px}\\n.pxk-dark h3{color:#fff;font-size:21px;margin-bottom:20px}\\n.pxk-num{display:flex;gap:14px;align-items:flex-start;padding:14px 0;border-top:1px solid rgba(255,255,255,.12)}\\n.pxk-num i{font-style:normal;font-family:Sora,system-ui,sans-serif;font-weight:700;color:#01CDF3;font-size:22px;line-height:1;min-width:30px}\\n.pxk-num p{margin:0;font-size:15px;color:rgba(255,255,255,.85)}\\n.pxk-dark .pxk-btn{margin-top:22px}\\n/* Chaîne de cohérence (AMO) */\\n.pxk-chain{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;gap:16px;align-items:stretch}\\n.pxk-node{background:#fff;border:1px solid #D5E1E6;border-radius:16px;padding:26px 24px;text-align:left;box-shadow:0 12px 32px rgba(8,45,74,.06)}\\n.pxk-node .pxk-ico{margin-bottom:16px}\\n.pxk-arrow{align-self:center;color:#01CDF3;font-size:22px}\\n.pxk-callout{margin:28px auto 0;max-width:900px;text-align:center;font-size:16px;color:#082D4A;background:#E3F7FC;border-radius:12px;padding:18px 24px}\\n/* Tuiles KPI (fond bleu nuit) */\\n.pxk-grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}\\n.pxk-tile{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.12);border-radius:16px;padding:26px 22px}\\n.pxk-tile .pxk-ico{background:rgba(1,205,243,.14);color:#01CDF3;margin-bottom:16px}\\n.pxk-tile h3{color:#fff;font-size:17px}\\n.pxk-tile p{color:rgba(255,255,255,.75);font-size:14.5px;margin:0}\\n/* Par où commencer */\\n.pxk-start{display:grid;gap:12px;max-width:1040px;margin:0 auto}\\n.pxk-start a{display:grid;grid-template-columns:1fr auto auto;gap:20px;align-items:center;background:#fff;border:1px solid #D5E1E6;border-radius:14px;padding:20px 24px;text-decoration:none!important;color:#082D4A;transition:border-color .2s,box-shadow .2s,transform .2s}\\n.pxk-start a:hover{border-color:#01CDF3;box-shadow:0 12px 30px rgba(8,45,74,.08);transform:translateY(-2px)}\\n.pxk-start b{font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:17px}\\n.pxk-start span{font-size:14px;color:#5A6B7B}\\n.pxk-pill{font-size:13px;font-weight:700;color:#082D4A;background:#E3F7FC;border-radius:6px;padding:8px 14px;white-space:nowrap}\\n.pxk-start .fa{color:#00769A}\\n/* Comparatif */\\n.pxk-vs{display:grid;grid-template-columns:1fr 1fr;gap:20px}\\n.pxk-vs>div{border-radius:16px;padding:28px}\\n.pxk-vs__a{background:#fff;border:1px solid #D5E1E6}\\n.pxk-vs__b{background:#082D4A;color:rgba(255,255,255,.85)}\\n.pxk-vs__b h3{color:#fff}\\n.pxk-vs ul{list-style:none;padding:0;margin:14px 0 0;display:grid;gap:12px}\\n.pxk-vs li{display:flex;gap:12px;align-items:flex-start;font-size:15px;line-height:1.5}\\n.pxk-vs li i{margin-top:3px}\\n.pxk-vs__a li i{color:#9AA9B5}\\n.pxk-vs__b li i{color:#01CDF3}\\n@media(max-width:991px){.pxk-grid3,.pxk-plan,.pxk-split,.pxk-vs{grid-template-columns:1fr}.pxk-grid4{grid-template-columns:1fr 1fr}.pxk-chain{grid-template-columns:1fr}.pxk-arrow{transform:rotate(90deg);justify-self:center}.pxk-dark{position:static}.pxk-plan__l,.pxk-plan__r{padding:32px 24px}.pxk-start a{grid-template-columns:1fr;gap:10px}}\\n@media(max-width:575px){.pxk-grid4{grid-template-columns:1fr}.pxk{padding:56px 0}}\\n/* Catalogue collé au tableau */\\n.px-block-typo:has(.px-ultra-table-sec) .px-ultra-table-sec{padding-bottom:20px!important}\\n.px-block-typo:has(.px-ultra-table-sec)+.px-block-typo .px-ultra-ed{background:#EEF3F7!important;padding:0 0 72px!important}\\n.px-block-typo:has(.px-ultra-table-sec)+.px-block-typo .px-ultra-ed__inner{display:block!important;text-align:center}\\n\\n.pxk-head--left{text-align:left!important}\\n.pxk-card,.pxk-row,.pxk-step,.pxk-dark,.pxk-node,.pxk-tile,.pxk-vs>div,.pxk-plan__l{text-align:left!important}\\n.pxk-callout{text-align:center!important}\\n.px-block-typo:has(.px-ultra-table-sec)+.px-block-typo .px-ultra-ed__prose{text-align:center!important;max-width:none!important;margin:0 auto!important}\\n/* ===== pxk2 ===== */\\n/* Logos qualifications : tous à la même hauteur, sur une ligne */\\nbody .px-ultra-root .px-ultra-preuves__quali{display:flex!important;flex-direction:row!important;flex-wrap:nowrap!important;align-items:center!important;justify-content:flex-start;gap:18px!important}\\nbody .px-ultra-root .px-ultra-preuves__quali .px-ultra-preuves__quali-item{flex:0 0 auto!important;width:auto!important;margin:0!important}\\nbody .px-ultra-root .px-ultra-preuves__quali .px-ultra-preuves__quali-item img{height:44px!important;width:auto!important;max-width:none!important;max-height:none!important}\\nbody .px-ultra-root .px-ultra-garant-logos img.px-ultra-garant-logo{height:52px!important;width:auto!important;max-width:none!important;max-height:none!important}\\nbody .px-ultra-root .px-ultra-ft .px-ultra-ft__quali img, body .px-ultra-ft__quali img.px-q{height:44px!important;width:auto!important;max-height:none!important}\\n/* Lien catalogue collé au tableau, espaces réduits */\\n.px-block-typo:has(.px-ultra-table-sec) .px-ultra-table-sec{padding-bottom:8px!important}\\n.px-block-typo:has(.px-ultra-table-sec)+.px-block-typo .px-ultra-ed{padding:0 0 40px!important}\\n.px-block-typo:has(.px-ultra-table-sec)+.px-block-typo .px-ultra-ed p{margin:0!important}\\n/* Photo + contenu */\\n.pxk-media{display:grid;grid-template-columns:5fr 7fr;gap:28px;align-items:stretch;text-align:left}\\n.pxk-media--rev{grid-template-columns:7fr 5fr}.pxk-media--rev .pxk-media__img{order:2}\\n.pxk-media__img{position:relative;border-radius:16px;overflow:hidden;min-height:380px;margin:0;box-shadow:0 18px 40px rgba(8,45,74,.12)}\\n.pxk-media__img img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\\n.pxk-media__img figcaption{position:absolute;left:16px;bottom:16px;right:16px;background:rgba(8,45,74,.88);color:#fff;font-size:13px;line-height:1.45;padding:10px 14px;border-radius:8px;backdrop-filter:blur(4px)}\\n.pxk-media__img figcaption b{color:#01CDF3}\\n.pxk-kpis{display:grid;grid-template-columns:1fr 1fr;gap:14px;align-content:center}\\n.pxk-kpi{position:relative;background:#fff;border:1px solid #D5E1E6;border-radius:14px;padding:20px 22px 20px 26px;overflow:hidden;text-align:left}\\n.pxk-kpi::before{content:\\"\\";position:absolute;left:0;top:0;bottom:0;width:4px;background:linear-gradient(180deg,#01CDF3,#009FCC)}\\n.pxk-kpi b{display:block;font-family:Sora,system-ui,sans-serif;font-size:clamp(24px,2.2vw,30px);font-weight:700;color:#082D4A;line-height:1.1;margin-bottom:8px}\\n.pxk-kpi p{margin:0;font-size:14.5px;line-height:1.55;color:#5A6B7B}\\n.pxk-kpi small{display:block;margin-top:8px;font-size:12px;color:#00769A;font-weight:600}\\n.pxk-kpi--wide{grid-column:1/-1}\\n.pxk-kpi--navy{background:#082D4A;border-color:#082D4A}.pxk-kpi--navy b{color:#01CDF3}.pxk-kpi--navy p{color:rgba(255,255,255,.8)}\\n/* Cartes avec photo */\\n.pxk-card--img{padding:0!important;overflow:hidden;display:flex;flex-direction:column}\\n.pxk-card--img>img{width:100%;height:190px;object-fit:cover;display:block}\\n.pxk-card__b{padding:24px 26px 26px;display:flex;flex-direction:column;gap:6px;flex:1}\\n.pxk-card__b ul{list-style:none;padding:0;margin:8px 0 0;display:grid;gap:10px}\\n.pxk-card__b li{display:flex;gap:10px;font-size:14.5px;line-height:1.5;color:#3E5163}\\n.pxk-card__b li .fa{color:#009FCC;margin-top:4px}\\n.pxk-badge{position:absolute;top:14px;left:14px;background:#01CDF3;color:#082D4A;font-weight:700;font-size:12px;letter-spacing:.06em;text-transform:uppercase;border-radius:6px;padding:6px 10px}\\n.pxk-card--img{position:relative}\\n/* Encart centré */\\n.pxk-enc{flex-direction:column;justify-content:center!important;text-align:center!important;padding:44px 32px!important;gap:22px!important}\\n.pxk-enc h3{font-size:clamp(24px,2.6vw,32px)!important;margin:10px 0!important}\\n.pxk-enc p{font-size:16px!important;max-width:620px;margin:0 auto!important}\\n.pxk-enc__b{justify-content:center}\\n@media(max-width:991px){.pxk-media,.pxk-media--rev{grid-template-columns:1fr}.pxk-media--rev .pxk-media__img{order:0}.pxk-media__img{min-height:260px}}\\n@media(max-width:575px){.pxk-kpis{grid-template-columns:1fr}.px-ultra-preuves__quali{flex-wrap:wrap!important}}\\n/* centrage pxk */.pxk-split,.pxk-plan,.pxk-media{align-items:center!important}.pxk-dark{position:relative!important;top:auto!important}\\n/* sous-titre hero */.px-ultra-page-hero__title em{display:block!important;font-style:normal!important;font-size:clamp(20px,1.8vw,26px)!important;line-height:1.3!important;font-weight:600!important;color:#00769A!important;margin-top:14px!important;letter-spacing:0!important}.px-ultra-page-hero__title em::before,.px-ultra-page-hero__title em::after{display:none!important}\\n/* ===== /pxk2 ===== */\\n</style>"}, "type": "html", "style": {"paddingTop": "none", "paddingBottom": "none"}}, {"id": "b-manif", "data": {"html": "<div class=\\"pxt\\"><section class=\\"pxt-sec pxt-manif-sec\\"><div class=\\"pxt-c\\"><div class=\\"pxt-manif pxt-rv\\"><p class=\\"pxt-manif__t\\">Optimiser aujourd'hui. <span>Performer demain.</span></p><div class=\\"pxt-manif__m\\"><span class=\\"pxt-k\\">Notre mission</span><p>Rendre la performance énergétique des sites industriels et tertiaires mesurable et durable, de la note de calcul au suivi des consommations.</p><a class=\\"pxt-link\\" href=\\"/notre-approche/\\">Découvrir notre approche <span class=\\"fa fa-arrow-right\\"></span></a></div></div></div></section></div>"}, "type": "html", "style": {"paddingTop": "none", "paddingBottom": "none"}}, {"id": "b-19rv2ury", "data": {"items": [{"id": "f-wdp6b9sy", "answer": "<p>L'ingénierie fluides dimensionne les installations (chauffage, ventilation, climatisation, plomberie, désenfumage). L'ingénierie efficacité énergétique mesure les consommations, calcule le gisement d'économies et justifie chaque action.</p>", "question": "Quelle différence entre ingénierie fluides et efficacité énergétique ?"}, {"id": "f-yfrbzr7z", "answer": "<p>Oui si sa consommation annuelle moyenne atteint 2,75 GWh et qu'elle ne dispose pas d'un système de management de l'énergie certifié ISO 50001. L'audit se renouvelle tous les quatre ans.</p>", "question": "Mon entreprise doit-elle réaliser un audit énergétique ?"}, {"id": "f-x6hj7kpc", "answer": "<p>Oui. Seuls les audits réglementaires sont conduits avec notre partenaire qualifié Leo Energy.</p>", "question": "Les études sont-elles réalisées en interne ?"}, {"id": "f-8bjnhe1j", "answer": "<p>De quelques jours pour une action ciblée à plusieurs semaines pour un audit de site complet. Le délai est fixé après la visite technique.</p>", "question": "Combien de temps dure une étude ?"}], "title": "Questions fréquentes sur nos études", "layout": "stacked", "eyebrow": "FAQ", "showContactCard": false}, "type": "faq", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-jsq5aygj", "data": {"html": "<section aria-labelledby=\\"pexen-cee-cta\\" style=\\"max-width:1120px;margin:0 auto;padding:72px 24px\\"><div style=\\"display:flex;flex-wrap:wrap;background:#082d4a;overflow:hidden;border-radius:8px\\"><img src=\\"/uploads/pexen-audit-mesures-electriques-93b25dc5.webp\\" alt=\\"Mesures électriques lors d'une étude énergétique PEXEN\\" loading=\\"lazy\\" width=\\"520\\" height=\\"640\\" style=\\"flex:1 1 230px;min-width:0;width:30%;object-fit:cover;max-height:480px\\"><div style=\\"flex:2 1 440px;padding:clamp(24px,4vw,48px);color:#fff;text-align:left\\"><p style=\\"color:#01cdf3;font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase\\">Votre projet</p><h2 id=\\"pexen-cee-cta\\" style=\\"font-size:clamp(26px,3vw,38px);line-height:1.2;color:#fff;margin:18px 0\\">Un projet ? Parlons-en.</h2><p style=\\"color:#d5e1e6;line-height:1.7;margin:0 0 28px\\">Prise de contact sous 48 h ouvrées par un ingénieur PEXEN, pour qualifier votre besoin et définir les prochaines étapes.</p><div style=\\"display:flex;flex-wrap:wrap;gap:12px\\"><a href=\\"/contact/\\" style=\\"display:inline-block;background:#01cdf3;color:#082d4a;padding:16px 20px;border-radius:4px;font-weight:700;text-decoration:none\\">Parler de votre projet →</a><a href=\\"/simulateur-prime-cee/\\" style=\\"display:inline-block;border:1px solid #d5e1e6;color:white;padding:15px 20px;border-radius:4px;font-weight:700;text-decoration:none\\">Estimer le financement →</a></div></div></div></section>"}, "type": "html", "style": {"background": "white", "paddingTop": "none", "paddingBottom": "none"}}, {"id": "b-c13cevyv", "data": {"text": "Prise de contact sous 48 h ouvrées par un ingénieur PEXEN, pour qualifier votre besoin et définir les prochaines étapes.", "title": "Un projet ? Parlons-en.", "layout": "centered", "buttons": [{"id": "btn-rek8pk3y", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-r9oudocu", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "variant": "dark"}, "type": "cta", "style": {"background": "navy", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-pxt-css", "data": {"html": "<style>/* ===== pxt (Secteurs) ===== */\\n.pxt{--n:#082D4A;--c:#01CDF3;--p:#009FCC;--pd:#00769A;--b:#D5E1E6;--m:#5A6B7B;font-family:Figtree,system-ui,sans-serif;color:#3E5163;text-align:left}\\n.pxt *{box-sizing:border-box}\\n.pxt h1,.pxt h2,.pxt h3{font-family:Sora,system-ui,sans-serif;color:var(--n);margin:0}\\n.pxt p{margin:0 0 12px;line-height:1.7;font-size:16px}\\n.pxt-c{max-width:1296px;margin:0 auto;padding:0 24px;position:relative}\\n.pxt-sec{padding:72px 0;position:relative;overflow:hidden}\\n.pxt-k{display:inline-flex;align-items:center;gap:10px;font-size:12px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--pd)}\\n.pxt-k::before{content:\\"\\";width:28px;height:2px;background:var(--c)}\\n.pxt h2{font-size:clamp(28px,2.8vw,42px);line-height:1.15;letter-spacing:-.015em;margin:14px 0 14px}\\n.pxt-lead{font-size:17.5px!important;color:var(--m);max-width:720px}\\n.pxt-btn{display:inline-flex;align-items:center;gap:10px;height:48px;padding:0 26px;border-radius:6px;background:var(--c);color:var(--n)!important;font-weight:600;font-size:16px;text-decoration:none!important;transition:transform .2s,box-shadow .2s}\\n.pxt-btn:hover{transform:translateY(-2px);box-shadow:0 12px 26px rgba(1,205,243,.35)}\\n.pxt-btn--ghost{background:transparent;border:1px solid rgba(255,255,255,.5);color:#fff!important}\\n.pxt-btn--line{background:transparent;border:1px solid rgba(8,45,74,.3);color:var(--n)!important}\\n.pxt-link{display:inline-flex;gap:8px;align-items:center;font-weight:700;color:var(--pd)!important;text-decoration:none!important}\\n.pxt-link:hover{gap:12px}\\n.pxt-tag{display:inline-block;font-size:12px;font-weight:700;color:var(--pd);background:#E3F7FC;border-radius:6px;padding:5px 9px}\\n.pxt-hero{position:relative;min-height:640px;display:flex;align-items:flex-end;color:#fff;overflow:hidden;background:var(--n)}\\n.pxt-hero__bg{position:absolute;inset:0;margin:0}\\n.pxt-hero__bg img{width:100%;height:100%;object-fit:cover;transform:scale(1.04)}\\n.pxt-hero::before{content:\\"\\";position:absolute;inset:0;z-index:1;background:linear-gradient(90deg,rgba(8,45,74,.96) 0%,rgba(8,45,74,.86) 38%,rgba(8,45,74,.35) 72%,rgba(8,45,74,.15) 100%)}\\n.pxt-hero::after{content:attr(data-word);position:absolute;z-index:1;right:-10px;bottom:-34px;font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:clamp(90px,13vw,200px);line-height:1;color:transparent;-webkit-text-stroke:1.5px rgba(1,205,243,.28);letter-spacing:-.03em;pointer-events:none;white-space:nowrap}\\n.pxt-hero .pxt-c{z-index:2;width:100%;padding-top:96px;padding-bottom:72px;display:grid;grid-template-columns:7fr 5fr;gap:48px;align-items:end}\\n.pxt-crumbs{font-size:13px;color:rgba(255,255,255,.65);margin-bottom:18px}\\n.pxt-crumbs a{color:rgba(255,255,255,.8)!important;text-decoration:none!important}\\n.pxt-hero .pxt-k{color:var(--c)}\\n.pxt-hero h1{color:#fff;font-size:clamp(34px,4vw,58px);line-height:1.06;letter-spacing:-.02em;margin:14px 0 14px}\\n.pxt-hero__sub{font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:clamp(19px,1.7vw,24px);line-height:1.35;color:var(--c);margin:0 0 16px!important;max-width:640px}\\n.pxt-hero__desc{color:rgba(255,255,255,.82);max-width:600px;font-size:16.5px!important}\\n.pxt-hero__act{display:flex;flex-wrap:wrap;gap:12px;margin-top:26px}\\n.pxt-figs{display:grid;gap:12px}\\n.pxt-fig{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);border-radius:16px;padding:18px 22px;display:grid;grid-template-columns:auto 1fr;gap:16px;align-items:center}\\n.pxt-fig b{font-family:Sora,system-ui,sans-serif;font-size:30px;line-height:1;color:var(--c);white-space:nowrap}\\n.pxt-fig span{font-size:14px;color:rgba(255,255,255,.85);line-height:1.4}\\n.pxt-enj{display:grid;grid-template-columns:repeat(3,1fr);gap:0;border-top:1px solid var(--b);margin-top:36px}\\n.pxt-enj>div{padding:34px 30px 30px;border-right:1px solid var(--b);position:relative;transition:background .3s}\\n.pxt-enj>div:last-child{border-right:0}\\n.pxt-enj>div::before{content:\\"\\";position:absolute;left:0;top:-1px;height:3px;width:0;background:var(--c);transition:width .5s}\\n.pxt-enj>div:hover{background:#F6FAFC}.pxt-enj>div:hover::before{width:100%}\\n.pxt-enj i{display:block;font-style:normal;font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:76px;line-height:1;color:transparent;-webkit-text-stroke:1.5px var(--p);margin-bottom:18px}\\n.pxt-enj h3{font-size:20px;margin-bottom:10px}\\n.pxt-enj p{font-size:15px!important;color:var(--m)}\\n.pxt-enj .pxt-link{margin-top:6px;font-size:14.5px}\\n.pxt-dark{background:radial-gradient(circle at 0% 0%,rgba(1,205,243,.14),transparent 40%),var(--n);color:rgba(255,255,255,.8)}\\n.pxt-dark h2,.pxt-dark h3{color:#fff}.pxt-dark .pxt-k{color:var(--c)}.pxt-dark .pxt-lead{color:rgba(255,255,255,.72)}\\n.pxt-tabs{display:grid;grid-template-columns:330px 1fr;gap:28px;margin-top:36px;align-items:stretch}\\n.pxt-tabs>input{position:absolute;opacity:0;pointer-events:none}\\n.pxt-tabs__nav{display:grid;gap:8px;align-content:start}\\n.pxt-tabs__nav label{display:flex;align-items:center;gap:14px;cursor:pointer;padding:16px 18px;border-radius:12px;border:1px solid rgba(255,255,255,.14);color:rgba(255,255,255,.85);font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:16px;transition:all .25s}\\n.pxt-tabs__nav label i{font-style:normal;font-size:12px;font-weight:800;color:var(--c);width:26px}\\n.pxt-tabs__nav label:hover{background:rgba(255,255,255,.06)}\\n.pxt-tabs__panels{position:relative;min-height:400px}\\n.pxt-panel{display:none;grid-template-columns:1fr 1fr;border-radius:20px;overflow:hidden;background:#fff;height:100%;animation:pxtFade .4s ease}\\n.pxt-panel figure{margin:0;position:relative;min-height:400px}.pxt-panel figure img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\\n.pxt-panel>div{padding:34px 34px 30px;display:flex;flex-direction:column;justify-content:center}\\n.pxt-panel h3{color:var(--n)!important;font-size:24px;margin-bottom:12px}\\n.pxt-panel p{color:#3E5163;font-size:15.5px!important}\\n.pxt-panel .pxt-note{font-size:13px!important;color:var(--m);background:#F2F6F9;border-radius:8px;padding:10px 12px}\\n@keyframes pxtFade{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}\\n.pxt-tabs>input:nth-of-type(1):checked~.pxt-tabs__panels .pxt-panel:nth-child(1),.pxt-tabs>input:nth-of-type(2):checked~.pxt-tabs__panels .pxt-panel:nth-child(2),.pxt-tabs>input:nth-of-type(3):checked~.pxt-tabs__panels .pxt-panel:nth-child(3),.pxt-tabs>input:nth-of-type(4):checked~.pxt-tabs__panels .pxt-panel:nth-child(4),.pxt-tabs>input:nth-of-type(5):checked~.pxt-tabs__panels .pxt-panel:nth-child(5){display:grid}\\n.pxt-tabs>input:nth-of-type(1):checked~.pxt-tabs__nav label:nth-of-type(1),.pxt-tabs>input:nth-of-type(2):checked~.pxt-tabs__nav label:nth-of-type(2),.pxt-tabs>input:nth-of-type(3):checked~.pxt-tabs__nav label:nth-of-type(3),.pxt-tabs>input:nth-of-type(4):checked~.pxt-tabs__nav label:nth-of-type(4),.pxt-tabs>input:nth-of-type(5):checked~.pxt-tabs__nav label:nth-of-type(5){background:var(--c);border-color:var(--c);color:var(--n)}\\n.pxt-tabs>input:nth-of-type(1):checked~.pxt-tabs__nav label:nth-of-type(1) i,.pxt-tabs>input:nth-of-type(2):checked~.pxt-tabs__nav label:nth-of-type(2) i,.pxt-tabs>input:nth-of-type(3):checked~.pxt-tabs__nav label:nth-of-type(3) i,.pxt-tabs>input:nth-of-type(4):checked~.pxt-tabs__nav label:nth-of-type(4) i,.pxt-tabs>input:nth-of-type(5):checked~.pxt-tabs__nav label:nth-of-type(5) i{color:var(--n)}\\n.pxt-split{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}\\n.pxt-bars{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;align-items:end;height:300px;padding:0 6px;border-bottom:2px solid var(--b)}\\n.pxt-bar{position:relative;border-radius:12px 12px 0 0;background:linear-gradient(180deg,#9DB4C3,#C7D4DD);display:flex;flex-direction:column;justify-content:flex-start;align