edia__img figcaption b{color:#01CDF3}\\n.pxk-kpis{display:grid;grid-template-columns:1fr 1fr;gap:14px;align-content:center}\\n.pxk-kpi{position:relative;background:#fff;border:1px solid #D5E1E6;border-radius:14px;padding:20px 22px 20px 26px;overflow:hidden;text-align:left}\\n.pxk-kpi::before{content:\\"\\";position:absolute;left:0;top:0;bottom:0;width:4px;background:linear-gradient(180deg,#01CDF3,#009FCC)}\\n.pxk-kpi b{display:block;font-family:Sora,system-ui,sans-serif;font-size:clamp(24px,2.2vw,30px);font-weight:700;color:#082D4A;line-height:1.1;margin-bottom:8px}\\n.pxk-kpi p{margin:0;font-size:14.5px;line-height:1.55;color:#5A6B7B}\\n.pxk-kpi small{display:block;margin-top:8px;font-size:12px;color:#00769A;font-weight:600}\\n.pxk-kpi--wide{grid-column:1/-1}\\n.pxk-kpi--navy{background:#082D4A;border-color:#082D4A}.pxk-kpi--navy b{color:#01CDF3}.pxk-kpi--navy p{color:rgba(255,255,255,.8)}\\n/* Cartes avec photo */\\n.pxk-card--img{padding:0!important;overflow:hidden;display:flex;flex-direction:column}\\n.pxk-card--img>img{width:100%;height:190px;object-fit:cover;display:block}\\n.pxk-card__b{padding:24px 26px 26px;display:flex;flex-direction:column;gap:6px;flex:1}\\n.pxk-card__b ul{list-style:none;padding:0;margin:8px 0 0;display:grid;gap:10px}\\n.pxk-card__b li{display:flex;gap:10px;font-size:14.5px;line-height:1.5;color:#3E5163}\\n.pxk-card__b li .fa{color:#009FCC;margin-top:4px}\\n.pxk-badge{position:absolute;top:14px;left:14px;background:#01CDF3;color:#082D4A;font-weight:700;font-size:12px;letter-spacing:.06em;text-transform:uppercase;border-radius:6px;padding:6px 10px}\\n.pxk-card--img{position:relative}\\n/* Encart centré */\\n.pxk-enc{flex-direction:column;justify-content:center!important;text-align:center!important;padding:44px 32px!important;gap:22px!important}\\n.pxk-enc h3{font-size:clamp(24px,2.6vw,32px)!important;margin:10px 0!important}\\n.pxk-enc p{font-size:16px!important;max-width:620px;margin:0 auto!important}\\n.pxk-enc__b{justify-content:center}\\n@media(max-width:991px){.pxk-media,.pxk-media--rev{grid-template-columns:1fr}.pxk-media--rev .pxk-media__img{order:0}.pxk-media__img{min-height:260px}}\\n@media(max-width:575px){.pxk-kpis{grid-template-columns:1fr}.px-ultra-preuves__quali{flex-wrap:wrap!important}}\\n/* centrage pxk */.pxk-split,.pxk-plan,.pxk-media{align-items:center!important}.pxk-dark{position:relative!important;top:auto!important}\\n/* ===== /pxk2 ===== */\\n/* ===== pxk3 (Solutions) ===== */\\n.pxk-grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}\\n.pxk-grid2 .pxk-card,.pxk-grid3 .pxk-card{display:flex;flex-direction:column;gap:4px}\\n.pxk-card .pxk-link{margin-top:auto;padding-top:10px}\\n.pxk-op{margin:6px 0 0!important}\\n.pxk-tag{display:inline-block;font-style:normal;font-size:12.5px;font-weight:700;color:#00769A;background:#E3F7FC;border-radius:6px;padding:6px 10px;letter-spacing:.02em}\\n.pxk-cta-line{text-align:center;margin:28px 0 0}\\n.pxk-cta-line .pxk-link{margin:0 12px}\\n.pxk-subh{font-size:17px;margin:18px 0 6px;color:#082D4A}\\n.pxk-band{display:grid;grid-template-columns:5fr 7fr;gap:40px;align-items:start;text-align:left;background:#fff;border:1px solid #D5E1E6;border-radius:18px;padding:40px 44px;box-shadow:0 14px 36px rgba(8,45,74,.06);position:relative;overflow:hidden}\\n.pxk-band::before{content:\\"\\";position:absolute;left:0;top:0;bottom:0;width:5px;background:linear-gradient(180deg,#01CDF3,#009FCC)}\\n.pxk-band .pxk-head{margin:0!important}\\n.pxk-band__t p{font-size:16px;line-height:1.75;color:#3E5163;margin:0 0 14px}\\n.pxk-band__t .pxk-link{display:inline-flex;margin-top:6px}\\n.pxk-media .pxk-band__t{align-self:center}\\n.pxk-n{font-family:Sora,system-ui,sans-serif;font-weight:700;font-size:14px}\\n.pxk-refs{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,360px),1fr));gap:20px;max-width:1040px;margin:0 auto}\\n.pxk-ref{display:grid;grid-template-columns:44% 1fr;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:16px;overflow:hidden;text-decoration:none!important;transition:transform .2s,border-color .2s}\\n.pxk-ref:hover{transform:translateY(-3px);border-color:#01CDF3}\\n.pxk-ref img{width:100%;height:100%;min-height:190px;object-fit:cover;display:block}\\n.pxk-ref>div{padding:22px 22px 20px;display:flex;flex-direction:column;gap:8px;text-align:left}\\n.pxk-ref__k{font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#01CDF3}\\n.pxk-ref b{font-family:Sora,system-ui,sans-serif;font-size:19px;line-height:1.3;color:#fff;font-weight:600}\\n.pxk-ref .pxk-link{margin-top:auto;color:#fff!important}\\n.pxk--navy .pxk-cta-line .pxk-link{color:#01CDF3!important}\\n.pxk-note{font-size:12.5px;color:rgba(255,255,255,.6);text-align:center;max-width:820px;margin:16px auto 0}\\n.pxk--tighthead{padding-bottom:0!important}\\n@media(max-width:991px){.pxk-grid2,.pxk-band{grid-template-columns:1fr}.pxk-band{padding:28px 24px;gap:16px}}\\n@media(max-width:575px){.pxk-ref{grid-template-columns:1fr}.pxk-ref img{height:180px}}\\n.pxk-step .pxk-n{width:30px;height:30px;flex:0 0 30px;display:inline-flex;align-items:center;justify-content:center;border-radius:50%;background:#01CDF3;color:#082D4A;font-size:13px;font-weight:700}\\n/* ===== /pxk3 ===== */</style>"}, "type": "html", "style": {"paddingTop": "none", "hideOnMobile": false, "hideOnDesktop": false, "paddingBottom": "none"}}, {"id": "b-al4gwn0e", "data": {"html": "<div class=\\"px-ultra-zig-list\\"><article class=\\"px-ultra-zig px-ultra-zig--flip\\">\\n  <div class=\\"px-ultra-zig__copy\\">\\n    <span class=\\"px-ultra-zig__num\\">Preuve terrain</span>\\n    <h2 class=\\"px-ultra-zig__title\\">535 kW récupérés sur une centrale froid</h2>\\n    <p class=\\"px-ultra-zig__lead\\">Chez Carrefour Market, la chaleur fatale du froid chauffe le magasin. Le projet a été engagé sous contrat de performance énergétique.</p>\\n    <ul class=\\"px-ultra-zig__list\\"><li>Puissance récupérée : 535 kW</li><li>30,6 GWh cumac estimés*</li><li>Objectif contractuel −40 %</li></ul>\\n    <a class=\\"px-ultra-zig__more\\" href=\\"/realisations/carrefour-market-recuperation-de-chaleur/\\">Voir la réalisation <span aria-hidden=\\"true\\">→</span></a>\\n  </div>\\n  <a class=\\"px-ultra-zig__card\\" href=\\"/realisations/carrefour-market-recuperation-de-chaleur/\\">\\n    <div class=\\"px-ultra-zig__card-media\\"><img src=\\"/themes/ultra-s/images/pexen/drive-recuperateur-de-chaleur.webp\\" alt=\\"Récupérateur de chaleur\\" loading=\\"lazy\\" width=\\"640\\" height=\\"400\\" /></div>\\n    <div class=\\"px-ultra-zig__card-body\\">\\n      <p class=\\"px-ultra-zig__card-tag\\">Grande distribution</p>\\n      <h3 class=\\"px-ultra-zig__card-title\\">Carrefour Market : récupération de chaleur</h3>\\n      <div class=\\"px-ultra-zig__card-metrics\\"><span>535 kW</span><span>30,6 GWh cumac*</span></div>\\n    </div>\\n  </a>\\n</article></div>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-1v937wxh", "data": {"intro": "", "items": [{"id": "c-c2qm3u8b", "link": "", "tags": [], "text": "Chaleur extraite des meubles et chambres froides, augmentée de l’énergie des compresseurs, rejetée au condenseur.", "image": "/themes/ultra-s/images/pexen/recuperation-de-chaleur-sur-groupe-froid-installee-par-pexen.webp", "title": "Groupe de production de froid", "imageAlt": "Groupe de production de froid", "linkLabel": ""}, {"id": "c-p2ewti2x", "link": "", "tags": [], "text": "La quasi-totalité de l’électricité absorbée se transforme en chaleur récupérable sur le circuit d’huile ou l’air de refroidissement.", "image": "/themes/ultra-s/images/pexen/efficacite-energetique-industrielle-pexen.webp", "title": "Compresseur d’air", "imageAlt": "Compresseur d’air", "linkLabel": ""}, {"id": "c-64avs4xl", "link": "", "tags": [], "text": "Fumées, eaux de refroidissement, buées et eaux de lavage : chaleur fatale à valoriser ou à rehausser.", "image": "/themes/ultra-s/images/pexen/chaufferie-vapeur-d-un-site-industriel-efficacite-energetique-industrielle.webp", "title": "Process industriels", "imageAlt": "Process industriels", "linkLabel": ""}, {"id": "c-pktbtcth", "link": "", "tags": [], "text": "Douches et lavages des bâtiments tertiaires : récupération instantanée sur l’évacuation.", "image": "/themes/ultra-s/images/pexen/installation-technique.webp", "title": "Eaux grises", "imageAlt": "Eaux grises", "linkLabel": ""}], "style": "hoverDark", "title": "D’où vient la chaleur récupérable", "columns": 2, "eyebrow": "Sources", "headerLinkLabel": ""}, "type": "cards", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-jjhn6lwp", "data": {"intro": "", "items": [{"id": "c-mcnfqlu7", "link": "", "tags": ["BAT-TH-139", "IND-UT-117"], "text": "Un échangeur placé en sortie de compresseur alimente un réseau d’eau chaude ou une batterie de traitement d’air. Le dimensionnement est validé par une étude datée et signée, exigée pour les CEE. Durée de vie conventionnelle : 14 ans.", "image": "/themes/ultra-s/images/pexen/recuperation-de-chaleur-groupe-froid-pexen.webp", "title": "Sur groupe de production de froid", "imageAlt": "Sur groupe de production de froid", "linkLabel": ""}, {"id": "c-25f7et6h", "link": "", "tags": ["IND-UT-103"], "text": "La chaleur du circuit d’huile ou de l’air de refroidissement préchauffe l’eau ou chauffe un atelier voisin.", "image": "/themes/ultra-s/images/pexen/drive-recuperateur-de-chaleur.webp", "title": "Sur compresseur d’air", "imageAlt": "Sur compresseur d’air", "linkLabel": ""}, {"id": "c-xr1yyfgj", "link": "", "tags": ["IND-UT-137"], "text": "Quand la chaleur disponible est trop basse en température (25 à 40 °C), une pompe à chaleur la relève au niveau requis par le process ou le réseau de chauffage.", "image": "/themes/ultra-s/images/pexen/pompe-a-chaleur-tertiaire-pexen.webp", "title": "Pompe à chaleur en rehausse de chaleur fatale", "imageAlt": "Pompe à chaleur en rehausse de chaleur fatale", "linkLabel": ""}, {"id": "c-5g59a663", "link": "", "tags": ["BAT-TH-154"], "text": "Un échangeur sur l’évacuation des douches préchauffe l’eau froide entrante. Adapté aux établissements de santé, aux salles de sport et aux hôtels.", "image": "/themes/ultra-s/images/pexen/installation-technique.webp", "title": "Récupération instantanée sur eaux grises", "imageAlt": "Récupération instantanée sur eaux grises", "linkLabel": ""}], "style": "hoverDark", "title": "Nos solutions de valorisation de la chaleur", "columns": 2, "eyebrow": "Solutions", "headerLinkLabel": ""}, "type": "cards", "style": {"background": "soft", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-cqbn3ie1", "data": {"cards": [{"id": "ck-u6oh1nfm", "icon": "fa-check", "title": "", "entries": [{"id": "e-jh4jvrt0", "title": "Chauffage : surface de vente, bureaux ou ateliers."}, {"id": "e-ibt5mx7p", "title": "Eau chaude sanitaire et préchauffage de l’air neuf."}, {"id": "e-p5w94b88", "title": "Process : eau de lavage et nettoyage en agroalimentaire."}, {"id": "e-68i96vl1", "title": "Préchauffage de l’eau d’appoint d’une chaudière vapeur."}]}], "intro": "", "title": "Où réutiliser la chaleur récupérée", "eyebrow": "Usages"}, "type": "checklist", "style": {"background": "soft", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-63zf0y1d", "data": {"html": "<p>Le projet tient si trois conditions sont réunies : des besoins de chaleur simultanés aux rejets, une distance courte entre source et usage, une régulation du froid qui reste prioritaire. Notre étude croise les courbes de rejet et de besoin heure par heure avant de dimensionner l’échangeur et le stockage.</p>", "image": "/themes/ultra-s/images/pexen/recuperation-de-chaleur-sur-la-centrale-froid-de-carrefour-market.webp", "ratio": "landscape", "title": "Les conditions d'un projet rentable", "bullets": [], "buttons": [], "eyebrow": "Rentabilité", "autoplay": false, "imageAlt": "Les conditions d'un projet rentable", "highlight": "", "mediaType": "image", "mediaStyle": "rounded", "videoSource": "file", "mediaPosition": "right"}, "type": "textMedia", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-qk03r1gg", "data": {"html": "<p>La puissance valorisable dépend de la température de condensation du groupe et du mode de captage. La désurchauffe capte une fraction à haute température (ECS) ; la condensation totale capte l’essentiel des rejets à plus basse température (chauffage). Un ballon tampon lisse l’écart entre production et besoin. La régulation donne toujours la priorité au froid.</p>", "image": "/themes/ultra-s/images/pexen/recuperation-de-chaleur-groupe-froid-pexen.webp", "ratio": "landscape", "title": "Dimensionner l'échangeur et le stockage", "bullets": [], "buttons": [], "eyebrow": "Dimensionnement", "autoplay": false, "imageAlt": "Dimensionner l'échangeur et le stockage", "highlight": "", "mediaType": "image", "mediaStyle": "rounded", "videoSource": "file", "mediaPosition": "left"}, "type": "textMedia", "style": {"background": "soft", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-rd4iga4s", "data": {"html": "<p>Le volume de kWh cumac dépend du secteur, de la zone climatique, de l’usage de la chaleur et de la puissance thermique récupérée. L’étude datée et signée fixe cette puissance : c’est la pièce contrôlée.</p><p><a href=\\"/expertises/financement-cee-reglementation/\\">Réglementation et financement CEE</a></p>", "image": "/themes/ultra-s/images/pexen/cee-tertiaire.webp", "ratio": "landscape", "title": "Comment se calcule la prime BAT-TH-139", "bullets": [], "buttons": [], "eyebrow": "CEE", "autoplay": false, "imageAlt": "Comment se calcule la prime BAT-TH-139", "highlight": "", "mediaType": "image", "mediaStyle": "rounded", "videoSource": "file", "mediaPosition": "right"}, "type": "textMedia", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-2mcywwk3", "data": {"html": "<h2>Réalisations liées</h2><div class=\\"px-ultra-case-list\\"><a class=\\"px-ultra-case-card\\" href=\\"/realisations/carrefour-market-recuperation-de-chaleur/\\">\\n    <div class=\\"px-ultra-case-card__media\\"><img src=\\"/themes/ultra-s/images/pexen/recuperation-de-chaleur-sur-la-centrale-froid-de-carrefour-market.webp\\" alt=\\"Récupération de chaleur sur la centrale froid de Carrefour Market\\" loading=\\"lazy\\" width=\\"640\\" height=\\"400\\" /></div>\\n    <div class=\\"px-ultra-case-card__body\\">\\n      <p class=\\"px-ultra-case-card__meta\\">Réalisation · Île-de-France · Grande distribution</p>\\n      <h3 class=\\"px-ultra-case-card__title\\">Carrefour Market : récupération sur centrale froid</h3>\\n      <p class=\\"px-ultra-case-card__enjeu\\">Récupération de chaleur sur la centrale froid, en complément de la régulation et de l’isolation.</p>\\n      <p class=\\"px-ultra-case-card__result\\">30,6 GWh cumac estimés*</p>\\n      <span class=\\"px-ultra-case-card__cta\\">Voir le projet <span aria-hidden=\\"true\\">→</span></span>\\n    </div>\\n  </a>\\n<a class=\\"px-ultra-case-card\\" href=\\"/realisations/intermarche-sortie-du-fioul/\\">\\n    <div class=\\"px-ultra-case-card__media\\"><img src=\\"/themes/ultra-s/images/pexen/recuperation-de-chaleur-sur-groupe-froid-installee-par-pexen.webp\\" alt=\\"Récupération de chaleur Intermarché\\" loading=\\"lazy\\" width=\\"640\\" height=\\"400\\" /></div>\\n    <div class=\\"px-ultra-case-card__body\\">\\n      <p class=\\"px-ultra-case-card__meta\\">Réalisation · Bourgogne-Franche-Comté · Grande distribution</p>\\n      <h3 class=\\"px-ultra-case-card__title\\">Intermarché : récupération couplée à la PAC</h3>\\n      <p class=\\"px-ultra-case-card__enjeu\\">Récupération de chaleur couplée à une pompe à chaleur pour sortir du fioul.</p>\\n      <p class=\\"px-ultra-case-card__result\\">14,8 GWh cumac estimés*</p>\\n      <span class=\\"px-ultra-case-card__cta\\">Voir le projet <span aria-hidden=\\"true\\">→</span></span>\\n    </div>\\n  </a></div><p><a href=\\"/realisations/\\">Voir nos réalisations →</a></p>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-dz97s6s0", "data": {"html": "<p class=\\"px-ultra-legal-note text-xs text-slate-500\\">* Estimation calculée selon les fiches d’opérations standardisées CEE mobilisées (arrêté du 22 décembre 2014 modifié). Le kWh cumac cumule et actualise les économies sur la durée de vie conventionnelle des équipements ; il ne mesure pas les consommations réelles.</p>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-f2hmmvta", "data": {"text": "Un ingénieur PEXEN étudie votre site, évalue le gisement et vous répond sous 48 h ouvrées.", "title": "Un projet ? Parlons-en.", "layout": "centered", "buttons": [{"id": "btn-83hsohjs", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-0a5l7kxu", "icon": "phone", "link": "tel:+33141935280", "label": "01 41 93 52 80", "variant": "secondary"}], "variant": "dark"}, "type": "cta", "style": {"background": "navy", "paddingTop": "lg", "hideOnMobile": true, "hideOnDesktop": true, "paddingBottom": "lg"}}, {"id": "b-pxs-css", "data": {"html": "<style>/* ===== pxs (pages Solutions v2) ===== */\\n.pxs{--n:#082D4A;--c:#01CDF3;--p:#009FCC;--pd:#00769A;--ice:#EEF4FA;--b:#D5E1E6;--m:#5A6B7B;text-align:left;color:#3E5163;font-family:Figtree,system-ui,sans-serif}\\n.pxs *{box-sizing:border-box}\\n.pxs-sec{padding:64px 0;scroll-margin-top:210px;position:relative}\\n.pxs-sec--ice{background:linear-gradient(180deg,#F4F7FA 0%,#EAF1F6 100%)}\\n.pxs-sec--navy{background:radial-gradient(circle at 85% 0%,rgba(1,205,243,.16),transparent 45%),var(--n);color:rgba(255,255,255,.82)}\\n.pxs-sec--tight{padding:40px 0}\\n.pxs-c{max-width:1296px;margin:0 auto;padding:0 24px}\\n.pxs-eb{display:inline-flex;align-items:center;gap:8px;font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--pd);background:#E3F7FC;border-radius:30px;padding:6px 14px}\\n.pxs-eb i{font-style:normal;font-family:Sora,system-ui,sans-serif;color:var(--n)}\\n.pxs-sec--navy .pxs-eb{background:rgba(1,205,243,.14);color:var(--c)}.pxs-sec--navy .pxs-eb i{color:#fff}\\n.pxs h2{font-family:Sora,system-ui,sans-serif;font-weight:700;color:var(--n);font-size:clamp(26px,2.5vw,36px);line-height:1.18;letter-spacing:-.01em;margin:14px 0 12px}\\n.pxs h3{font-family:Sora,system-ui,sans-serif;font-weight:600;color:var(--n);font-size:17.5px;line-height:1.3;margin:0 0 6px}\\n.pxs-sec--navy h2,.pxs-sec--navy h3{color:#fff}\\n.pxs p{margin:0 0 12px;font-size:16px;line-height:1.7}\\n.pxs-head{max-width:780px;margin:0 0 28px}\\n.pxs-head--c{margin:0 auto 36px;text-align:center}\\n.pxs-lead{font-size:17px!important;color:var(--m)}\\n.pxs-sec--navy .pxs-lead{color:rgba(255,255,255,.75)}\\n.pxs-clair{display:flex;gap:14px;align-items:flex-start;background:#fff;border:1px solid var(--b);border-left:4px solid var(--c);border-radius:12px;padding:16px 18px;margin:16px 0 20px;box-shadow:0 8px 22px rgba(8,45,74,.05)}\\n.pxs-clair b{flex:0 0 auto;font-size:10.5px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:#fff;background:var(--n);border-radius:6px;padding:5px 9px;margin-top:2px}\\n.pxs-clair span{font-size:16px;line-height:1.55;color:var(--n);font-weight:500}\\n.pxs-head--c .pxs-clair{text-align:left;max-width:720px;margin:16px auto 0}\\n.pxs-2{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:center}\\n.pxs-2--57{grid-template-columns:5fr 7fr}.pxs-2--75{grid-template-columns:7fr 5fr}.pxs-2--top{align-items:start}\\n.pxs-tags{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}\\n.pxs-tag{display:inline-block;font-size:12.5px;font-weight:700;color:var(--pd);background:#E3F7FC;border-radius:6px;padding:6px 10px;font-style:normal}\\n.pxs-sec--navy .pxs-tag{background:rgba(1,205,243,.14);color:var(--c)}\\n.pxs-link{display:inline-flex;align-items:center;gap:8px;font-weight:700;color:var(--pd)!important;text-decoration:none!important}\\n.pxs-link:hover{gap:12px}\\n.pxs-sec--navy .pxs-link{color:var(--c)!important}\\n.pxs-btn{display:inline-flex;align-items:center;gap:10px;height:48px;padding:0 26px;border-radius:6px;background:var(--c);color:var(--n)!important;font-weight:600;font-size:16px;text-decoration:none!important;transition:transform .2s,box-shadow .2s}\\n.pxs-btn:hover{transform:translateY(-2px);box-shadow:0 12px 26px rgba(1,205,243,.35)}\\n.pxs-btn--ghost{background:transparent;border:1px solid rgba(8,45,74,.35);color:var(--n)!important}\\n.pxs-sec--navy .pxs-btn--ghost,.pxs-cta .pxs-btn--ghost{border-color:rgba(255,255,255,.45);color:#fff!important}\\n.pxs-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}\\n.pxs-actions--c{justify-content:center}\\n.pxs-checks{list-style:none;padding:0;margin:8px 0 0;display:grid;gap:10px}\\n.pxs-checks li{display:flex;gap:12px;align-items:flex-start;font-size:15.5px;line-height:1.5;color:var(--n)}\\n.pxs-checks li::before{content:\\"\\\\f00c\\";font-family:\\"Font Awesome 5 Free\\",\\"FontAwesome\\";font-weight:900;flex:0 0 24px;height:24px;border-radius:50%;background:#E3F7FC;color:var(--pd);font-size:11px;display:grid;place-items:center;margin-top:1px}\\n.pxs-sec--navy .pxs-checks li{color:#fff}\\n.pxs-note{font-size:13.5px!important;color:var(--m);background:rgba(8,45,74,.04);border-radius:8px;padding:10px 14px;margin-top:14px!important}\\n.pxs-miles{display:grid;gap:12px;position:relative}\\n.pxs-mile{display:grid;grid-template-columns:150px 1fr;gap:18px;align-items:center;background:#fff;border:1px solid var(--b);border-radius:14px;padding:18px 22px;box-shadow:0 10px 26px rgba(8,45,74,.05);transition:transform .2s,border-color .2s}\\n.pxs-mile:hover{transform:translateX(4px);border-color:var(--c)}\\n.pxs-mile__k{font-family:Sora,system-ui,sans-serif;font-weight:700;font-size:26px;color:var(--n);line-height:1}\\n.pxs-mile__k small{display:block;font-family:Figtree,system-ui,sans-serif;font-size:12.5px;color:var(--m);font-weight:600;margin-top:6px;line-height:1.3}\\n.pxs-mile__d strong{display:block;font-size:12px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--pd);margin-bottom:3px}\\n.pxs-mile__d span{font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:18px;color:var(--n)}\\n.pxs-mile--on{background:var(--n);border-color:var(--n)}\\n.pxs-mile--on .pxs-mile__k{color:var(--c)}.pxs-mile--on .pxs-mile__k small{color:rgba(255,255,255,.7)}\\n.pxs-mile--on .pxs-mile__d strong{color:var(--c)}.pxs-mile--on .pxs-mile__d span{color:#fff}\\n.pxs-scale{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin:6px 0 8px}\\n.pxs-scale>div{border-radius:10px;padding:12px 8px;text-align:center;font-family:Sora,system-ui,sans-serif;font-weight:700;font-size:24px;color:#fff;position:relative}\\n.pxs-scale small{display:block;font-family:Figtree,system-ui,sans-serif;font-size:11px;font-weight:700;margin-top:3px;opacity:.9}\\n.pxs-scale .s-a{background:#00769A}.pxs-scale .s-b{background:#009FCC}.pxs-scale .s-c{background:#9DB4C3}.pxs-scale .s-d{background:#C7D4DD}\\n.pxs-scale .s-on{box-shadow:0 0 0 3px #fff,0 0 0 5px var(--c)}\\n.pxs-scale-cap{font-size:13.5px!important;color:var(--m)}\\n.pxs-stats{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:18px}\\n.pxs-stat{background:#fff;border:1px solid var(--b);border-radius:14px;padding:16px 18px;position:relative;overflow:hidden}\\n.pxs-stat::before{content:\\"\\";position:absolute;left:0;top:0;bottom:0;width:4px;background:linear-gradient(180deg,var(--c),var(--p))}\\n.pxs-stat b{display:block;font-family:Sora,system-ui,sans-serif;font-size:30px;line-height:1.05;color:var(--n)}\\n.pxs-stat span{font-size:14px;color:var(--m)}\\n.pxs-stats-cap{font-size:12.5px!important;color:var(--m);margin-top:8px!important}\\n.pxs-tiles{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}\\n.pxs-tiles--3{grid-template-columns:repeat(3,1fr)}\\n.pxs-tile{display:flex;gap:14px;align-items:flex-start;background:#fff;border:1px solid var(--b);border-radius:14px;padding:18px;transition:transform .2s,border-color .2s,box-shadow .2s}\\n.pxs-tile:hover{transform:translateY(-3px);border-color:var(--c);box-shadow:0 14px 30px rgba(8,45,74,.08)}\\n.pxs-tile p{font-size:14.5px!important;line-height:1.5;margin:0!important;color:var(--m)}\\n.pxs-ico{flex:0 0 46px;width:46px;height:46px;border-radius:12px;background:linear-gradient(135deg,#E3F7FC,#C9EEF8);color:var(--pd);display:grid;place-items:center;font-size:18px}\\n.pxs-sec--navy .pxs-ico{background:rgba(1,205,243,.14);color:var(--c)}\\n.pxs-proc{display:grid;grid-template-columns:repeat(var(--k,4),minmax(0,1fr));gap:18px;position:relative}\\n.pxs-proc::before{content:\\"\\";position:absolute;top:46px;left:calc(100%/var(--k,4)/2);right:calc(100%/var(--k,4)/2);height:2px;background:repeating-linear-gradient(90deg,var(--c) 0 10px,transparent 10px 18px);opacity:.7}\\n.pxs-step{position:relative;background:#fff;border:1px solid var(--b);border-radius:16px;padding:24px 22px 22px;transition:transform .2s,border-color .2s}\\n.pxs-step:hover{transform:translateY(-4px);border-color:var(--c)}\\n.pxs-step__n{position:relative;z-index:1;width:46px;height:46px;border-radius:50%;background:var(--c);color:var(--n);font-family:Sora,system-ui,sans-serif;font-weight:700;font-size:17px;display:grid;place-items:center;margin-bottom:16px;box-shadow:0 0 0 6px var(--n)}\\n.pxs-step p{font-size:14.5px!important;line-height:1.55;margin:0!important;color:var(--m)}\\n.pxs-sec--navy .pxs-step{background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.14)}\\n.pxs-sec--navy .pxs-step p{color:rgba(255,255,255,.75)}\\n.pxs-step .pxs-tag{margin-top:12px}\\n.pxs-cta{display:grid;grid-template-columns:7fr 5fr;border-radius:20px;overflow:hidden;background:radial-gradient(circle at 0% 100%,rgba(1,205,243,.22),transparent 50%),var(--n);box-shadow:0 26px 54px rgba(8,45,74,.2);color:rgba(255,255,255,.82)}\\n.pxs-cta__t{padding:44px 48px}\\n.pxs-cta__t h2{color:#fff;margin-top:12px}\\n.pxs-cta__t p{color:rgba(255,255,255,.78)}\\n.pxs-cta__img{position:relative;min-height:300px;margin:0}\\n.pxs-cta__img img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\\n.pxs-cta__img::before{content:\\"\\";position:absolute;inset:0;background:linear-gradient(90deg,var(--n) 0%,rgba(8,45,74,0) 45%);z-index:1}\\n.pxs-cta__badge{position:absolute;right:20px;bottom:20px;z-index:2;background:#fff;color:var(--n);border-radius:12px;padding:12px 16px;font-weight:700;font-size:14px;display:flex;gap:10px;align-items:center;box-shadow:0 14px 30px rgba(0,0,0,.2)}\\n.pxs-cta__badge i{color:var(--pd)}\\n.pxs-photo{position:relative;margin:0;border-radius:18px;overflow:visible}\\n.pxs-photo img{width:100%;height:360px;object-fit:cover;border-radius:18px;display:block;box-shadow:0 22px 46px rgba(8,45,74,.16)}\\n.pxs-photo figcaption{position:absolute;left:-18px;bottom:22px;background:#fff;border-radius:12px;padding:14px 18px;box-shadow:0 16px 34px rgba(8,45,74,.16);max-width:270px;font-size:14px;line-height:1.4;color:var(--n);font-weight:600;border-left:4px solid var(--c)}\\n.pxs-photo figcaption small{display:block;font-size:11px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--pd);margin-bottom:3px}\\n.pxs-ref{display:block;position:relative;border-radius:18px;overflow:hidden;min-height:360px;text-decoration:none!important;box-shadow:0 22px 46px rgba(8,45,74,.18)}\\n.pxs-ref img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .5s}\\n.pxs-ref:hover img{transform:scale(1.04)}\\n.pxs-ref::after{content:\\"\\";position:absolute;inset:0;background:linear-gradient(180deg,rgba(8,45,74,0) 30%,rgba(8,45,74,.92) 100%)}\\n.pxs-ref>div{position:absolute;left:0;right:0;bottom:0;z-index:1;padding:24px 26px}\\n.pxs-ref small{display:block;font-size:11.5px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--c);margin-bottom:6px}\\n.pxs-ref b{display:block;font-family:Sora,system-ui,sans-serif;font-size:20px;line-height:1.3;color:#fff;font-weight:600;margin-bottom:10px}\\n.pxs-ref span{color:#fff;font-weight:700;font-size:14.5px}\\n.pxs-refs{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:18px}\\n.pxs-refs .pxs-ref{min-height:300px}\\n.pxs-cards{display:flex;flex-wrap:wrap;justify-content:center;gap:18px}\\n.pxs-cards>*{flex:0 1 calc((100% - 36px)/3)}\\n.pxs-cards--2>*{flex-basis:calc((100% - 18px)/2)}\\n.pxs-card{position:relative;display:flex;flex-direction:column;background:#fff;border:1px solid var(--b);border-radius:16px;overflow:hidden;transition:transform .25s,box-shadow .25s,border-color .25s}\\n.pxs-card:hover{transform:translateY(-4px);border-color:var(--c);box-shadow:0 18px 36px rgba(8,45,74,.1)}\\n.pxs-card>img{width:100%;height:170px;object-fit:cover;display:block}\\n.pxs-card__b{padding:20px 22px 22px;display:flex;flex-direction:column;gap:6px;flex:1}\\n.pxs-card__b p{font-size:14.5px!important;line-height:1.55;margin:0!important;color:var(--m)}\\n.pxs-card__b .pxs-tags{margin-top:auto;padding-top:12px}\\n.pxs-card__n{position:absolute;top:14px;left:14px;width:34px;height:34px;border-radius:50%;background:var(--c);color:var(--n);font-family:Sora,system-ui,sans-serif;font-weight:700;font-size:14px;display:grid;place-items:center;z-index:1}\\n.pxs-diag{background:#fff;border:1px solid var(--b);border-radius:18px;padding:22px;box-shadow:0 16px 36px rgba(8,45,74,.07);margin:0}\\n.pxs-diag svg{display:block;width:100%;height:auto}\\n.pxs-diag figcaption{font-size:13px;color:var(--m);margin-top:10px;text-align:center}\\n@supports (animation-timeline:view()){\\n.pxs-rv{animation:pxsIn linear both;animation-timeline:view();animation-range:entry 0% entry 30%}\\n@keyframes pxsIn{from{opacity:0;transform:translateY(28px)}to{opacity:1;transform:none}}\\n}\\n@media (prefers-reduced-motion:reduce){.pxs-rv{animation:none!important}}\\n.row:has(>[class*=\\"col-\\"]:nth-child(5):last-child){justify-content:center}\\n@media(max-width:1100px){.pxs-tiles--3{grid-template-columns:repeat(2,1fr)}}\\n@media(max-width:991px){.pxs-2,.pxs-2--57,.pxs-2--75,.pxs-cta{grid-template-columns:1fr}.pxs-2{gap:32px}.pxs-proc{grid-template-columns:1fr 1fr}.pxs-proc::before{display:none}.pxs-cards>*{flex-basis:calc((100% - 18px)/2)}.pxs-cta__img{min-height:220px}.pxs-cta__img::before{background:linear-gradient(180deg,var(--n) 0%,rgba(8,45,74,0) 40%)}.pxs-photo figcaption{left:12px}.pxs-sec{padding:48px 0}}\\n@media(max-width:575px){.pxs-proc,.pxs-tiles,.pxs-tiles--3,.pxs-stats{grid-template-columns:1fr}.pxs-cards>*{flex-basis:100%}.pxs-mile{grid-template-columns:1fr;gap:8px}.pxs-cta__t{padding:30px 24px}}\\n/* v3 : hub, étiquette énergie, gain, flux, correspondances */\\n.pxs-hub{display:grid;grid-template-columns:1fr 150px 1fr;gap:12px 26px;align-items:center}\\n.pxs-hub__col{display:grid;gap:12px}\\n.pxs-hub .pxs-tile{position:relative;padding:12px 14px;gap:12px}.pxs-hub .pxs-tile p{font-size:13.5px!important}\\n.pxs-hub .pxs-tile h3{font-size:16px}\\n.pxs-hub .pxs-ico{flex-basis:36px;width:36px;height:36px;font-size:15px;border-radius:10px}\\n.pxs-hub__col--l .pxs-tile::after,.pxs-hub__col--r .pxs-tile::after{content:\\"\\";position:absolute;top:50%;width:26px;height:2px}\\n.pxs-hub__col--l .pxs-tile::after{right:-27px;background:linear-gradient(90deg,#D5E1E6,#01CDF3)}\\n.pxs-hub__col--r .pxs-tile::after{left:-27px;background:linear-gradient(270deg,#D5E1E6,#01CDF3)}\\n.pxs-core{width:150px;height:150px;border-radius:50%;background:radial-gradient(circle at 30% 25%,#12507B,#082D4A 70%);color:#fff;display:grid;place-content:center;text-align:center;position:relative;margin:0 auto;box-shadow:0 0 0 10px rgba(1,205,243,.12),0 0 0 22px rgba(1,205,243,.06),0 24px 48px rgba(8,45,74,.28)}\\n.pxs-core b{font-family:Sora,system-ui,sans-serif;font-size:28px;line-height:1;color:#01CDF3;display:block;margin-bottom:6px}\\n.pxs-core span{font-size:12px;line-height:1.35;padding:0 18px;display:block;color:rgba(255,255,255,.82)}\\n.pxs-core::after{content:\\"\\";position:absolute;inset:-10px;border-radius:50%;border:2px solid rgba(1,205,243,.55);animation:pxsPulse 2.8s ease-out infinite}\\n@keyframes pxsPulse{from{transform:scale(.94);opacity:.9}to{transform:scale(1.28);opacity:0}}\\n.pxs-hub__lbl{grid-column:1/-1;display:flex;justify-content:space-between;font-size:11.5px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pd);margin-bottom:-2px}\\n.pxs-label{display:grid;gap:6px;margin:8px 0 10px}\\n.pxs-label>div{display:flex;align-items:center;gap:12px;height:40px;padding-left:14px;color:#fff;font-family:Sora,system-ui,sans-serif;font-weight:700;font-size:19px;clip-path:polygon(0 0,calc(100% - 18px) 0,100% 50%,calc(100% - 18px) 100%,0 100%);border-radius:8px 0 0 8px}\\n.pxs-label small{font-family:Figtree,system-ui,sans-serif;font-size:12.5px;font-weight:700;opacity:.95}\\n.pxs-label .l-a{width:58%;background:#00769A}.pxs-label .l-b{width:70%;background:#009FCC}.pxs-label .l-c{width:82%;background:#A9BDCB}.pxs-label .l-d{width:94%;background:#CBD7DF;color:#5A6B7B}\\n.pxs-gain{display:grid;grid-template-columns:auto 1fr 1fr;gap:16px;align-items:center;background:radial-gradient(circle at 100% 0,rgba(1,205,243,.25),transparent 55%),var(--n);border-radius:16px;padding:18px 22px;margin-top:16px;color:#fff}\\n.pxs-gain__cls{display:flex;align-items:center;gap:8px;font-family:Sora,system-ui,sans-serif;font-weight:700;font-size:15px;white-space:nowrap}\\n.pxs-gain__cls em{font-style:normal;width:34px;height:34px;border-radius:8px;display:grid;place-items:center;font-size:17px}\\n.pxs-gain__cls em:first-child{background:#A9BDCB}.pxs-gain__cls em:last-child{background:#00769A;box-shadow:0 0 0 2px #01CDF3}\\n.pxs-gain__cls i{color:#01CDF3}\\n.pxs-gain__n b{display:block;font-family:Sora,system-ui,sans-serif;font-size:30px;line-height:1;color:#01CDF3}\\n.pxs-gain__n span{font-size:13px;color:rgba(255,255,255,.78)}\\n.pxs-flow{display:flex;align-items:center;gap:14px;background:#fff;border:1px solid var(--b);border-radius:16px;padding:18px 20px;margin-top:18px;box-shadow:0 12px 28px rgba(8,45,74,.06)}\\n.pxs-flow__in,.pxs-flow__out{text-align:center;flex:1}\\n.pxs-flow b{display:block;font-family:Sora,system-ui,sans-serif;font-size:30px;line-height:1;color:var(--n)}\\n.pxs-flow__out b{color:var(--pd)}\\n.pxs-flow span{font-size:13px;color:var(--m)}\\n.pxs-flow__mid{flex:0 0 auto;display:flex;align-items:center;gap:10px;color:var(--c);font-size:20px}\\n.pxs-flow__mid em{font-style:normal;background:var(--n);color:#fff;border-radius:10px;padding:10px 14px;font-weight:700;font-size:14px}\\n.pxs-map{display:grid;gap:10px}\\n.pxs-map>div{display:grid;grid-template-columns:1fr 44px 1fr;align-items:stretch}\\n.pxs-map__a,.pxs-map__b{border-radius:12px;padding:14px 16px;font-size:15px;line-height:1.45;display:flex;gap:12px;align-items:center}\\n.pxs-map__a{background:#fff;border:1px solid var(--b);color:var(--n)}\\n.pxs-map__a::before{content:\\"\\\\f071\\";font-family:\\"Font Awesome 5 Free\\",\\"FontAwesome\\";font-weight:900;color:#C77B12;flex:0 0 auto}\\n.pxs-map__b{background:var(--n);color:#fff;font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:15.5px}\\n.pxs-map__b::before{content:\\"\\\\f00c\\";font-family:\\"Font Awesome 5 Free\\",\\"FontAwesome\\";font-weight:900;color:var(--c);flex:0 0 auto}\\n.pxs-map__x{display:grid;place-items:center;color:var(--c);font-size:18px}\\n.pxs-map__h{display:grid;grid-template-columns:1fr 44px 1fr;font-size:11.5px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pd);margin-bottom:2px}\\n.pxs-map__h span:last-child{grid-column:3}\\n.pxs-heat{position:relative;margin:18px 0 6px}\\n.pxs-heat__bar{height:14px;border-radius:10px;background:linear-gradient(90deg,#D9480F,#F59F00 40%,#9DB4C3 70%,#01CDF3)}\\n.pxs-heat__pts{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:14px}\\n.pxs-heat__pts>div{background:#fff;border:1px solid var(--b);border-radius:12px;padding:12px 14px}\\n.pxs-heat__pts b{display:block;font-family:Sora,system-ui,sans-serif;font-size:14.5px;color:var(--n);margin-bottom:4px}\\n.pxs-heat__pts span{font-size:13.5px;color:var(--m);line-height:1.45;display:block}\\n.pxs-heat__pts em{font-style:normal;display:inline-block;font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:#fff;border-radius:6px;padding:3px 8px;margin-bottom:8px}\\n.pxs-rows2{display:grid;gap:8px}\\n.pxs-rows2>div{display:grid;grid-template-columns:220px 1fr;gap:16px;align-items:center;background:#fff;border:1px solid var(--b);border-radius:12px;padding:12px 16px}\\n.pxs-rows2 b{font-family:Sora,system-ui,sans-serif;font-size:14.5px;color:var(--n)}\\n.pxs-rows2 span{font-size:14.5px;color:var(--m)}\\n.pxs-cards--4>*{flex-basis:calc((100% - 54px)/4)}\\n.pxs-card--ico .pxs-card__b{padding-top:22px}\\n.pxs-card--ico .pxs-ico{margin-bottom:8px}\\n.pxs-dark{background:radial-gradient(circle at 100% 0,rgba(1,205,243,.2),transparent 50%),var(--n);color:rgba(255,255,255,.82);border-radius:18px;padding:30px 30px 26px}\\n.pxs-dark h3{color:#fff;font-size:20px}\\n.pxs-dark p{color:rgba(255,255,255,.8)}\\n.pxs-mile__k em{font-style:normal;color:var(--pd)}\\n@media(max-width:991px){.pxs-hub{grid-template-columns:1fr}.pxs-hub .pxs-core{order:-1;margin-bottom:12px}.pxs-hub__col .pxs-tile::after{display:none}.pxs-hub__lbl{display:none}.pxs-gain{grid-template-columns:1fr 1fr}.pxs-gain__cls{grid-column:1/-1}.pxs-cards--4>*{flex-basis:calc((100% - 18px)/2)}.pxs-map>div,.pxs-map__h{grid-template-columns:1fr 30px 1fr}.pxs-heat__pts{grid-template-columns:1fr}.pxs-rows2>div{grid-template-columns:1fr;gap:4px}}\\n@media(max-width:575px){.pxs-map>div{grid-template-columns:1fr}.pxs-map__x{transform:rotate(90deg);height:26px}.pxs-map__h{display:none}.pxs-cards--4>*{flex-basis:100%}.pxs-flow{flex-direction:column}}\\n.pxs-dark .pxs-step{background:rgba(255,255,255,.07);border-color:rgba(255,255,255,.16)}.pxs-dark .pxs-step p{color:#fff!important}\\n\\n/* 5 cartes : les deux dernières centrées */.px-ultra-serv-grid:has(>:nth-child(5):last-child){grid-template-columns:repeat(6,minmax(0,1fr))!important}.px-ultra-serv-grid:has(>:nth-child(5):last-child)>*{grid-column:span 2}.px-ultra-serv-grid:has(>:nth-child(5):last-child)>:nth-child(4){grid-column:2/span 2}@media(max-width:991px){.px-ultra-serv-grid:has(>:nth-child(5):last-child){grid-template-columns:1fr 1fr!important}.px-ultra-serv-grid:has(>:nth-child(5):last-child)>*{grid-column:auto!important}.px-ultra-serv-grid:has(>:nth-child(5):last-child)>:nth-child(5){grid-column:1/-1!important;justify-self:center;max-width:50%}}@media(max-width:575px){.px-ultra-serv-grid:has(>:nth-child(5):last-child){grid-template-columns:1fr!important}.px-ultra-serv-grid:has(>:nth-child(5):last-child)>:nth-child(5){max-width:none}}\\n/* centrage vertical */.pxs-2--top{align-items:center}\\n.pxs-case{display:grid;grid-template-columns:6fr 5fr;gap:0;border-radius:22px;overflow:hidden;background:#fff;box-shadow:0 26px 60px rgba(8,45,74,.14);border:1px solid var(--b)}\\n.pxs-case__img{position:relative;min-height:460px;margin:0}.pxs-case__img img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\\n.pxs-case__img figcaption{position:absolute;left:20px;top:20px;background:var(--n);color:#fff;border-radius:8px;padding:8px 12px;font-size:12px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}\\n.pxs-case__t{padding:40px 44px;display:flex;flex-direction:column;justify-content:center}\\n.pxs-case__t h2{font-size:clamp(24px,2.2vw,32px)}\\n.pxs-case .pxs-stats{grid-template-columns:1fr 1fr}.pxs-case .pxs-stat b{font-size:26px}\\n.pxs-case__chips{display:flex;flex-wrap:wrap;gap:8px;margin:6px 0 4px}.pxs-case__chips span{background:var(--ice);color:var(--n);border:1px solid var(--b);border-radius:30px;padding:7px 14px;font-size:13.5px;font-weight:700}\\n@media(max-width:991px){.pxs-case{grid-template-columns:1fr}.pxs-case__img{min-height:260px}.pxs-case__t{padding:28px 24px}}\\n/* pleine largeur */.pxs-sec,.pxt-sec,.pxt-hero{width:100vw!important;margin-left:calc(50% - 50vw)!important;margin-right:0!important}body{overflow-x:clip}\\n/* ===== /pxs ===== */</style>"}, "type": "html", "style": {"paddingTop": "none", "paddingBottom": "none"}}], "status": "published", "template": "default", "createdAt": "2026-10-21T10:43:13.022Z", "updatedAt": "2026-11-11T17:00:22.099Z", "publishedAt": "2026-10-21T10:43:13.022Z", "contentSource": "cms"}	admin@pexen.fr	2026-11-11 19:18:02.04772+01
