:820px;margin:0 auto 40px!important}\\n\\n.fa-euro-sign::before{content:\\"\\\\f3ed\\"}\\n\\n/* ===== PEXEN · composants maison (pxk) ===== */\\nsection.sec-padding,section.px-ultra-real-sec--standalone,section.px-ultra-ed:has(.px-ultra-ed__title){padding-top:72px!important;padding-bottom:72px!important}\\n@media(max-width:767px){section.sec-padding,section.px-ultra-real-sec--standalone,section.px-ultra-ed:has(.px-ultra-ed__title){padding-top:56px!important;padding-bottom:56px!important}}\\n.sec-intro.mb-5,.px-ultra-ed__title{margin-bottom:36px!important}\\n.pxk{text-align:left;padding:72px 0;font-family:Figtree,system-ui,sans-serif;color:#3a4a5a}\\n.pxk--ice{background:linear-gradient(180deg,#F4F7FA 0%,#EEF3F7 100%)}\\n.pxk--navy{background:#082D4A;color:rgba(255,255,255,.78)}\\n.pxk__c{max-width:1296px;margin:0 auto;padding:0 24px}\\n.pxk-head{text-align:center!important;max-width:820px;margin:0 auto 44px}\\n.pxk-head--left{text-align:left;margin-left:0}\\n.pxk-eyebrow{display:inline-block;padding:5px 20px;border:1px solid #D5E1E6;border-radius:30px;font-size:13px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:#082D4A;margin-bottom:16px}\\n.pxk--navy .pxk-eyebrow{border-color:rgba(255,255,255,.25);color:#fff}\\n.pxk h2{font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:clamp(26px,2.6vw,38px);line-height:1.2;color:#082D4A;margin:0 0 14px;letter-spacing:-.01em}\\n.pxk--navy h2{color:#fff}\\n.pxk h3{font-family:Sora,system-ui,sans-serif;font-weight:600;font-size:19px;line-height:1.3;color:#082D4A;margin:0 0 10px}\\n.pxk p{margin:0 0 12px;line-height:1.65;font-size:15.5px}\\n.pxk-lead{font-size:17px!important;color:#5A6B7B}\\n.pxk-btn{display:inline-flex;align-items:center;gap:10px;height:48px;padding:0 28px;border-radius:6px;border:1px solid #01CDF3;background:#01CDF3;color:#082D4A!important;font-weight:600;font-size:16px;text-decoration:none!important;transition:background .2s,border-color .2s}\\n.pxk-btn:hover{background:#00B8DB;border-color:#00B8DB}\\n.pxk-btn--ghost{background:transparent;border-color:currentColor;color:#082D4A!important}\\n.pxk--navy .pxk-btn--ghost,.pxk-dark .pxk-btn--ghost{color:#fff!important}\\n.pxk-btn--ghost:hover{background:#082D4A;color:#fff!important;border-color:#082D4A}\\n.pxk-link{display:inline-flex;align-items:center;gap:8px;font-weight:600;color:#00769A!important;text-decoration:none!important;border-bottom:1px solid rgba(0,118,154,.35);padding-bottom:2px}\\n.pxk-link:hover{border-color:#00769A}\\n.pxk-ico{display:inline-flex;align-items:center;justify-content:center;width:46px;height:46px;border-radius:12px;background:#E3F7FC;color:#00769A;font-size:19px;flex:0 0 46px}\\n/* Obligations */\\n.pxk-grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}\\n.pxk-card{position:relative;display:flex;flex-direction:column;background:#fff;border:1px solid #D5E1E6;border-radius:16px;padding:30px 28px;box-shadow:0 12px 32px rgba(8,45,74,.06);overflow:hidden}\\n.pxk-card::before{content:\\"\\";position:absolute;left:0;top:0;right:0;height:4px;background:linear-gradient(90deg,#01CDF3,#009FCC)}\\n.pxk-fig{font-family:Sora,system-ui,sans-serif;font-weight:700;font-size:38px;line-height:1;color:#082D4A;margin:6px 0 6px}\\n.pxk-fig small{font-size:15px;font-weight:600;color:#00769A;margin-left:6px}\\n.pxk-figcap{font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:#5A6B7B;margin-bottom:18px;padding-bottom:18px;border-bottom:1px solid #E6EEF2}\\n.pxk-card p{font-size:14.5px;color:#4a5a6a}\\n.pxk-card .pxk-link{margin-top:auto;align-self:flex-start;padding-top:8px}\\n/* Encart plan d'actions */\\n.pxk-plan{display:grid;grid-template-columns:1.05fr 1fr;border-radius:20px;overflow:hidden;box-shadow:0 20px 50px rgba(8,45,74,.14)}\\n.pxk-plan__l{background:#082D4A;padding:48px;color:rgba(255,255,255,.8);text-align:left}\\n.pxk-plan__l h2{color:#fff}\\n.pxk-plan__l .pxk-eyebrow{border-color:rgba(255,255,255,.25);color:#fff}\\n.pxk-p